int _runtimeLevelForMinutes(int totalMinutes) {
  int level = 1;
  int remainingMinutes = totalMinutes;

  while (remainingMinutes >= level * 20) {
    remainingMinutes -= level * 20;

    level++;
  }

  return level;
}

