  State<_AchievementUnlockDialog> createState() =>
      _AchievementUnlockDialogState();
}

class _AchievementUnlockDialogState extends State<_AchievementUnlockDialog>
    with SingleTickerProviderStateMixin {
  late final AnimationController _fireworksController;

  @override
  void initState() {
    super.initState();

    _fireworksController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1800),
    )..repeat();
  }

  @override
  void dispose() {
    _fireworksController.dispose();

    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final achievement = widget.achievement;

    final colors = _achievementPopupColors(achievement);

    final screenSize = MediaQuery.sizeOf(context);

    final textScale = MediaQuery.textScalerOf(context).scale(1.0);

    final dialogWidth = math.min(340.0, screenSize.width - 40);

    final extraHeight = ((textScale - 1.0).clamp(0.0, 0.5)) * 140;

    final dialogHeight = 470.0 + extraHeight;

    return Material(
      color: Colors.transparent,

      child: SafeArea(
        child: Center(
          child: SingleChildScrollView(
            padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 20),

            child: SizedBox(
              width: dialogWidth,
              height: dialogHeight,

              child: Stack(
                alignment: Alignment.topCenter,

                clipBehavior: Clip.none,

                children: [
                  // =========================
                  // FIREWORKS
                  // =========================

                  Positioned(
                    top: 0,
                    left: 0,
                    right: 0,

                    child: SizedBox(
                      height: 155,

                      child: AnimatedBuilder(
                        animation: _fireworksController,

                        builder: (context, _) {
                          return CustomPaint(
                            painter: _AchievementFireworksPainter(
                              progress: _fireworksController.value,

                              colors: colors,
                            ),
                          );
                        },
                      ),
                    ),
                  ),

                  // =========================
                  // LARGE TRANSPARENT MEDAL
                  // =========================
                  Positioned(
                    top: 100,

                    child: IgnorePointer(
                      child: Opacity(
                        opacity: 0.05,

                        child: Transform.scale(
                          scale: 3.2,

                          child: _AchievementMedal(achievement: achievement),
                        ),
                      ),
                    ),
                  ),

                  // =========================
                  // ACHIEVEMENT CARD
                  // =========================
                  Positioned(
                    top: 120,
                    left: 0,
                    right: 0,

                    child: Container(
                      padding: const EdgeInsets.all(1.4),

                      decoration: BoxDecoration(
                        borderRadius: BorderRadius.circular(26),

                        gradient: LinearGradient(
                          begin: Alignment.topLeft,
                          end: Alignment.bottomRight,
                          colors: colors,
                        ),

                        boxShadow: [
                          BoxShadow(
                            color: _achievementAccent(achievement.rarity)
                                .withValues(alpha: 0.24),

                            blurRadius: 28,

                            spreadRadius: 2,
                          ),
                        ],
                      ),

                      child: Container(
                        padding: const EdgeInsets.fromLTRB(24, 28, 24, 22),

                        decoration: BoxDecoration(
                          borderRadius: BorderRadius.circular(25),

                          color: Color.alphaBlend(
                            chipluxViolet.withValues(alpha: 0.035),

                            chipluxSurface,
                          ),
                        ),

                        child: Column(
                          mainAxisSize: MainAxisSize.min,

                          children: [
                            // =========================
                            // LABEL
                            // =========================

                            const GradientText(
                              'ACHIEVEMENT UNLOCKED',

                              style: TextStyle(
                                fontSize: 12,

                                fontWeight: FontWeight.w800,

                                letterSpacing: 1.7,
                              ),
                            ),

                            const SizedBox(height: 24),

                            // =========================
                            // NORMAL MEDAL
                            // =========================
                            Transform.scale(
                              scale: 1.35,

                              child: _AchievementMedal(
                                achievement: achievement,
                              ),
                            ),

                            const SizedBox(height: 27),

                            // =========================
                            // TITLE
                            // =========================
                            Text(
                              achievement.title,

                              textAlign: TextAlign.center,

                              style: const TextStyle(
                                color: Colors.white,

                                fontSize: 23,

