class _AchievementFireworksPainter extends CustomPainter {
  final double progress;
  final List<Color> colors;

  const _AchievementFireworksPainter({
    required this.progress,
    required this.colors,
  });

  @override
  void paint(Canvas canvas, Size size) {
    _drawFirework(
      canvas,
      size,
      const Offset(0.22, 0.62),
      delay: 0.00,
      particleCount: 14,
    );

    _drawFirework(
      canvas,
      size,
      const Offset(0.50, 0.30),
      delay: 0.28,
      particleCount: 17,
    );

    _drawFirework(
      canvas,
      size,
      const Offset(0.78, 0.58),
      delay: 0.56,
      particleCount: 14,
    );

    _drawFirework(
      canvas,
      size,
      const Offset(0.38, 0.70),
      delay: 0.78,
      particleCount: 11,
    );
  }

  void _drawFirework(
    Canvas canvas,
    Size size,
    Offset normalizedCenter, {
    required double delay,
    required int particleCount,
  }) {
    final double local = (progress + 1.0 - delay) % 1.0;

    // Each firework appears only
    // during part of the loop.
    if (local > 0.72) {
      return;
    }

    final double normalized = (local / 0.72).clamp(0.0, 1.0);

    final double expansion = Curves.easeOutCubic.transform(normalized);

    final double fade = (1.0 - normalized).clamp(0.0, 1.0);

    final center = Offset(
      size.width * normalizedCenter.dx,
      size.height * normalizedCenter.dy,
    );

    final maxRadius = 28 + size.width * 0.11;

    for (int i = 0; i < particleCount; i++) {
      final angle = (math.pi * 2 / particleCount) * i + delay * math.pi;

      final variation = 0.78 + (i % 4) * 0.08;

      final distance = maxRadius * expansion * variation;

      final position =
          center +
          Offset(math.cos(angle) * distance, math.sin(angle) * distance);

      final color = colors[i % colors.length];

      final particlePaint = Paint()
        ..color = color.withValues(alpha: fade * 0.95);

      final trailPaint = Paint()
        ..color = color.withValues(alpha: fade * 0.30)
        ..strokeWidth = 1.4
        ..strokeCap = StrokeCap.round;

      final trailLength = 7.0 + (i % 3) * 2.5;

      final trailEnd =
          position -
          Offset(math.cos(angle) * trailLength, math.sin(angle) * trailLength);

      canvas.drawLine(trailEnd, position, trailPaint);

      canvas.drawCircle(position, 1.8 + (i % 3) * 0.45, particlePaint);
    }

    // Small flash at explosion center.
    final flashFade = (1.0 - normalized * 4.0).clamp(0.0, 1.0);

    if (flashFade > 0) {
      canvas.drawCircle(
        center,
        4 + normalized * 5,
        Paint()..color = Colors.white.withValues(alpha: flashFade * 0.85),
      );
    }
  }

  @override
  bool shouldRepaint(covariant _AchievementFireworksPainter oldDelegate) {
    return oldDelegate.progress != progress || oldDelegate.colors != colors;
  }
}

List<Color> _achievementPopupColors(_Achievement achievement) {
  switch (achievement.visualTier) {
    case 1:
      return const [Color(0xFFF7F9FC), Color(0xFFBFC9D4)];

    case 2:
      // Strong blue
      return const [Color(0xFF38BDF8), Color(0xFF2563EB)];

    case 3:
      // Strong violet / magenta
      return const [Color(0xFFA855F7), Color(0xFFD946EF), Color(0xFF6366F1)];

    case 4:
      // Pure gold
      return const [Color(0xFFFFF3A3), Color(0xFFFFC400), Color(0xFFE6A700)];

    case 5:
      // Fire / molten
      return const [Color(0xFFFF8A3D), Color(0xFFFF4D4D), Color(0xFFD91E36)];

    case 6:
      return const [Color(0xFFFF416C), Color(0xFFD65CFF), Color(0xFF7A5CFF)];

    case 7:
      return const [Color(0xFF5CFFD1), Color(0xFF25D98F), Color(0xFF43E8FF)];

    case 8:
      return const [Color(0xFFFF6BFF), Color(0xFF9B5CFF), Color(0xFF5C7CFF)];

    case 9:
      return const [
        Color(0xFFFFD86B),
        Color(0xFFFF6B8A),
        Color(0xFFD65CFF),
        Color(0xFF43E8FF),
      ];

    default:
      return const [Color(0xFFFFFFFF), Color(0xFFCBD5E1), Color(0xFF94A3B8)];
  }
}

class ChipluxBackground extends StatelessWidget {
  final ChipluxBackgroundStyle style;
  final Widget child;

  const ChipluxBackground({
    super.key,
    required this.style,
    required this.child,
  });

  @override
  Widget build(BuildContext context) {
    return RepaintBoundary(
      child: CustomPaint(
        painter: _ChipluxBackgroundPainter(style),
        child: child,
      ),
    );
  }
}

class _ChipluxBackgroundPainter extends CustomPainter {
  final ChipluxBackgroundStyle style;

  const _ChipluxBackgroundPainter(this.style);

  @override
  void paint(Canvas canvas, Size size) {
    // Keep our normal dark background.
    canvas.drawRect(Offset.zero & size, Paint()..color = chipluxBackground);

    late Color firstColor;
    late Color secondColor;
    late Color thirdColor;

    switch (style) {
      case ChipluxBackgroundStyle.discover:
        firstColor = chipluxCyan;
        secondColor = chipluxViolet;
        thirdColor = chipluxPurple;
        break;

      case ChipluxBackgroundStyle.search:
        firstColor = chipluxViolet;
        secondColor = chipluxCyan;
        thirdColor = chipluxPurple;
        break;

      case ChipluxBackgroundStyle.watch:
        firstColor = chipluxCyan;
        secondColor = chipluxPurple;
        thirdColor = chipluxViolet;
        break;

      case ChipluxBackgroundStyle.community:
        firstColor = chipluxCyan;
        secondColor = chipluxViolet;
        thirdColor = chipluxPurple;
        break;

      case ChipluxBackgroundStyle.profile:
        firstColor = chipluxPurple;
        secondColor = chipluxViolet;
        thirdColor = chipluxCyan;
        break;
    }

    // TOP LEFT GLOW
    _drawGlow(
      canvas,
      center: Offset(-size.width * 0.10, size.height * 0.12),
      radius: size.width * 0.85,
      color: firstColor,
      opacity: 0.12,
    );

    // RIGHT / MIDDLE GLOW
    _drawGlow(
      canvas,
      center: Offset(size.width * 1.08, size.height * 0.45),
      radius: size.width * 0.90,
      color: secondColor,
      opacity: 0.095,
    );

    // LOWER LEFT GLOW
    _drawGlow(
      canvas,
      center: Offset(size.width * 0.05, size.height * 0.90),
      radius: size.width * 0.80,
      color: thirdColor,
      opacity: 0.07,
    );

    _drawLines(canvas, size, secondColor);
  }

  void _drawGlow(
    Canvas canvas, {
    required Offset center,
    required double radius,
    required Color color,
    required double opacity,
  }) {
    final rect = Rect.fromCircle(center: center, radius: radius);

    final shader = RadialGradient(
      colors: [
        color.withValues(alpha: opacity),
        color.withValues(alpha: 0),
      ],
      stops: const [0, 1],
    ).createShader(rect);

    canvas.drawCircle(center, radius, Paint()..shader = shader);
  }

  void _drawLines(Canvas canvas, Size size, Color color) {
    final paint = Paint()
      ..color = color.withValues(alpha: 0.06)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.0;

    // UPPER DIAGONAL
    final path1 = Path()
      ..moveTo(size.width * 0.62, 0)
      ..lineTo(size.width * 0.90, size.height * 0.18)
      ..lineTo(size.width, size.height * 0.18);

    canvas.drawPath(path1, paint);

    // MIDDLE LINE
    final path2 = Path()
      ..moveTo(0, size.height * 0.48)
      ..lineTo(size.width * 0.14, size.height * 0.44)
      ..lineTo(size.width * 0.52, size.height * 0.44);

    canvas.drawPath(path2, paint);

    // LOWER GEOMETRIC LINE
    final path3 = Path()
      ..moveTo(size.width * 0.45, size.height)
      ..lineTo(size.width * 0.68, size.height * 0.83)
      ..lineTo(size.width, size.height * 0.83);

    canvas.drawPath(path3, paint);
  }

  @override
  bool shouldRepaint(covariant _ChipluxBackgroundPainter oldDelegate) {
    return oldDelegate.style != style;
  }
}

final GlobalKey<NavigatorState>
    chipluxNavigatorKey =
    GlobalKey<NavigatorState>();

    final FlutterLocalNotificationsPlugin
    chipluxLocalNotifications =
    FlutterLocalNotificationsPlugin();


const AndroidNotificationChannel
    chipluxNotificationChannel =
    AndroidNotificationChannel(
  'chiplux_notifications',
  'Chiplux Notifications',

  description:
      'Notifications from Chiplux.',

  importance:
      Importance.high,
);

Future<void>
    _initializeForegroundNotifications()
    async {
  const initializationSettings =
      InitializationSettings(
    android:
        AndroidInitializationSettings(
      '@mipmap/ic_launcher',
    ),

    iOS:
        DarwinInitializationSettings(
      requestAlertPermission:
          false,

      requestBadgePermission:
          false,

      requestSoundPermission:
          false,
    ),
  );


  await chipluxLocalNotifications
      .initialize(
    settings:
        initializationSettings,

    onDidReceiveNotificationResponse:
        (response) {
      final payload =
          response.payload;

      if (payload == null ||
          payload.isEmpty) {
        return;
      }

      try {
        final decoded =
            jsonDecode(
          payload,
        );

        if (decoded is! Map) {
          return;
        }

        final data =
            Map<String, dynamic>.from(
          decoded,
        );

        final message =
            RemoteMessage(
          data: data,
        );

        unawaited(
          _openPushWhenReady(
            message,
          ),
        );
      } catch (e) {
        debugPrint(
          'Could not open foreground notification: $e',
        );
      }
    },
  );


  await chipluxLocalNotifications
      .resolvePlatformSpecificImplementation<
          AndroidFlutterLocalNotificationsPlugin>()
      ?.createNotificationChannel(
    chipluxNotificationChannel,
  );
}

Future<void>
    _showForegroundPush(
  RemoteMessage message,
) async {
  final title =
      message.notification
              ?.title ??
          message.data['title']
              ?.toString() ??
          'Chiplux';


  final body =
      message.notification
              ?.body ??
          message.data['body']
              ?.toString() ??
          '';


  final notificationId =
      (message.messageId ??
              DateTime.now()
                  .microsecondsSinceEpoch
                  .toString())
          .hashCode &
      0x7fffffff;


  await chipluxLocalNotifications
      .show(
    id: notificationId,

    title: title,

    body: body,

    notificationDetails:
        const NotificationDetails(
      android:
          AndroidNotificationDetails(
        'chiplux_notifications',

        'Chiplux Notifications',

        channelDescription:
            'Notifications from Chiplux.',

        importance:
            Importance.high,

        priority:
            Priority.high,

        playSound:
            true,
      ),
    ),

    // Keep all FCM routing data.
    payload:
        jsonEncode(
      message.data,
    ),
  );
}

    String? _pushString(
  Map<String, dynamic> data,
  String key,
) {
  final value = data[key];

  if (value == null) {
    return null;
  }

  final text =
      value.toString().trim();

  return text.isEmpty
      ? null
      : text;
}


int? _pushInt(
  Map<String, dynamic> data,
  String key,
) {
  final value =
      _pushString(
    data,
    key,
  );

  if (value == null) {
    return null;
  }

  return int.tryParse(value);
}


int _pushAchievementTabIndex(
  String? achievementId,
) {
  if (achievementId == null ||
      achievementId.isEmpty) {
    return 0;
  }

  if (achievementId.startsWith(
        'movies_',
      ) ||
      achievementId.startsWith(
        'movies_rated_',
      )) {
    return 0;
  }

  if (achievementId.startsWith(
        'tv_',
      ) ||
      achievementId.startsWith(
        'episodes_',
      ) ||
      achievementId.startsWith(
        'tv_rated_',
      ) ||
      achievementId.startsWith(
        'episodes_rated_',
      )) {
    return 1;
  }

  if (achievementId.startsWith(
        'followers_',
      ) ||
      achievementId.startsWith(
        'profile_views_',
      )) {
    return 2;
  }

  if (achievementId.startsWith(
        'login_',
      ) ||
      achievementId.startsWith(
        'runtime_level_',
      ) ||
      achievementId.startsWith(
        'ratings_level_',
      ) ||
      achievementId.startsWith(
        'medal_collection_',
      )) {
    return 3;
  }

  return 0;
}


