Future<void> _openPushMessage(
  RemoteMessage message,
) async {
  final navigator =
      chipluxNavigatorKey
          .currentState;

  if (navigator == null) {
    return;
  }

  final data = message.data;

  final type =
      _pushString(
    data,
    'type',
  );

  if (type == null) {
    return;
  }

  // Mark the matching in-app
  // notification as read.
  final notificationId =
      _pushString(
    data,
    'notification_id',
  );

  if (notificationId != null) {
    try {
      await NotificationService
          .instance
          .markRead(
        notificationId,
      );
    } catch (e) {
      debugPrint(
        'Could not mark push notification read: $e',
      );
    }
  }

  // ==========================================
  // NEW FOLLOWER
  // ==========================================

  if (type == 'new_follower') {
    final userId =
        _pushString(
      data,
      'actor_user_id',
    );

    if (userId == null) {
      return;
    }

    await navigator.push(
      MaterialPageRoute(
        builder: (_) =>
            PublicProfilePage(
          userId: userId,
        ),
      ),
    );

    return;
  }


  // ==========================================
  // ACHIEVEMENT
  // ==========================================

  if (type == 'achievement') {
    final achievementId =
        _pushString(
      data,
      'achievement_id',
    );

    await navigator.push(
      MaterialPageRoute(
        builder: (_) =>
            AchievementsPage(
          initialTabIndex:
              _pushAchievementTabIndex(
            achievementId,
          ),

          initialAchievementId:
              achievementId,
        ),
      ),
    );

    return;
  }


  // ==========================================
  // RELEASE
  // ==========================================

  if (type == 'release') {
    final tmdbId =
        _pushInt(
      data,
      'tmdb_id',
    );

    final mediaType =
        _pushString(
      data,
      'media_type',
    );

    if (tmdbId == null ||
        mediaType == null ||
        (mediaType != 'movie' &&
            mediaType != 'tv')) {
      return;
    }

    await navigator.push(
      MaterialPageRoute(
        builder: (_) =>
            MediaDetailsPage(
          id: tmdbId,
          mediaType:
              mediaType,
        ),
      ),
    );

    return;
  }


  // ==========================================
  // NEW EPISODE
  // ==========================================

  if (type == 'new_episode') {
    final showId =
        _pushInt(
      data,
      'tmdb_id',
    );

    final seasonNumber =
        _pushInt(
      data,
      'season_number',
    );

    final episodeNumber =
        _pushInt(
      data,
      'episode_number',
    );

    if (showId == null ||
        seasonNumber == null ||
        episodeNumber == null) {
      return;
    }

    try {
      final tmdb =
          TmdbService();

      final episodes =
          await tmdb
              .getSeasonEpisodes(
        showId,
        seasonNumber,
      );

      Map<String, dynamic>?
          foundEpisode;

      for (final raw
          in episodes) {
        if (raw is! Map) {
          continue;
        }

        final episode =
            Map<String, dynamic>.from(
          raw,
        );

        final rawNumber =
            episode[
                'episode_number'];

        if (rawNumber is num &&
            rawNumber.toInt() ==
                episodeNumber) {
          foundEpisode =
              episode;

          break;
        }
      }

      if (foundEpisode == null) {
        return;
      }

      final rawRuntime =
          foundEpisode[
              'runtime'];

      final rawRating =
          foundEpisode[
              'vote_average'];

      await navigator.push(
        MaterialPageRoute(
          builder: (_) =>
              SwipeableEpisodePage(
            showId:
                showId,

            seasonNumber:
                seasonNumber,

            episodeNumber:
                episodeNumber,

            title:
                foundEpisode?[
                            'name']
                        ?.toString() ??
                    'Episode $episodeNumber',

            stillPath:
                foundEpisode?[
                        'still_path']
                    ?.toString(),

            runtime:
                rawRuntime
                        is num
                    ? rawRuntime
                        .toInt()
                    : null,

            rating:
                rawRating is num &&
                        rawRating
                                .toDouble() >
                            0
                    ? rawRating
                        .toDouble()
                    : null,

            overview:
                foundEpisode?[
                            'overview']
                        ?.toString() ??
                    '',

            airDate:
                foundEpisode?[
                        'air_date']
                    ?.toString(),
          ),
        ),
      );
    } catch (e) {
      debugPrint(
        'Could not open push episode: $e',
      );
    }

    return;
  }


  // ==========================================
  // COMMENT / LIKE MILESTONE
  // ==========================================

  if (type ==
          'comment_reply' ||
      type ==
          'comment_like_milestone') {
    final mediaType =
        _pushString(
      data,
      'media_type',
    );

    final tmdbId =
        _pushInt(
      data,
      'tmdb_id',
    );

    final targetCommentId =
        _pushString(
      data,
      'comment_id',
    );

    if (mediaType == null ||
        tmdbId == null) {
      return;
    }

    final tmdb =
        TmdbService();

    try {
      // ======================================
      // EPISODE COMMENT
      // ======================================

      if (mediaType ==
          'episode') {
        final seasonNumber =
            _pushInt(
          data,
          'season_number',
        );

        final episodeNumber =
            _pushInt(
          data,
          'episode_number',
        );

        if (seasonNumber ==
                null ||
            episodeNumber ==
                null) {
          return;
        }

        final showDetails =
            await tmdb
                .getDetails(
          tmdbId,
          'tv',
        );

        final episodes =
            await tmdb
                .getSeasonEpisodes(
          tmdbId,
          seasonNumber,
        );

        Map<String, dynamic>?
            episodeDetails;

        for (final raw
            in episodes) {
          if (raw is! Map) {
            continue;
          }

          final episode =
              Map<String, dynamic>.from(
            raw,
          );

          final rawNumber =
              episode[
                  'episode_number'];

          if (rawNumber is num &&
              rawNumber.toInt() ==
                  episodeNumber) {
            episodeDetails =
                episode;

            break;
          }
        }

        final showTitle =
            (showDetails[
                        'name'] ??
                    'TV Show')
                .toString();

        final episodeTitle =
            (episodeDetails?[
                        'name'] ??
                    'Episode $episodeNumber')
                .toString();

        final episodeCode =
            'S${seasonNumber.toString().padLeft(2, '0')}'
            'E${episodeNumber.toString().padLeft(2, '0')}';

        await navigator.push(
          MaterialPageRoute(
            builder: (_) =>
                CommentsPage(
              mediaType:
                  'episode',

              tmdbId:
                  tmdbId,

              seasonNumber:
                  seasonNumber,

              episodeNumber:
                  episodeNumber,

              title:
                  episodeTitle,

              subtitle:
                  '$showTitle • $episodeCode',

              imagePath:
                  episodeDetails?[
                          'still_path']
                      ?.toString(),

              targetCommentId:
                  targetCommentId,

              onProfileTap:
                  (userId) async {
                await chipluxNavigatorKey
                    .currentState
                    ?.push(
                  MaterialPageRoute(
                    builder: (_) =>
                        PublicProfilePage(
                      userId:
                          userId,
                    ),
                  ),
                );
              },
            ),
          ),
        );

        return;
      }


      // ======================================
      // MOVIE / TV COMMENT
      // ======================================

      if (mediaType ==
              'movie' ||
          mediaType ==
              'tv') {
        final details =
            await tmdb
                .getDetails(
          tmdbId,
          mediaType,
        );

        final title =
            (details['title'] ??
                    details['name'] ??
                    'Discussion')
                .toString();

        await navigator.push(
          MaterialPageRoute(
            builder: (_) =>
                CommentsPage(
              mediaType:
                  mediaType,

              tmdbId:
                  tmdbId,

              title:
                  title,

              imagePath:
                  details[
                          'backdrop_path']
                      ?.toString(),

              targetCommentId:
                  targetCommentId,

              onProfileTap:
                  (userId) async {
                await chipluxNavigatorKey
                    .currentState
                    ?.push(
                  MaterialPageRoute(
                    builder: (_) =>
                        PublicProfilePage(
                      userId:
                          userId,
                    ),
                  ),
                );
              },
            ),
          ),
        );

        return;
      }
    } catch (e) {
      debugPrint(
        'Could not open push discussion: $e',
      );
    }

    return;
  }


  // ==========================================
  // CHIPLUX UPDATE
  // ==========================================

  if (type ==
      'chiplux_update') {


    final title =
        _pushString(
          data,
          'title',
        ) ??
        message.notification
            ?.title ??
        'Chiplux Update';

    final body =
        _pushString(
          data,
          'body',
        ) ??
        message.notification
            ?.body ??
        '';

    final dialogContext =
        chipluxNavigatorKey.currentContext;

    if (dialogContext == null ||
        !dialogContext.mounted) {
      return;
    }

    await _showChipluxUpdateDialog(
      context: dialogContext,
      title: title,
      body: body,
    );

    return;
  }
}

Future<void> _openPushWhenReady(
  RemoteMessage message,
) async {
  // Cold start can take a moment before
  // MaterialApp/AuthGate has a navigator.

  for (int attempt = 0;
      attempt < 30;
      attempt++) {
    final navigatorReady =
        chipluxNavigatorKey
                .currentState !=
            null;

    final userReady =
        AuthService.instance
                .currentUser !=
            null;

    if (navigatorReady &&
        userReady) {
      await _openPushMessage(
        message,
      );

      return;
    }

    await Future<void>.delayed(
      const Duration(
        milliseconds: 150,
      ),
    );
  }

  debugPrint(
    'Push tap could not be routed because the app was not ready.',
  );
}

class ChipluxApp
    extends StatefulWidget {
  const ChipluxApp({
    super.key,
  });

  @override
  State<ChipluxApp>
      createState() =>
          _ChipluxAppState();
}


class _ChipluxAppState
    extends State<ChipluxApp> {
  StreamSubscription<
      RemoteMessage>?
      _pushTapSubscription;

  StreamSubscription<
      RemoteMessage>?
      _foregroundPushSubscription;


  @override
  void initState() {
    super.initState();

    // =========================================
    // APP IS OPEN / FOREGROUND
    // =========================================

    _foregroundPushSubscription =
        FirebaseMessaging
            .onMessage
            .listen(
      (message) {
        unawaited(
          _showForegroundPush(
            message,
          ),
        );
      },
    );

    // =========================================
    // APP WAS IN BACKGROUND
    // =========================================

    _pushTapSubscription =
        FirebaseMessaging
            .onMessageOpenedApp
            .listen(
      (message) {
        unawaited(
          _openPushWhenReady(
            message,
          ),
        );
      },
    );


    // =========================================
    // APP WAS COMPLETELY CLOSED
    // =========================================

    WidgetsBinding.instance
        .addPostFrameCallback(
      (_) {
        unawaited(
          _checkInitialPush(),
        );
      },
    );
  }


  Future<void>
      _checkInitialPush() async {
    final message =
        await FirebaseMessaging
            .instance
            .getInitialMessage();

    if (message == null) {
      return;
    }

    await _openPushWhenReady(
      message,
    );
  }


  @override
  void dispose() {
    _pushTapSubscription
        ?.cancel();

    _foregroundPushSubscription
        ?.cancel();

    super.dispose();
  }


  @override
  Widget build(
    BuildContext context,
  ) {
    return MaterialApp(
      navigatorKey:
          chipluxNavigatorKey,

      debugShowCheckedModeBanner:
          false,

      title: 'Chiplux',

      theme: ThemeData(
        brightness:
            Brightness.dark,

        scaffoldBackgroundColor:
            chipluxBackground,

        colorScheme:
            const ColorScheme.dark(
          primary:
              chipluxCyan,

          secondary:
              chipluxViolet,

          surface:
              chipluxSurface,
        ),

        useMaterial3: true,

        navigationBarTheme:
            const NavigationBarThemeData(
          backgroundColor:
              Color(
            0xFF091521,
          ),

          indicatorColor:
              Color(
            0xFF173A50,
          ),
        ),
      ),

      home:
          const AuthGate(),
    );
  }
}

class AuthGate extends StatelessWidget {
  const AuthGate({super.key});

  @override
  Widget build(BuildContext context) {
    return StreamBuilder(
      stream: AuthService.instance.authChanges,
      builder: (context, snapshot) {
        final user = AuthService.instance.currentUser;

        if (user == null) {
          return const LoginPage();
        }

        return const MainScreen();
      },
    );
  }
}

class LoginPage extends StatefulWidget {
  const LoginPage({super.key});

  @override
  State<LoginPage> createState() => _LoginPageState();
}

class _LoginPageState extends State<LoginPage> {
  // =====================================================
  // CONTROLLERS
  // =====================================================

  final TextEditingController emailController = TextEditingController();

  final TextEditingController passwordController = TextEditingController();

  final TextEditingController usernameController = TextEditingController();

  // =====================================================
  // LOGIN STATE
  // =====================================================

  bool loading = false;
  bool signupMode = false;
  bool showPassword = false;

  bool rememberMe = false;

  String? message;

  static const String _rememberedEmailKey = 'chiplux_remembered_email';

  static const String _pendingSignupKey = 'chiplux_pending_signup_email';

  // =====================================================
  // USERNAME CHECK
  // =====================================================

  Timer? _usernameDebounce;

  bool usernameChecking = false;

  bool? usernameAvailable;

  String? usernameStatus;

  List<String> usernameSuggestions = <String>[];

  int _usernameCheckGeneration = 0;

  // =====================================================
  // INIT
  // =====================================================

  @override
  void initState() {
    super.initState();

    _loadRememberedEmail();
  }

  Future<void> _loadRememberedEmail() async {
    final prefs = await SharedPreferences.getInstance();

    final rememberedEmail = prefs.getString(_rememberedEmailKey);

    if (!mounted || rememberedEmail == null || rememberedEmail.isEmpty) {
      return;
    }

    setState(() {
      emailController.text = rememberedEmail;

      rememberMe = true;
    });
  }

  // =====================================================
  // USERNAME
  // =====================================================

  void _onUsernameChanged(String value) {
    _usernameDebounce?.cancel();

    final username = value.trim().toLowerCase();

    _usernameCheckGeneration++;

    final generation = _usernameCheckGeneration;

    setState(() {
      usernameAvailable = null;
      usernameSuggestions = [];
      usernameStatus = null;
      usernameChecking = false;
    });

    if (!signupMode) {
      return;
    }

    if (username.isEmpty) {
      return;
    }

    if (username.length < 3) {
      setState(() {
        usernameStatus = 'Username must be at least 3 characters.';
      });

      return;
    }

    if (username.length > 20) {
      setState(() {
        usernameStatus = 'Username cannot be longer than 20 characters.';
      });

      return;
    }

    if (!RegExp(r'^[a-z0-9_]+$').hasMatch(username)) {
      setState(() {
        usernameStatus = 'Use only letters, numbers and underscores.';
      });

      return;
    }

    setState(() {
      usernameChecking = true;

      usernameStatus = 'Checking username...';
    });

    _usernameDebounce = Timer(const Duration(milliseconds: 350), () {
      _checkUsername(username, generation);
    });
  }

  Future<void> _checkUsername(String username, int generation) async {
    try {
      final result = await AuthService.instance.checkUsernameAvailability(
        username,
      );

      if (!mounted || generation != _usernameCheckGeneration) {
        return;
      }

      final rawSuggestions = result['suggestions'];

      final suggestions = rawSuggestions is List
          ? rawSuggestions
                .map((value) => value.toString())
                .where((value) => value.isNotEmpty)
                .take(3)
                .toList()
          : <String>[];

      final available = result['available'] == true;

      setState(() {
        usernameChecking = false;

        usernameAvailable = available;

        usernameStatus = available
            ? 'Username is available.'
            : 'Username is already taken.';

        usernameSuggestions = suggestions;
      });
    } catch (e) {
      debugPrint('Could not check username: $e');

      if (!mounted || generation != _usernameCheckGeneration) {
        return;
      }

      setState(() {
        usernameChecking = false;

        usernameAvailable = null;

        usernameStatus = 'Could not check username.';
      });
    }
  }

  void _useUsernameSuggestion(String username) {
    usernameController.text = username;

    usernameController.selection = TextSelection.collapsed(
      offset: username.length,
    );

    _onUsernameChanged(username);
  }

  // =====================================================
  // SIGN IN / SIGN UP
  // =====================================================

  Future<void> submit() async {
    final identifier = emailController.text.trim();

    final password = passwordController.text;

    final username = usernameController.text.trim().toLowerCase();

    // ===================================================
    // BASIC VALIDATION
    // ===================================================

    if (identifier.isEmpty || password.length < 6) {
      setState(() {
        message = signupMode
            ? 'Enter your email and a password of at least 6 characters.'
            : 'Enter your email or username and a password of at least 6 characters.';
      });

      return;
    }

    // ===================================================
    // SIGNUP VALIDATION
    // ===================================================

    if (signupMode) {
      if (!identifier.contains('@')) {
        setState(() {
          message = 'Enter a valid email address.';
        });

        return;
      }

      if (username.isEmpty) {
        setState(() {
          message = 'Choose a username.';
        });

        return;
      }

      if (usernameChecking) {
        setState(() {
          message = 'Wait for the username check to finish.';
        });

        return;
      }

      if (usernameAvailable != true) {
        setState(() {
          message = 'Choose an available username.';
        });

        return;
      }
    }

    setState(() {
      loading = true;
      message = null;
    });

    try {
      final prefs = await SharedPreferences.getInstance();

      // =================================================
      // CREATE ACCOUNT
      // =================================================

      if (signupMode) {
        final response = await AuthService.instance.signUp(
          email: identifier,

          password: password,

          username: username,
        );

        if (response.session != null) {
          await LibraryService.instance.syncToCloud();

          await _loadCurrentAccountAchievementState();

          await DailyLoginService.instance.recordToday();

          await prefs.remove(_pendingSignupKey);
        } else {
          // Email confirmation is required.
          //
          // Remember which specific account
          // is allowed to inherit the local
          // guest library after confirmation.

          await prefs.setString(_pendingSignupKey, identifier.toLowerCase());

          if (mounted) {
            setState(() {
              message = 'Account created. Check your email and confirm your account, then sign in.';
            });
          }
        }

        return;
      }

      // =================================================
      // SIGN IN
      // =================================================

      await AuthService.instance.signIn(
        identifier: identifier,
        password: password,
      );

      // Authentication succeeded.
      //
      // This is the ACTUAL account email,
      // even if the user signed in using
      // their username.

      final signedInEmail = AuthService.instance.currentUser?.email
          ?.trim()
          .toLowerCase();

      // =================================================
      // REMEMBER ME
      // =================================================

      if (rememberMe && signedInEmail != null && signedInEmail.isNotEmpty) {
        await prefs.setString(_rememberedEmailKey, signedInEmail);
      } else if (!rememberMe) {
        await prefs.remove(_rememberedEmailKey);
      }

      // =================================================
      // LOCAL / CLOUD LIBRARY
      // =================================================

      final library = LibraryService.instance;

      final cloud = CloudSyncService.instance;

      final pendingEmail = prefs.getString(_pendingSignupKey);

      final isPendingNewAccount =
          pendingEmail != null &&
          signedInEmail != null &&
          pendingEmail == signedInEmail;

      if (isPendingNewAccount) {
        final cloudLibrary = await cloud.downloadLibrary();

        final cloudEpisodes = await cloud.downloadEpisodes();

        final cloudIsEmpty = cloudLibrary.isEmpty && cloudEpisodes.isEmpty;

        if (cloudIsEmpty) {
          // This is the newly-created
          // account that owns the guest
          // data currently on the device.

          await library.syncToCloud();
        } else {
          // Cloud already contains data.
          // Cloud wins.

          await library.syncFromCloud();
        }

        await prefs.remove(_pendingSignupKey);
      } else {
        // Normal login to an existing
        // account.
        //
        // Never accidentally upload
        // leftover local data into it.

        await library.syncFromCloud();
      }

      await _loadCurrentAccountAchievementState();

      await DailyLoginService.instance.recordToday();
    } catch (e) {
      if (mounted) {
        setState(() {
          String error = e.toString();

          if (error.contains('already taken')) {
            message = 'That username is already taken.';
          } else if (error.contains('Invalid username or password') ||
              error.contains('Invalid login credentials')) {
            message = 'Invalid email, username or password.';
          } else {
            message = error;
          }
        });
      }
    } finally {
      if (mounted) {
        setState(() {
          loading = false;
        });
      }
    }
  }

  // =====================================================
  // CHANGE MODE
  // =====================================================

  void _toggleMode() {
    if (loading) {
      return;
    }

    _usernameDebounce?.cancel();

    setState(() {
      signupMode = !signupMode;

      message = null;

      usernameAvailable = null;
      usernameChecking = false;
      usernameStatus = null;

      usernameSuggestions = <String>[];

      passwordController.clear();

      showPassword = false;
    });

    _usernameCheckGeneration++;

    if (signupMode && usernameController.text.trim().isNotEmpty) {
      _onUsernameChanged(usernameController.text);
    }
  }

  // =====================================================
  // DISPOSE
  // =====================================================

  @override
  void dispose() {
    _usernameDebounce?.cancel();

    usernameController.dispose();
    emailController.dispose();
    passwordController.dispose();

    super.dispose();
  }

  // =====================================================
  // BUILD
  // =====================================================

  @override
  Widget build(BuildContext context) {
    final disableSubmit =
        loading ||
        (signupMode && (usernameChecking || usernameAvailable != true));

    return Scaffold(
      backgroundColor: Colors.transparent,

      body: ChipluxBackground(
        style: ChipluxBackgroundStyle.discover,

        child: SafeArea(
          child: Center(
            child: SingleChildScrollView(
              padding: const EdgeInsets.all(30),

              child: ConstrainedBox(
                constraints: const BoxConstraints(maxWidth: 430),

                child: Column(
                  children: [
                    // =====================================
                    // LOGO
                    // =====================================

                    const ChipluxWordmark(fontSize: 44),

                    const SizedBox(height: 10),

                    const Text(
                      'Your Taste · Your Story',
                      textAlign: TextAlign.center,
                      style: TextStyle(color: Colors.white54, letterSpacing: 2),
                    ),

                    const SizedBox(height: 42),

                    // =====================================
                    // USERNAME - CREATE ACCOUNT ONLY
                    // =====================================
                    if (signupMode) ...[
                      TextField(
                        controller: usernameController,

                        maxLength: 20,

                        autocorrect: false,

                        enableSuggestions: false,

                        textCapitalization: TextCapitalization.none,

                        textInputAction: TextInputAction.next,

                        onChanged: _onUsernameChanged,

                        decoration: InputDecoration(
                          labelText: 'Username',

                          prefixText: '@',

                          prefixIcon: const Icon(Icons.person_outline),

                          suffixIcon: usernameChecking
                              ? const Padding(
                                  padding: EdgeInsets.all(14),
                                  child: SizedBox(
                                    width: 18,
                                    height: 18,
                                    child: CircularProgressIndicator(
                                      strokeWidth: 2,
                                    ),
                                  ),
                                )
                              : usernameAvailable == true
                              ? const Icon(
                                  Icons.check_circle_outline,
                                  color: Colors.greenAccent,
                                )
                              : usernameAvailable == false
                              ? const Icon(
                                  Icons.cancel_outlined,
                                  color: Colors.redAccent,
                                )
                              : null,
                        ),
                      ),

                      if (usernameStatus != null)
                        Align(
                          alignment: Alignment.centerLeft,
                          child: Text(
                            usernameStatus!,
                            style: TextStyle(
                              fontSize: 12,
                              color: usernameAvailable == true
                                  ? Colors.greenAccent
                                  : usernameAvailable == false
                                  ? Colors.redAccent
                                  : Colors.white54,
                            ),
                          ),
                        ),

                      if (usernameSuggestions.isNotEmpty) ...[
                        const SizedBox(height: 9),

                        const Align(
                          alignment: Alignment.centerLeft,
                          child: Text(
                            'Try one of these:',
                            style: TextStyle(
                              color: Colors.white54,
                              fontSize: 12,
                            ),
                          ),
                        ),

                        const SizedBox(height: 7),

                        Align(
                          alignment: Alignment.centerLeft,
                          child: Wrap(
                            spacing: 7,
                            runSpacing: 5,

                            children: usernameSuggestions.map((suggestion) {
                              return ActionChip(
                                label: Text('@$suggestion'),
                                onPressed: () {
                                  _useUsernameSuggestion(suggestion);
                                },
                              );
                            }).toList(),
                          ),
                        ),
                      ],

                      const SizedBox(height: 15),
                    ],

                    // =====================================
                    // EMAIL / USERNAME
                    // =====================================
                    TextField(
                      controller: emailController,

                      keyboardType: signupMode
                          ? TextInputType.emailAddress
                          : TextInputType.text,

                      autocorrect: false,

                      textCapitalization: TextCapitalization.none,

                      textInputAction: TextInputAction.next,

                      decoration: InputDecoration(
                        labelText: signupMode ? 'Email' : 'Email or username',

                        prefixIcon: Icon(
                          signupMode
                              ? Icons.email_outlined
                              : Icons.person_outline,
                        ),
                      ),
                    ),

                    const SizedBox(height: 15),

                    // =====================================
                    // PASSWORD
                    // =====================================
                    TextField(
                      controller: passwordController,

                      obscureText: !showPassword,

                      textInputAction: TextInputAction.done,

                      onSubmitted: (_) {
                        if (!disableSubmit) {
                          submit();
                        }
                      },

                      decoration: InputDecoration(
                        labelText: signupMode ? 'Create Password' : 'Password',

                        prefixIcon: const Icon(Icons.lock_outline),

                        suffixIcon: IconButton(
                          onPressed: () {
                            setState(() {
                              showPassword = !showPassword;
                            });
                          },

                          icon: Icon(
                            showPassword
                                ? Icons.visibility_off_outlined
                                : Icons.visibility_outlined,
                          ),

                          tooltip: showPassword
                              ? 'Hide password'
                              : 'Show password',
                        ),
                      ),
                    ),

                    // =====================================
                    // REMEMBER ME
                    // =====================================
                    if (!signupMode) ...[
                      const SizedBox(height: 7),

                      Row(
                        children: [
                          Checkbox(
                            value: rememberMe,

                            activeColor: chipluxCyan,

                            checkColor: Colors.black,

                            visualDensity: VisualDensity.compact,

                            onChanged: loading
                                ? null
                                : (value) {
                                    setState(() {
                                      rememberMe = value ?? false;
                                    });
                                  },
                          ),

                          GestureDetector(
                            onTap: loading
                                ? null
                                : () {
                                    setState(() {
                                      rememberMe = !rememberMe;
                                    });
                                  },
                            child: const Text(
                              'Remember Me',
                              style: TextStyle(
                                color: Colors.white70,
                                fontSize: 14,
                              ),
                            ),
                          ),
                        ],
                      ),
                    ],

                    const SizedBox(height: 18),

                    // =====================================
                    // MESSAGE
                    // =====================================
                    if (message != null) ...[
                      Container(
                        width: double.infinity,

                        padding: const EdgeInsets.all(12),

                        decoration: BoxDecoration(
                          color: Colors.white.withValues(alpha: 0.05),

                          borderRadius: BorderRadius.circular(12),

                          border: Border.all(
                            color: Colors.white.withValues(alpha: 0.08),
                          ),
                        ),

                        child: Text(
                          message!,
                          textAlign: TextAlign.center,
                          style: const TextStyle(
                            color: Colors.white70,
                            fontSize: 13,
                          ),
                        ),
                      ),

                      const SizedBox(height: 15),
                    ],

                    // =====================================
                    // SUBMIT
                    // =====================================
                    SizedBox(
                      width: double.infinity,

                      child: ElevatedButton(
                        onPressed: disableSubmit ? null : submit,

                        child: Padding(
                          padding: const EdgeInsets.all(15),

                          child: loading
                              ? const SizedBox(
                                  width: 20,
                                  height: 20,
                                  child: CircularProgressIndicator(
                                    strokeWidth: 2,
                                  ),
                                )
                              : Text(signupMode ? 'Create Account' : 'Sign In'),
                        ),
                      ),
                    ),

                    const SizedBox(height: 15),

                    // =====================================
                    // MODE SWITCH
                    // =====================================
                    TextButton(
                      onPressed: loading ? null : _toggleMode,

                      child: Text(
                        signupMode
                            ? 'Already have an account? Sign In'
                            : 'Don\'t have an account? Create Account',
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}

class MainScreen extends StatefulWidget {
  const MainScreen({super.key});

  @override
  State<MainScreen> createState() => _MainScreenState();
}

class _MainScreenState extends State<MainScreen> {
  int currentIndex = 2;

  String libraryInitialFilter = 'watching';

  String libraryInitialMediaType = 'tv';

  String? libraryInitialSortMode;

  int libraryOpenRequest = 0;

  int communityInitialTabIndex = 0;

  int communityOpenRequest = 0;

  late int _lastRuntimeLevel;

  late int _lastRatingsLevel;

  @override
  void initState() {
    super.initState();

    ProfileService.instance.loadProfile();

    _lastRuntimeLevel = _runtimeLevelForMinutes(
      LibraryService.instance.totalWatchedMinutes,
    );

    _lastRatingsLevel = CriticService.instance.level;

    LibraryService.instance.addListener(_onLibraryChanged);

    CriticService.instance.addListener(_onCriticChanged);

    WidgetsBinding.instance.addPostFrameCallback((_) {
      unawaited(_checkPendingLaunchAchievements());
    });
  }

  void _onLibraryChanged() {
    final currentLevel = _runtimeLevelForMinutes(
      LibraryService.instance.totalWatchedMinutes,
    );

    if (currentLevel <= _lastRuntimeLevel) {
      _lastRuntimeLevel = currentLevel;

      return;
    }

    final previousLevel = _lastRuntimeLevel;

    _lastRuntimeLevel = currentLevel;

    if (!mounted) {
      return;
    }

    unawaited(
      _checkRuntimeLevelAchievementUnlock(
        context,
        previousLevel: previousLevel,
        currentLevel: currentLevel,
      ),
    );
  }

  void _onCriticChanged() {
    final currentLevel = CriticService.instance.level;

    if (currentLevel <= _lastRatingsLevel) {
      _lastRatingsLevel = currentLevel;

      return;
    }

    final previousLevel = _lastRatingsLevel;

    _lastRatingsLevel = currentLevel;

    if (!mounted) {
      return;
    }

    unawaited(
      _checkRatingsLevelAchievementUnlock(
        context,
        previousLevel: previousLevel,
        currentLevel: currentLevel,
      ),
    );
  }

  Future<void> _checkPendingLaunchAchievements() async {
    // =========================
    // DAILY LOGIN
    // =========================

    final dailyService = DailyLoginService.instance;

    final previousLoginCount = dailyService.takePendingPreviousCount();

    if (previousLoginCount != null && mounted) {
      await _checkDailyLoginAchievementUnlock(
        context,
        previousCount: previousLoginCount,
        currentCount: dailyService.loginDays,
      );
    }

    if (!mounted) {
      return;
    }

    // =========================
    // FOLLOWERS
    // =========================

    final followerService = FollowerCountService.instance;

    final previousFollowerPeak = followerService.takePendingPreviousPeakCount();

    if (previousFollowerPeak == null) {
      return;
    }

    await _checkFollowerAchievementUnlock(
      context,
      previousCount: previousFollowerPeak,
      currentCount: followerService.peakFollowerCount,
    );
  }

  void _openOwnFollowers() {
    setState(() {
      communityInitialTabIndex = 2;

      communityOpenRequest++;

      currentIndex = 3;
    });
  }

  void _openCompleted(String mediaType, {String? sortMode}) {
    setState(() {
      libraryInitialFilter = 'completed';

      libraryInitialMediaType = mediaType;

      libraryInitialSortMode = sortMode;

      libraryOpenRequest++;

      currentIndex = 2;
    });
  }

  Widget _currentPage() {
    return IndexedStack(
      index: currentIndex,

      children: [
        const HomePage(),

        const SearchPage(),

        LibraryPage(
          initialFilter: libraryInitialFilter,

          initialMediaType: libraryInitialMediaType,

          initialSortMode: libraryInitialSortMode,

          openRequest: libraryOpenRequest,
        ),

        CommunityPage(
          initialTabIndex: communityInitialTabIndex,

          openRequest: communityOpenRequest,
        ),

        ProfilePage(
          onFollowersTap: _openOwnFollowers,

          onTvShowsWatchedTap: () {
            _openCompleted('tv');
          },

          onEpisodesWatchedTap: () {
            _openCompleted('tv');
          },

          onMoviesWatchedTap: () {
            _openCompleted('movie');
          },

          onEpisodesRatedTap: () {
            _openCompleted('tv', sortMode: 'rated');
          },

          onTvShowsRatedTap: () {
            _openCompleted('tv', sortMode: 'rated');
          },

          onMoviesRatedTap: () {
            _openCompleted('movie', sortMode: 'rated');
          },
        ),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    final profile = ProfileService.instance;

    return Scaffold(
      body: ChipluxBackground(style: _backgroundStyle, child: _currentPage()),

      bottomNavigationBar: AnimatedBuilder(
        animation: profile,

        builder: (context, _) {
          return _ChipluxBottomNav(
            currentIndex: currentIndex,

            avatarUrl: profile.avatarUrl,

            onTap: (index) {
              setState(() {
                if (index == 2) {
                  libraryInitialFilter = 'watching';

                  libraryInitialMediaType = 'tv';

                  libraryInitialSortMode = null;

                  libraryOpenRequest++;
                }

                currentIndex = index;
              });
            },
          );
        },
      ),
    );
  }

  ChipluxBackgroundStyle get _backgroundStyle {
    switch (currentIndex) {
      case 0:
        return ChipluxBackgroundStyle.discover;

      case 1:
        return ChipluxBackgroundStyle.search;

      case 2:
        return ChipluxBackgroundStyle.watch;

      case 3:
        return ChipluxBackgroundStyle.community;

      case 4:
        return ChipluxBackgroundStyle.profile;

      default:
        return ChipluxBackgroundStyle.discover;
    }
  }

  @override
  void dispose() {
    LibraryService.instance.removeListener(_onLibraryChanged);

    CriticService.instance.removeListener(_onCriticChanged);

    super.dispose();
  }
}

class CommunityPage extends StatefulWidget {
  final int initialTabIndex;
  final int openRequest;

  const CommunityPage({
    super.key,
    this.initialTabIndex = 0,
    this.openRequest = 0,
  });

  @override
  State<CommunityPage> createState() => _CommunityPageState();
}

class _CommunityPageState extends State<CommunityPage>
    with SingleTickerProviderStateMixin {
  late final TabController _tabController;

  final CommunityService community = CommunityService.instance;

  RealtimeChannel? _activityChannel;

  RealtimeChannel? _followsChannel;

  Timer? _activityRefreshTimer;
  Timer? _followsRefreshTimer;

  bool loadingFriendsWatch = true;
  bool loadingFollowers = true;
  bool loadingFollowing = true;

  int newFollowersToday = 0;

  late int _lastCommunityTabIndex;

  List<Map<String, dynamic>> friendsWatch = [];

  List<Map<String, dynamic>> followers = [];

  List<Map<String, dynamic>> following = [];

  void _startCommunityRealtime() {
    final client = Supabase.instance.client;

    final userId = client.auth.currentUser?.id ?? 'anonymous';

    // =====================================
    // COMMUNITY ACTIVITY
    // =====================================

    _activityChannel = client.channel('community_activity_$userId');

    _activityChannel!
        .onPostgresChanges(
          event: PostgresChangeEvent.all,
          schema: 'public',
          table: 'community_activity',
          callback: (payload) {
            // Ratings use delete + insert,
            // so debounce rapid changes into
            // one refresh.
            _activityRefreshTimer?.cancel();

            _activityRefreshTimer = Timer(
              const Duration(milliseconds: 250),
              () {
                if (!mounted) {
                  return;
                }

                unawaited(_loadFriendsWatch());
              },
            );
          },
        )
        .subscribe();

    // =====================================
    // FOLLOWERS / FOLLOWING
    // =====================================

    _followsChannel = client.channel('community_follows_$userId');

    _followsChannel!
        .onPostgresChanges(
          event: PostgresChangeEvent.all,
          schema: 'public',
          table: 'follows',
          callback: (payload) {
            _followsRefreshTimer?.cancel();

            _followsRefreshTimer = Timer(const Duration(milliseconds: 250), () {
              if (!mounted) {
                return;
              }

              unawaited(_loadFollowers());

              unawaited(_loadFollowing());

              // Following/unfollowing somebody
              // also changes whose activity
              // belongs in Friends Watch.
              unawaited(_loadFriendsWatch());
            });
          },
        )
        .subscribe();
  }

  void _onCommunityTabChanged() {
    if (_tabController.indexIsChanging) {
      return;
    }

    final index = _tabController.index;

    if (index == _lastCommunityTabIndex) {
      return;
    }

    _lastCommunityTabIndex = index;

    switch (index) {
      case 0:
        unawaited(_loadFriendsWatch());
        break;

      case 2:
        unawaited(_openFollowersTab());
        break;

      case 3:
        unawaited(_loadFollowing());
        break;
    }
  }

  @override
  void initState() {
    super.initState();

    _lastCommunityTabIndex = widget.initialTabIndex;

    _tabController = TabController(
      length: 4,
      initialIndex: widget.initialTabIndex,
      vsync: this,
    );

    _tabController.addListener(_onCommunityTabChanged);

    _loadFriendsWatch();

    _loadFollowers();

    _loadFollowing();

    _startCommunityRealtime();
  }

  @override
  void didUpdateWidget(covariant CommunityPage oldWidget) {
    super.didUpdateWidget(oldWidget);

    if (oldWidget.openRequest == widget.openRequest) {
      return;
    }

    final index = widget.initialTabIndex.clamp(0, 3).toInt();

    _lastCommunityTabIndex = index;

    _tabController.animateTo(index);

    if (index == 2) {
      unawaited(_openFollowersTab());
    }
  }

  Future<void> _loadFriendsWatch() async {
    try {
      final data = await community.getFriendsWatch();

      if (!mounted) {
        return;
      }

      setState(() {
        friendsWatch = data;
        loadingFriendsWatch = false;
      });
    } catch (e) {
      debugPrint('Could not load Friends Watch: $e');

      if (!mounted) {
        return;
      }

      setState(() {
        loadingFriendsWatch = false;
      });
    }
  }

  Future<void> _openCommunityProfile(String userId) async {
    await Navigator.push(
      context,
      MaterialPageRoute(builder: (_) => PublicProfilePage(userId: userId)),
    );

    if (!mounted) {
      return;
    }

    await _loadFriendsWatch();
    await _loadFollowers();
    await _loadFollowing();
  }

  void _openCommunityMedia(Map<String, dynamic> activity) {
    final rawId = activity['tmdb_id'];

    final mediaType = activity['media_type']?.toString();

    if (rawId is! num || mediaType == null) {
      return;
    }

    Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) =>
            MediaDetailsPage(id: rawId.toInt(), mediaType: mediaType),
      ),
    );
  }

  Future<void> _openCommunityEpisode(Map<String, dynamic> activity) async {
    final rawShowId = activity['tmdb_id'];

    final rawSeason = activity['season_number'];

    final rawEpisode = activity['episode_number'];

    if (rawShowId is! num || rawSeason is! num || rawEpisode is! num) {
      return;
    }

    final showId = rawShowId.toInt();

    final seasonNumber = rawSeason.toInt();

    final episodeNumber = rawEpisode.toInt();

    try {
      final episodes = await TmdbService().getSeasonEpisodes(
        showId,
        seasonNumber,
      );

      Map<String, dynamic>? foundEpisode;

      for (final raw in episodes) {
        final episode = Map<String, dynamic>.from(raw);

        final number = episode['episode_number'];

        if (number is num && number.toInt() == episodeNumber) {
          foundEpisode = episode;

          break;
        }
      }

      if (!mounted || foundEpisode == null) {
        return;
      }

      final episode = foundEpisode;

      final rawRuntime = episode['runtime'];

      final rawRating = episode['vote_average'];

      await Navigator.push(
        context,
        MaterialPageRoute(
          builder: (_) => SwipeableEpisodePage(
            showId: showId,

            seasonNumber: seasonNumber,

            episodeNumber: episodeNumber,

            title:
                episode['name']?.toString() ??
                activity['episode_title']?.toString() ??
                'Episode',

            stillPath: episode['still_path']?.toString(),

            runtime: rawRuntime is num ? rawRuntime.toInt() : null,

            rating: rawRating is num ? rawRating.toDouble() : null,

            overview: episode['overview']?.toString() ?? '',

            airDate: episode['air_date']?.toString(),
          ),
        ),
      );
    } catch (e) {
      debugPrint('Could not open community episode: $e');
    }
  }

  Future<void> _openActivity(Map<String, dynamic> activity) async {
    final type = activity['activity_type']?.toString();

    if (type == 'achievement_unlocked') {
      await Navigator.push(
        context,
        MaterialPageRoute(builder: (_) => const AchievementsPage()),
      );

      return;
    }

    final bool isEpisodeRating =
        type == 'rated' &&
        activity['season_number'] is num &&
        activity['episode_number'] is num;

    if (type == 'episode_watched' || isEpisodeRating) {
      await _openCommunityEpisode(activity);

      return;
    }

    _openCommunityMedia(activity);
  }

  Future<void> _loadFollowers() async {
    try {
      final data = await community.getFollowers();

      final client = Supabase.instance.client;

      final currentUserId = client.auth.currentUser?.id;

      if (currentUserId == null) {
        if (!mounted) {
          return;
        }

        setState(() {
          followers = data;
          newFollowersToday = 0;
          loadingFollowers = false;
        });

        return;
      }

      // Get the actual follow timestamps.
      final followRows = await client
          .from('follows')
          .select('follower_id, created_at')
          .eq('following_id', currentUserId);

      final followedAtByUser = <String, String>{};

      for (final raw in followRows) {
        final followerId = raw['follower_id']?.toString();

        final createdAt = raw['created_at']?.toString();

        if (followerId == null || createdAt == null) {
          continue;
        }

        followedAtByUser[followerId] = createdAt;
      }

      // Add followed_at to each profile.
      final enrichedFollowers = data.map((rawUser) {
        final user = Map<String, dynamic>.from(rawUser);

        final id = user['id']?.toString();

        if (id != null) {
          final followedAt = followedAtByUser[id];

          if (followedAt != null) {
            user['followed_at'] = followedAt;
          }
        }

        return user;
      }).toList();

      final prefs = await SharedPreferences.getInstance();

      final seenKey = 'community_followers_seen_at_$currentUserId';

      final seenRaw = prefs.getString(seenKey);

      final lastSeen = seenRaw != null
          ? DateTime.tryParse(seenRaw)?.toLocal()
          : null;

      final now = DateTime.now();

      bool isToday(DateTime date) {
        return date.year == now.year &&
            date.month == now.month &&
            date.day == now.day;
      }

      int unreadToday = 0;

      for (final raw in followRows) {
        final createdRaw = raw['created_at']?.toString();

        if (createdRaw == null) {
          continue;
        }

        final created = DateTime.tryParse(createdRaw)?.toLocal();

        if (created == null || !isToday(created)) {
          continue;
        }

        if (lastSeen == null || created.isAfter(lastSeen)) {
          unreadToday++;
        }
      }

      if (!mounted) {
        return;
      }

      setState(() {
        followers = enrichedFollowers;

        newFollowersToday = unreadToday;

        loadingFollowers = false;
      });
    } catch (e) {
      debugPrint('Could not load followers: $e');

      if (!mounted) {
        return;
      }

      setState(() {
        loadingFollowers = false;
      });
    }
  }

  Future<void> _markFollowersSeen() async {
    final userId = Supabase.instance.client.auth.currentUser?.id;

    if (userId == null) {
      return;
    }

    if (mounted) {
      setState(() {
        newFollowersToday = 0;
      });
    }

    final prefs = await SharedPreferences.getInstance();

    await prefs.setString(
      'community_followers_seen_at_$userId',
      DateTime.now().toUtc().toIso8601String(),
    );
  }

  Future<void> _openFollowersTab() async {
    await _markFollowersSeen();

    await _loadFollowers();
  }

  Future<void> _loadFollowing() async {
    try {
      final data = await community.getFollowing();

      if (!mounted) {
        return;
      }

      setState(() {
        following = data;
        loadingFollowing = false;
      });
    } catch (e) {
      debugPrint('Could not load following: $e');

      if (!mounted) {
        return;
      }

      setState(() {
        loadingFollowing = false;
      });
    }
  }

  @override
  void dispose() {
    _activityRefreshTimer?.cancel();

    _followsRefreshTimer?.cancel();

    if (_activityChannel != null) {
      unawaited(_activityChannel!.unsubscribe());
    }

    if (_followsChannel != null) {
      unawaited(_followsChannel!.unsubscribe());
    }
    _tabController.removeListener(_onCommunityTabChanged);
    _tabController.dispose();

    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return SafeArea(
      child: Column(
        children: [
          Padding(
            padding: const EdgeInsets.fromLTRB(20, 20, 20, 12),
            child: Row(
              children: [
                const Expanded(
                  child: Text(
                    'Community',
                    style: TextStyle(fontSize: 28, fontWeight: FontWeight.bold),
                  ),
                ),

                Icon(
                  Icons.people_rounded,
                  color: chipluxCyan.withValues(alpha: 0.9),
                  size: 28,
                ),
              ],
            ),
          ),

          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16),
            child: Container(
              height: 64,
              padding: const EdgeInsets.all(4),
              decoration: BoxDecoration(
                color: chipluxSurface.withValues(alpha: 0.45),
                borderRadius: BorderRadius.circular(22),
              ),
              child: TabBar(
                controller: _tabController,

                isScrollable: true,

                tabAlignment: TabAlignment.start,

                indicator: BoxDecoration(
                  color: Colors.transparent,

                  borderRadius: BorderRadius.circular(18),

                  border: Border.all(color: chipluxCyan, width: 2),
                ),

                indicatorSize: TabBarIndicatorSize.tab,

                dividerColor: Colors.transparent,

                overlayColor: WidgetStateProperty.all(Colors.transparent),

                splashFactory: NoSplash.splashFactory,

                labelColor: chipluxCyan,

                unselectedLabelColor: Colors.white70,

                labelStyle: const TextStyle(
                  fontWeight: FontWeight.bold,
                  fontSize: 14,
                ),

                unselectedLabelStyle: const TextStyle(
                  fontWeight: FontWeight.w600,
                  fontSize: 14,
                ),

                labelPadding: const EdgeInsets.symmetric(horizontal: 20),

                tabs: [
                  const Tab(text: 'Friends Watch'),

                  const Tab(text: 'Find Friends'),

                  Tab(
                    child: Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        const Text('Followers'),

                        if (newFollowersToday > 0) ...[
                          const SizedBox(width: 6),

                          Container(
                            width: 21,
                            height: 21,
                            alignment: Alignment.center,
                            decoration: const BoxDecoration(
                              color: Color(0xFFFFC857),
                              shape: BoxShape.circle,
                            ),
                            child: FittedBox(
                              fit: BoxFit.scaleDown,
                              child: Padding(
                                padding: const EdgeInsets.all(3),
                                child: Text(
                                  '$newFollowersToday',
                                  style: const TextStyle(
                                    color: Colors.black,
                                    fontSize: 11,
                                    fontWeight: FontWeight.bold,
                                  ),
                                ),
                              ),
                            ),
                          ),
                        ],
                      ],
                    ),
                  ),

                  const Tab(text: 'Following'),
                ],
              ),
            ),
          ),

          const SizedBox(height: 12),

          Expanded(
            child: TabBarView(
              controller: _tabController,

              children: [
                // =========================
                // FRIENDS WATCH
                // =========================

                _FriendsWatchList(
                  loading: loadingFriendsWatch,

                  activities: friendsWatch,

                  onRefresh: _loadFriendsWatch,

                  onProfileTap: _openCommunityProfile,

                  onActivityTap: _openActivity,
                ),

                // =========================
                // FIND FRIENDS
                // =========================
                const _FindFriendsTab(),

                // =========================
                // FOLLOWERS
                // =========================
                _CommunityUsersList(
                  loading: loadingFollowers,

                  users: followers,

                  emptyText: 'No followers yet.',

                  onRefresh: _loadFollowers,
                ),

                // =========================
                // FOLLOWING
                // =========================
                _CommunityUsersList(
                  loading: loadingFollowing,

                  users: following,

                  emptyText: 'You are not following anyone yet.',

                  onRefresh: _loadFollowing,
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class _FindFriendsTab extends StatefulWidget {
  const _FindFriendsTab();

  @override
  State<_FindFriendsTab> createState() => _FindFriendsTabState();
}

class _FindFriendsTabState extends State<_FindFriendsTab> {
  final TextEditingController _searchController = TextEditingController();

  Timer? _debounce;

  List<Map<String, dynamic>> _results = [];

  bool _searching = false;

  String _query = '';

  int _searchGeneration = 0;

  void _onSearchChanged(String value) {
    _debounce?.cancel();

    final query = value.trim();

    _searchGeneration++;

    if (query.isEmpty) {
      setState(() {
        _query = '';
        _results = [];
        _searching = false;
      });

      return;
    }

    setState(() {
      _query = query;
      _searching = true;
    });

    final generation = _searchGeneration;

    _debounce = Timer(const Duration(milliseconds: 350), () {
      _search(query, generation);
    });
  }

  Future<void> _search(String query, int generation) async {
    try {
      final client = Supabase.instance.client;

      final result = await client.rpc(
        'search_visible_profiles',
        params: {
          'p_query': query,
          'p_limit': 20,
        },
      );

      if (!mounted || generation != _searchGeneration) {
        return;
      }

      final results = <Map<String, dynamic>>[];

      if (result is List) {
        for (final raw in result) {
          if (raw is Map) {
            results.add(Map<String, dynamic>.from(raw));
          }
        }
      }

      setState(() {
        _results = results;
        _searching = false;
      });
    } catch (e) {
      debugPrint('Could not search users: $e');

      if (!mounted || generation != _searchGeneration) {
        return;
      }

      setState(() {
        _results = [];
        _searching = false;
      });
    }
  }

  Future<void> _refresh() async {
    final query = _searchController.text.trim();

    if (query.isEmpty) {
      return;
    }

    _searchGeneration++;

    final generation = _searchGeneration;

    setState(() {
      _searching = true;
    });

    await _search(query, generation);
  }

  void _clearSearch() {
    _debounce?.cancel();

    _searchController.clear();

    _searchGeneration++;

    setState(() {
      _query = '';
      _results = [];
      _searching = false;
    });
  }

  @override
  void dispose() {
    _debounce?.cancel();

    _searchController.dispose();

    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(16, 4, 16, 12),
          child: TextField(
            controller: _searchController,

            onChanged: _onSearchChanged,

            textInputAction: TextInputAction.search,

            decoration: InputDecoration(
              hintText: 'Search name or username',

              prefixIcon: const Icon(Icons.search_rounded),

              suffixIcon: _query.isNotEmpty
                  ? IconButton(
                      onPressed: _clearSearch,
                      icon: const Icon(Icons.close_rounded),
                    )
                  : null,

              filled: true,

              fillColor: chipluxSurface.withValues(alpha: 0.88),

              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(16),
                borderSide: BorderSide.none,
              ),

              enabledBorder: OutlineInputBorder(
                borderRadius: BorderRadius.circular(16),
                borderSide: BorderSide(
                  color: Colors.white.withValues(alpha: 0.05),
                ),
              ),

              focusedBorder: OutlineInputBorder(
                borderRadius: BorderRadius.circular(16),
                borderSide: const BorderSide(color: chipluxCyan, width: 1.5),
              ),
            ),
          ),
        ),

        Expanded(
          child: _CommunityUsersList(
            loading: _searching,

            users: _results,

            emptyText: _query.isEmpty
                ? 'Search for friends by display name or username.'
                : 'No users found.',

            onRefresh: _refresh,
          ),
        ),
      ],
    );
  }
}

class _CommunityUsersList extends StatelessWidget {
  final bool loading;

  final List<Map<String, dynamic>> users;

  final String emptyText;

  final Future<void> Function() onRefresh;

  const _CommunityUsersList({
    required this.loading,
    required this.users,
    required this.emptyText,
    required this.onRefresh,
  });

  @override
  Widget build(BuildContext context) {
    if (loading) {
      return const Center(child: CircularProgressIndicator());
    }

    if (users.isEmpty) {
      return Center(
        child: Text(emptyText, style: const TextStyle(color: Colors.white54)),
      );
    }

    return RefreshIndicator(
      onRefresh: onRefresh,
      child: ListView.separated(
        padding: const EdgeInsets.fromLTRB(16, 4, 16, 25),

        itemCount: users.length,

        separatorBuilder: (context, index) => const SizedBox(height: 10),

        itemBuilder: (context, index) {
          final user = users[index];

          final displayName = user['display_name']?.toString().trim() ?? '';

          final username = user['username']?.toString().trim() ?? '';

          final avatarUrl = user['avatar_url']?.toString();

          final followedAtRaw = user['followed_at']?.toString();

          final followedAt = followedAtRaw != null
              ? DateTime.tryParse(followedAtRaw)?.toLocal()
              : null;

          final now = DateTime.now();

          final isNewToday =
              followedAt != null &&
              followedAt.year == now.year &&
              followedAt.month == now.month &&
              followedAt.day == now.day;

          final name = displayName.isNotEmpty
              ? displayName
              : username.isNotEmpty
              ? username
              : 'Chiplux User';

          return InkWell(
            borderRadius: BorderRadius.circular(16),

            onTap: () async {
              final userId = user['id']?.toString();

              if (userId == null || userId.isEmpty) {
                return;
              }

              await Navigator.push(
                context,
                MaterialPageRoute(
                  builder: (_) => PublicProfilePage(userId: userId),
                ),
              );
            },

            child: Container(
              padding: const EdgeInsets.all(14),

              decoration: BoxDecoration(
                color: chipluxSurface,
                borderRadius: BorderRadius.circular(16),

                border: Border.all(color: Colors.white.withValues(alpha: 0.05)),
              ),

              child: Row(
                children: [
                  CircleAvatar(
                    radius: 24,

                    backgroundColor: chipluxSurfaceLight,

                    backgroundImage: avatarUrl != null && avatarUrl.isNotEmpty
                        ? NetworkImage(avatarUrl)
                        : null,

                    child: avatarUrl == null || avatarUrl.isEmpty
                        ? const Icon(Icons.person, color: Colors.white54)
                        : null,
                  ),

                  const SizedBox(width: 13),

                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,

                      children: [
                        Text(
                          name,
                          style: const TextStyle(
                            fontSize: 16,
                            fontWeight: FontWeight.bold,
                          ),
                        ),

                        if (username.isNotEmpty) ...[
                          const SizedBox(height: 3),

                          Text(
                            '@$username',
                            style: const TextStyle(
                              color: Colors.white54,
                              fontSize: 13,
                            ),
                          ),
                        ],
                      ],
                    ),
                  ),

                  Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.end,
                    children: [
                      if (isNewToday) ...[
                        const Text(
                          'New',
                          style: TextStyle(
                            color: Color(0xFFFFC857),
                            fontSize: 12,
                            fontWeight: FontWeight.bold,
                          ),
                        ),

                        const SizedBox(height: 3),
                      ],

                      const Icon(
                        Icons.chevron_right_rounded,
                        color: Colors.white38,
                      ),
                    ],
                  ),
                ],
              ),
            ),
          );
        },
      ),
    );
  }
}

