class _FriendsWatchRow extends StatelessWidget {
  final Map<String, dynamic> activity;

  final Future<void> Function(String userId) onProfileTap;

  final Future<void> Function(Map<String, dynamic> activity) onActivityTap;

  const _FriendsWatchRow({
    required this.activity,
    required this.onProfileTap,
    required this.onActivityTap,
  });

  String _userName() {
    final profile = activity['profile'];

    if (profile is! Map) {
      return 'Chiplux User';
    }

    final displayName = profile['display_name']?.toString().trim() ?? '';

    if (displayName.isNotEmpty) {
      return displayName;
    }

    final username = profile['username']?.toString().trim() ?? '';

    if (username.isNotEmpty) {
      return username;
    }

    return 'Chiplux User';
  }

  String? _avatarUrl() {
    final profile = activity['profile'];

    if (profile is! Map) {
      return null;
    }

    return profile['avatar_url']?.toString();
  }

  String _prefixText() {
    final type = activity['activity_type']?.toString();

    switch (type) {
      case 'episode_watched':
        final season = activity['season_number'];

        final episode = activity['episode_number'];

        if (season is num && episode is num) {
          final code =
              'S${season.toInt().toString().padLeft(2, '0')}'
              'E${episode.toInt().toString().padLeft(2, '0')}';

          return 'watched $code of';
        }

        return 'watched an episode of';

      case 'season_watched':
        final season = activity['season_number'];

        return season is num
            ? 'watched Season ${season.toInt()} of'
            : 'watched a season of';

      case 'movie_watched':
        return 'watched';

      case 'tv_watched':
        return 'has completed';

      case 'started_watching':
        return 'started watching';

      case 'rated':
        final season = activity['season_number'];

        final episode = activity['episode_number'];

        if (season is num && episode is num) {
          final code =
              'S${season.toInt().toString().padLeft(2, '0')}'
              'E${episode.toInt().toString().padLeft(2, '0')}';

          return 'rated $code of';
        }

        return 'rated';

      case 'plan_to_watch':
        return 'plans to watch';

      case 'dropped':
        return 'dropped';

      case 'favorite':
        return 'added to favorites';

      case 'achievement_unlocked':
        return 'unlocked';

      default:
        return '';
    }
  }

  String _targetText() {
    final type = activity['activity_type']?.toString();

    if (type == 'achievement_unlocked') {
      return activity['achievement_title']?.toString() ?? 'an achievement';
    }

    return activity['media_title']?.toString() ?? 'Unknown title';
  }

  String? _ratingText() {
    if (activity['activity_type'] != 'rated') {
      return null;
    }

    final stars = activity['rating_stars'];

    if (stars is! num) {
      return null;
    }

    return '★' * stars.toInt().clamp(1, 5);
  }

  String _timeAgo() {
    final raw = activity['created_at']?.toString();

    if (raw == null) {
      return '';
    }

    final date = DateTime.tryParse(raw);

    if (date == null) {
      return '';
    }

    final difference = DateTime.now().difference(date.toLocal());

    if (difference.inSeconds < 60) {
      return 'just now';
    }

    if (difference.inMinutes < 60) {
      return '${difference.inMinutes}m ago';
    }

    if (difference.inHours < 24) {
      return '${difference.inHours}h ago';
    }

    if (difference.inDays < 7) {
      return '${difference.inDays}d ago';
    }

    return '${date.day}/${date.month}/${date.year}';
  }

  @override
  Widget build(BuildContext context) {
    final userId = activity['user_id']?.toString();

    final avatarUrl = _avatarUrl();

    final name = _userName();

    final prefix = _prefixText();

    final target = _targetText();

    final rating = _ratingText();

    final type = activity['activity_type']?.toString();

    final canOpenTarget = type != 'achievement_unlocked';

    return Container(
      padding: const EdgeInsets.all(14),

      decoration: BoxDecoration(
        color: chipluxSurface.withValues(alpha: 0.88),

        borderRadius: BorderRadius.circular(18),

        border: Border.all(color: Colors.white.withValues(alpha: 0.05)),
      ),

      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,

        children: [
          InkWell(
            onTap: userId == null
                ? null
                : () {
                    onProfileTap(userId);
                  },

            borderRadius: BorderRadius.circular(30),

            child: CircleAvatar(
              radius: 23,

              backgroundColor: chipluxSurfaceLight,

              backgroundImage: avatarUrl != null && avatarUrl.isNotEmpty
                  ? NetworkImage(avatarUrl)
                  : null,

              child: avatarUrl == null || avatarUrl.isEmpty
                  ? const Icon(Icons.person, color: Colors.white54)
                  : null,
            ),
          ),

          const SizedBox(width: 12),

          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,

              children: [
                Wrap(
                  spacing: 4,
                  runSpacing: 4,
                  crossAxisAlignment: WrapCrossAlignment.center,

                  children: [
                    InkWell(
                      onTap: userId == null
                          ? null
                          : () {
                              onProfileTap(userId);
                            },

                      child: Text(
                        name,
                        style: const TextStyle(
                          fontSize: 15,
                          fontWeight: FontWeight.bold,
                          color: Colors.white,
                        ),
                      ),
                    ),

                    Text(
                      prefix,
                      style: const TextStyle(
                        color: Colors.white60,
                        fontSize: 14,
                      ),
                    ),

                    InkWell(
                      onTap: canOpenTarget
                          ? () {
                              onActivityTap(activity);
                            }
                          : null,

                      child: Text(
                        target,
                        style: TextStyle(
                          color: canOpenTarget ? chipluxCyan : chipluxViolet,

                          fontSize: 14,

                          fontWeight: FontWeight.w700,

                          decoration: canOpenTarget
                              ? TextDecoration.underline
                              : TextDecoration.none,

                          decorationColor: chipluxCyan,
                        ),
                      ),
                    ),

                    if (rating != null)
                      Text(
                        rating,
                        style: const TextStyle(
                          color: Colors.amber,
                          fontSize: 15,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                  ],
                ),

                const SizedBox(height: 7),

                Text(
                  _timeAgo(),
                  style: const TextStyle(color: Colors.white30, fontSize: 12),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class PublicStatsSyncService {
  PublicStatsSyncService._();

  static final PublicStatsSyncService instance = PublicStatsSyncService._();

  Timer? _debounce;

  bool _started = false;

  void start() {
    if (_started) {
      return;
    }

    _started = true;

    LibraryService.instance.addListener(_scheduleSync);

    FollowerCountService.instance.addListener(_scheduleSync);

    CriticService.instance.addListener(_scheduleSync);

    MedalPinService.instance.addListener(_scheduleSync);

    DailyLoginService.instance.addListener(_scheduleSync);

    PublicProfileViewService.instance.addListener(_scheduleSync);

    _scheduleSync();
  }

  void _scheduleSync() {
    _debounce?.cancel();

    _debounce = Timer(const Duration(milliseconds: 600), () {
      unawaited(syncNow());
    });
  }

  Future<void> syncNow() async {
    final client = Supabase.instance.client;

    final user = client.auth.currentUser;

    if (user == null) {
      return;
    }

    final library = LibraryService.instance;

    final critic = CriticService.instance;

    final dailyLoginService = DailyLoginService.instance;

    final tvShowsRatedAchievementGroup = _tvShowsRatedAchievementGroupFor(
      critic.tvRatingCount,
    );

    final followerAchievementGroup = _followersAchievementGroupFor(
      FollowerCountService.instance.peakFollowerCount,
    );

    final moviesRatedAchievementGroup = _moviesRatedAchievementGroupFor(
      critic.movieRatingCount,
    );

    // =========================
    // ACHIEVEMENT GROUPS
    // =========================

    final movieAchievementGroup = _movieAchievementGroupFor(
      library.moviesWatchedCount,
    );

    final tvAchievementGroup = _tvAchievementGroupFor(
      library.completedTvShowsCount,
    );

    final episodeAchievementGroup = _episodeAchievementGroupFor(
      library.watchedEpisodeCount,
    );

    final episodeRatedAchievementGroup = _episodeRatedAchievementGroupFor(
      critic.episodeRatingCount,
    );

    final runtimeLevel = _runtimeLevelForMinutes(library.totalWatchedMinutes);

    final runtimeLevelAchievementGroup = _runtimeLevelAchievementGroupFor(
      runtimeLevel,
    );

    final ratingsLevelAchievementGroup = _ratingsLevelAchievementGroupFor(
      critic.level,
    );

    final dailyLoginAchievementGroup = _dailyLoginAchievementGroupFor(
      dailyLoginService.loginDays,
    );

    final publicProfileAchievementGroup = _publicProfileViewAchievementGroupFor(
      PublicProfileViewService.instance.viewCount,
    );

    // =========================
    // UNLOCKED ACHIEVEMENTS
    // =========================

    final unlockedIds = <String>[
      ...movieAchievementGroup.tiers
          .where((achievement) => achievement.unlocked)
          .map((achievement) => achievement.id),

      ...tvAchievementGroup.tiers
          .where((achievement) => achievement.unlocked)
          .map((achievement) => achievement.id),

      ...episodeAchievementGroup.tiers
          .where((achievement) => achievement.unlocked)
          .map((achievement) => achievement.id),

      ...followerAchievementGroup.tiers
          .where((achievement) => achievement.unlocked)
          .map((achievement) => achievement.id),

      ...dailyLoginAchievementGroup.tiers
          .where((achievement) => achievement.unlocked)
          .map((achievement) => achievement.id),

      ...ratingsLevelAchievementGroup.tiers
          .where((achievement) => achievement.unlocked)
          .map((achievement) => achievement.id),

      ...publicProfileAchievementGroup.tiers
          .where((achievement) => achievement.unlocked)
          .map((achievement) => achievement.id),

      ...episodeRatedAchievementGroup.tiers
          .where((achievement) => achievement.unlocked)
          .map((achievement) => achievement.id),

      ...runtimeLevelAchievementGroup.tiers
          .where((achievement) => achievement.unlocked)
          .map((achievement) => achievement.id),

      ...tvShowsRatedAchievementGroup.tiers
          .where((achievement) => achievement.unlocked)
          .map((achievement) => achievement.id),

      ...moviesRatedAchievementGroup.tiers
          .where((achievement) => achievement.unlocked)
          .map((achievement) => achievement.id),
    ];

    // =========================
    // GENRE RUNTIME
    // =========================

    final genreRuntime = _buildGenreRuntime(library);

    // =========================
    // RATING DISTRIBUTION
    // =========================

    final distribution = <String, int>{};

    for (int rating = 1; rating <= 5; rating++) {
      distribution['$rating'] = critic.ratingDistribution[rating] ?? 0;
    }

    // =========================
    // SYNC
    // =========================

    try {
      await client
          .from('profiles')
          .update({
            'public_stats': {
              'total_watched_minutes': library.totalWatchedMinutes,

              'movie_watched_minutes': library.watchedMovieMinutes,

              'episode_watched_minutes': library.watchedEpisodeMinutes,

              'viewer_title': library.viewerTitle,

              'movies_watched': library.moviesWatchedCount,

              'followers_count': FollowerCountService.instance.followerCount,

              'followers_peak_count':
                  FollowerCountService.instance.peakFollowerCount,

              'episodes_watched': library.watchedEpisodeCount,

              'tv_shows_completed': library.completedTvShowsCount,

              'login_days': dailyLoginService.loginDays,

              'movie_ratings': critic.movieRatingCount,

              'tv_ratings': critic.tvRatingCount,

              'title_ratings': critic.movieRatingCount + critic.tvRatingCount,

              'public_profiles_viewed':
                  PublicProfileViewService.instance.viewCount,

              'critic_level': critic.level,

              'critic_title': critic.title,

              'critic_xp': critic.xpInLevel,

              'critic_required_xp': critic.requiredXp,

              'total_ratings': critic.totalRatings,

              'episode_ratings': critic.episodeRatingCount,

              'average_stars': critic.averageStars,

              'title_coverage': critic.titleRatingCoverage,

              'episode_coverage': critic.episodeRatingCoverage,

              'rating_distribution': distribution,

              'genre_runtime': genreRuntime,

              'unlocked_achievement_ids': unlockedIds,
            },

            'pinned_achievement_id':
                MedalPinService.instance.pinnedAchievementId,
          })
          .eq('id', user.id);
    } catch (e) {
      debugPrint('Could not sync public profile stats: $e');
    }
  }

  List<Map<String, dynamic>> _buildGenreRuntime(LibraryService library) {
    final titleCounts = <int, int>{};

    final watchedMinutes = <int, int>{};

    for (final item in library.items) {
      final genres = item.genreIds.toSet();

      if (genres.isEmpty) {
        continue;
      }

      final itemMinutes = library.watchedMinutesForItem(item);

      for (final genreId in genres) {
        titleCounts[genreId] = (titleCounts[genreId] ?? 0) + 1;

        watchedMinutes[genreId] = (watchedMinutes[genreId] ?? 0) + itemMinutes;
      }
    }

    final total = watchedMinutes.values.fold<int>(
      0,
      (sum, minutes) => sum + minutes,
    );

    final result = <Map<String, dynamic>>[];

    for (final entry in watchedMinutes.entries) {
      final genreId = entry.key;

      final minutes = entry.value;

      result.add({
        'genre_id': genreId,

        'title_count': titleCounts[genreId] ?? 0,

        'minutes': minutes,

        'percentage': total <= 0 ? 0.0 : minutes / total,
      });
    }

    result.sort((a, b) => (b['minutes'] as int).compareTo(a['minutes'] as int));

    return result;
  }
}

class _PublicCompletedTvShowsPage extends StatefulWidget {
  final String userId;
  final String displayName;
  final bool sortByRated;

  const _PublicCompletedTvShowsPage({
    required this.userId,
    required this.displayName,
    this.sortByRated = false,
  });

  @override
  State<_PublicCompletedTvShowsPage> createState() =>
      _PublicCompletedTvShowsPageState();
}

class _PublicCompletedTvShowsPageState
    extends State<_PublicCompletedTvShowsPage> {
  bool loading = true;

  String? errorMessage;

  List<Map<String, dynamic>> shows = [];

  @override
  void initState() {
    super.initState();

    _loadShows();
  }

  Future<void> _loadShows() async {
    setState(() {
      loading = true;
      errorMessage = null;
    });

    final allowed = await Supabase.instance.client.rpc(
      'can_view_public_media_list',
      params: {
        'p_target_user_id': widget.userId,
        'p_require_ratings': widget.sortByRated,
      },
    );

    if (allowed != true) {
      if (!mounted) {
        return;
      }

      setState(() {
        loading = false;
        shows = [];
        errorMessage =
            'This user is not sharing this profile information.';
      });

      return;
    }

    try {
      final result = await Supabase.instance.client.rpc(
        'get_public_completed_tv_shows',
        params: {
          'p_user_id': widget.userId,
          'p_sort_rated': widget.sortByRated,
        },
      );

      final loadedShows = <Map<String, dynamic>>[];

      if (result is List) {
        for (final item in result) {
          if (item is Map) {
            loadedShows.add(Map<String, dynamic>.from(item));
          }
        }
      }

      if (!mounted) {
        return;
      }

      setState(() {
        shows = loadedShows;
        loading = false;
      });
    } catch (e) {
      debugPrint('Could not load public completed TV shows: $e');

      if (!mounted) {
        return;
      }

      setState(() {
        loading = false;
        errorMessage = 'Could not load completed TV shows.';
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: chipluxBackground,

      body: ChipluxBackground(
        style: ChipluxBackgroundStyle.profile,

        child: SafeArea(
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(10, 8, 18, 8),

                child: Row(
                  children: [
                    IconButton(
                      onPressed: () {
                        Navigator.pop(context);
                      },

                      icon: const Icon(Icons.arrow_back_rounded),
                    ),

                    const SizedBox(width: 4),

                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,

                        children: [
                          Text(
                            '${widget.displayName}\'s TV Shows',

                            maxLines: 1,

                            overflow: TextOverflow.ellipsis,

                            style: const TextStyle(
                              color: Colors.white,
                              fontSize: 19,
                              fontWeight: FontWeight.bold,
                            ),
                          ),

                          const SizedBox(height: 2),

                          Text(
                            '${shows.length} completed',

                            style: const TextStyle(
                              color: Colors.white38,
                              fontSize: 12,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              ),

              Divider(height: 1, color: Colors.white.withValues(alpha: 0.06)),

              Expanded(
                child: loading
                    ? const Center(
                        child: CircularProgressIndicator(color: chipluxCyan),
                      )
                    : errorMessage != null
                    ? _buildError()
                    : shows.isEmpty
                    ? _buildEmpty()
                    : RefreshIndicator(
                        color: chipluxCyan,
                        backgroundColor: chipluxSurface,
                        onRefresh: _loadShows,

                        child: GridView.builder(
                          physics: const AlwaysScrollableScrollPhysics(),

                          padding: const EdgeInsets.fromLTRB(16, 18, 16, 30),

                          gridDelegate:
                              const SliverGridDelegateWithFixedCrossAxisCount(
                                crossAxisCount: 2,
                                crossAxisSpacing: 12,
                                mainAxisSpacing: 14,
                                childAspectRatio: 0.62,
                              ),

                          itemCount: shows.length,

                          itemBuilder: (context, index) {
                            return _PublicCompletedTvShowCard(
                              show: shows[index],
                            );
                          },
                        ),
                      ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildEmpty() {
    return Center(
      child: Padding(
        padding: const EdgeInsets.all(30),

        child: Column(
          mainAxisSize: MainAxisSize.min,

          children: [
            const Icon(Icons.tv_rounded, color: Colors.white24, size: 48),

            const SizedBox(height: 14),

            Text(
              '${widget.displayName} has no completed TV shows yet.',

              textAlign: TextAlign.center,

              style: const TextStyle(
                color: Colors.white54,
                fontSize: 14,
                fontWeight: FontWeight.w600,
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildError() {
    return Center(
      child: Padding(
        padding: const EdgeInsets.all(30),

        child: Column(
          mainAxisSize: MainAxisSize.min,

          children: [
            const Icon(
              Icons.error_outline_rounded,
              color: Colors.white38,
              size: 42,
            ),

            const SizedBox(height: 12),

            Text(errorMessage!, style: const TextStyle(color: Colors.white54)),

            const SizedBox(height: 16),

            OutlinedButton(
              onPressed: _loadShows,

              child: const Text('Try Again'),
            ),
          ],
        ),
      ),
    );
  }
}

class _PublicCompletedTvShowCard extends StatelessWidget {
  final Map<String, dynamic> show;

  const _PublicCompletedTvShowCard({required this.show});

  @override
  Widget build(BuildContext context) {
    final rawId = show['tmdb_id'];

    final int? id = rawId is num
        ? rawId.toInt()
        : int.tryParse(rawId?.toString() ?? '');

    final title = show['title']?.toString().trim() ?? '';

    final year = show['year']?.toString().trim() ?? '';

    final rawRating = show['rating'];

    final int? ratingStars = rawRating is num
