class _PublicWatchedMoviesPage extends StatefulWidget {
  final String userId;
  final String displayName;
  final bool sortByRated;

  const _PublicWatchedMoviesPage({
    required this.userId,
    required this.displayName,
    this.sortByRated = false,
  });

  @override
  State<_PublicWatchedMoviesPage> createState() =>
      _PublicWatchedMoviesPageState();
}

class _PublicWatchedMoviesPageState extends State<_PublicWatchedMoviesPage> {
  bool loading = true;

  String? errorMessage;

  List<Map<String, dynamic>> movies = [];

  @override
  void initState() {
    super.initState();

    _loadMovies();
  }

  Future<void> _loadMovies() async {
    setState(() {
      loading = true;
      errorMessage = null;
    });

    final allowed = await Supabase.instance.client.rpc(
      'can_view_public_media_list',
      params: {
        'p_target_user_id': widget.userId,
        'p_require_ratings': widget.sortByRated,
      },
    );

    if (allowed != true) {
      if (!mounted) {
        return;
      }

      setState(() {
        loading = false;
        movies = [];
        errorMessage =
            'This user is not sharing this profile information.';
      });

      return;
    }

    try {
      final result = await Supabase.instance.client.rpc(
        'get_public_watched_movies',
        params: {
          'p_user_id': widget.userId,
          'p_sort_rated': widget.sortByRated,
        },
      );

      final loadedMovies = <Map<String, dynamic>>[];

      if (result is List) {
        for (final item in result) {
          if (item is Map) {
            loadedMovies.add(Map<String, dynamic>.from(item));
          }
        }
      }

      if (!mounted) {
        return;
      }

      setState(() {
        movies = loadedMovies;
        loading = false;
      });
    } catch (e) {
      debugPrint('Could not load public watched movies: $e');

      if (!mounted) {
        return;
      }

      setState(() {
        loading = false;
        errorMessage = 'Could not load watched movies.';
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: chipluxBackground,

      body: ChipluxBackground(
        style: ChipluxBackgroundStyle.profile,

        child: SafeArea(
          child: Column(
            children: [
              // =========================
              // TOP BAR
              // =========================
              Padding(
                padding: const EdgeInsets.fromLTRB(10, 8, 18, 8),

                child: Row(
                  children: [
                    IconButton(
                      onPressed: () {
                        Navigator.pop(context);
                      },

                      icon: const Icon(Icons.arrow_back_rounded),
                    ),

                    const SizedBox(width: 4),

                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,

                        children: [
                          Text(
                            '${widget.displayName}\'s Movies',

                            maxLines: 1,

                            overflow: TextOverflow.ellipsis,

                            style: const TextStyle(
                              color: Colors.white,
                              fontSize: 19,
                              fontWeight: FontWeight.bold,
                            ),
                          ),

                          const SizedBox(height: 2),

                          Text(
                            '${movies.length} watched',

                            style: const TextStyle(
                              color: Colors.white38,
                              fontSize: 12,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              ),

              Divider(height: 1, color: Colors.white.withValues(alpha: 0.06)),

              // =========================
              // CONTENT
              // =========================
              Expanded(
                child: loading
                    ? const Center(
                        child: CircularProgressIndicator(color: chipluxCyan),
                      )
                    : errorMessage != null
                    ? _buildError()
                    : movies.isEmpty
                    ? _buildEmpty()
                    : RefreshIndicator(
                        color: chipluxCyan,
                        backgroundColor: chipluxSurface,
                        onRefresh: _loadMovies,
                        child: GridView.builder(
                          physics: const AlwaysScrollableScrollPhysics(),
                          padding: const EdgeInsets.fromLTRB(16, 18, 16, 30),
                          gridDelegate:
                              const SliverGridDelegateWithFixedCrossAxisCount(
                                crossAxisCount: 2,
                                crossAxisSpacing: 12,
                                mainAxisSpacing: 14,
                                childAspectRatio: 0.62,
                              ),
                          itemCount: movies.length,
                          itemBuilder: (context, index) {
                            return _PublicWatchedMovieCard(
                              movie: movies[index],
                            );
                          },
                        ),
                      ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _buildEmpty() {
    return Center(
      child: Padding(
        padding: const EdgeInsets.all(30),

        child: Column(
          mainAxisSize: MainAxisSize.min,

          children: [
            const Icon(Icons.movie_outlined, color: Colors.white24, size: 48),

            const SizedBox(height: 14),

            Text(
              '${widget.displayName} has no watched movies yet.',

              textAlign: TextAlign.center,

              style: const TextStyle(
                color: Colors.white54,
                fontSize: 14,
                fontWeight: FontWeight.w600,
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildError() {
    return Center(
      child: Padding(
        padding: const EdgeInsets.all(30),

        child: Column(
          mainAxisSize: MainAxisSize.min,

          children: [
            const Icon(
              Icons.error_outline_rounded,
              color: Colors.white38,
              size: 42,
            ),

            const SizedBox(height: 12),

            Text(errorMessage!, style: const TextStyle(color: Colors.white54)),

            const SizedBox(height: 16),

            OutlinedButton(
              onPressed: _loadMovies,

              child: const Text('Try Again'),
            ),
          ],
        ),
      ),
    );
  }
}

