List<_AchievementGroup> _currentUserProfileTitleGroups() {
  final library = LibraryService.instance;

  final critic = CriticService.instance;

  final runtimeLevel = _runtimeLevelForMinutes(library.totalWatchedMinutes);

  final normalGroups = <_AchievementGroup>[
    // MOVIES
    _movieAchievementGroupFor(library.moviesWatchedCount),

    _moviesRatedAchievementGroupFor(critic.movieRatingCount),

    // TV
    _tvAchievementGroupFor(library.completedTvShowsCount),

    _episodeAchievementGroupFor(library.watchedEpisodeCount),

    _tvShowsRatedAchievementGroupFor(critic.tvRatingCount),

    _episodeRatedAchievementGroupFor(critic.episodeRatingCount),

    // COMMUNITY
    _publicProfileViewAchievementGroupFor(
      PublicProfileViewService.instance.viewCount,
    ),

    _followersAchievementGroupFor(
      FollowerCountService.instance.peakFollowerCount,
    ),

    // CHIPLUX
    _dailyLoginAchievementGroupFor(DailyLoginService.instance.loginDays),

    _runtimeLevelAchievementGroupFor(runtimeLevel),

    _ratingsLevelAchievementGroupFor(critic.level),
  ];

  final unlockedCount = _unlockedAchievementCount(normalGroups);

  return [...normalGroups, _medalCollectionAchievementGroupFor(unlockedCount)];
}

_Achievement? _findProfileTitleAchievement(
  Iterable<_AchievementGroup> groups,
  String? achievementId, {
  bool requireUnlocked = true,
}) {
  if (achievementId == null || achievementId.isEmpty) {
    return null;
  }

  for (final group in groups) {
    for (final tier in group.tiers) {
      if (tier.id != achievementId) {
        continue;
      }

      if (requireUnlocked && !tier.unlocked) {
        return null;
      }

      return tier;
    }
  }

  return null;
}


class _PublicGenreRuntimeCard extends StatefulWidget {
  final List<Map<String, dynamic>> stats;

  const _PublicGenreRuntimeCard({required this.stats});

  @override
  State<_PublicGenreRuntimeCard> createState() =>
      _PublicGenreRuntimeCardState();
}

class _PublicGenreRuntimeCardState extends State<_PublicGenreRuntimeCard> {
  bool expanded = false;

  String _formatRuntime(int totalMinutes) {
    final hours = totalMinutes ~/ 60;

    final minutes = totalMinutes % 60;

    if (hours > 0 && minutes > 0) {
      return '${hours}h ${minutes}m';
    }

    if (hours > 0) {
      return '${hours}h';
    }

    return '${minutes}m';
  }

  @override
  Widget build(BuildContext context) {
    final stats = widget.stats;

    final visible = expanded ? stats : stats.take(4).toList();

    const colors = <Color>[
      chipluxCyan,
      Color(0xFF55C7FF),
      chipluxViolet,
      chipluxPurple,
      Color(0xFF6F7CFF),
      Color(0xFF43B8FF),
      Color(0xFFB56DFF),
      Color(0xFF5363B8),
    ];

    Color statColor(int index) {
      return colors[index % colors.length];
    }

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        color: chipluxSurface,
        borderRadius: BorderRadius.circular(22),
        border: Border.all(color: chipluxCyan.withValues(alpha: 0.14)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Row(
            children: [
              Icon(Icons.bar_chart_rounded, color: chipluxCyan, size: 27),

              SizedBox(width: 10),

              Text(
                'Genre Runtime',
                style: TextStyle(fontSize: 22, fontWeight: FontWeight.bold),
              ),
            ],
          ),

          const SizedBox(height: 20),

          if (stats.isEmpty)
            const Text(
              'No genre runtime yet.',
              style: TextStyle(color: Colors.white54),
            )
          else ...[
            ClipRRect(
              borderRadius: BorderRadius.circular(30),
              child: SizedBox(
                height: 20,
                child: Row(
                  children: stats
                      .asMap()
                      .entries
                      .where((entry) {
                        final minutes = entry.value['minutes'];

                        return minutes is num && minutes.toInt() > 0;
                      })
                      .map((entry) {
                        final minutes = (entry.value['minutes'] as num).toInt();

                        return Expanded(
                          flex: minutes,
                          child: Container(color: statColor(entry.key)),
                        );
                      })
                      .toList(),
                ),
              ),
            ),

            const SizedBox(height: 18),

            for (int i = 0; i < visible.length; i++) ...[
              Builder(
                builder: (context) {
                  final stat = visible[i];

                  final genre = stat['genre']?.toString() ?? 'Other';

                  final minutes = stat['minutes'] is num
                      ? (stat['minutes'] as num).toInt()
                      : 0;

                  final percentage = stat['percentage'] is num
                      ? (stat['percentage'] as num).toDouble()
                      : 0.0;

                  return Padding(
                    padding: const EdgeInsets.symmetric(vertical: 8),
                    child: Row(
                      children: [
                        Container(
                          width: 10,
                          height: 10,
                          decoration: BoxDecoration(
                            shape: BoxShape.circle,
                            color: statColor(i),
                          ),
                        ),

                        const SizedBox(width: 10),

                        Expanded(
                          child: Text(
                            genre,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(fontWeight: FontWeight.w600),
                          ),
                        ),

                        SizedBox(
                          width: 62,
                          child: Text(
                            '${percentage.toStringAsFixed(1)}%',
                            textAlign: TextAlign.right,
                            style: const TextStyle(fontWeight: FontWeight.bold),
                          ),
                        ),

                        const SizedBox(width: 12),

                        SizedBox(
                          width: 75,
                          child: Text(
                            _formatRuntime(minutes),
                            textAlign: TextAlign.right,
                            style: const TextStyle(color: Colors.white60),
                          ),
                        ),
                      ],
                    ),
                  );
                },
              ),
            ],

            if (stats.length > 4) ...[
              const SizedBox(height: 10),

              InkWell(
                borderRadius: BorderRadius.circular(14),
                onTap: () {
                  setState(() {
                    expanded = !expanded;
                  });
                },
                child: Container(
                  width: double.infinity,
                  padding: const EdgeInsets.symmetric(vertical: 11),
                  decoration: BoxDecoration(
                    color: chipluxSurfaceLight.withValues(alpha: 0.55),
                    borderRadius: BorderRadius.circular(14),
                  ),
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      Text(
                        expanded
                            ? 'Show less'
                            : 'Show all ${stats.length} genres',
                        style: const TextStyle(
                          color: chipluxCyan,
                          fontWeight: FontWeight.w600,
                        ),
                      ),

                      const SizedBox(width: 5),

                      Icon(
                        expanded
                            ? Icons.keyboard_arrow_up_rounded
                            : Icons.keyboard_arrow_down_rounded,
                        color: chipluxCyan,
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ],
        ],
      ),
    );
  }
}

class _PublicRatingDistributionCard extends StatelessWidget {
  final Map<int, int> distribution;

  const _PublicRatingDistributionCard({required this.distribution});

  @override
  Widget build(BuildContext context) {
    const criticGold = Color(0xFFFFC857);

    const criticOrange = Color(0xFFFF8A4C);

    final total = distribution.values.fold<int>(0, (sum, value) => sum + value);

    Color ratingColor(int rating) {
      final t = (rating - 1) / 4;

      if (t < 0.5) {
        return Color.lerp(criticOrange, criticGold, t * 2)!;
      }

      return Color.lerp(criticGold, chipluxPurple, (t - 0.5) * 2)!;
    }

    final active = <int>[];

    for (int rating = 1; rating <= 5; rating++) {
      if ((distribution[rating] ?? 0) > 0) {
        active.add(rating);
      }
    }

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        color: chipluxSurface,
        borderRadius: BorderRadius.circular(22),
        border: Border.all(color: criticGold.withValues(alpha: 0.14)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Row(
            children: [
              Icon(Icons.star_rate_rounded, color: criticGold, size: 27),

              SizedBox(width: 10),

              Text(
                'Rating Distribution',
                style: TextStyle(fontSize: 22, fontWeight: FontWeight.bold),
              ),
            ],
          ),

          const SizedBox(height: 20),

          ClipRRect(
            borderRadius: BorderRadius.circular(30),
            child: Container(
              height: 20,
              color: Colors.white10,
              child: active.isEmpty
                  ? const SizedBox.expand()
                  : Row(
                      children: active.map((rating) {
                        final count = distribution[rating] ?? 0;

                        return Expanded(
                          flex: count,
                          child: Container(color: ratingColor(rating)),
                        );
                      }).toList(),
                    ),
            ),
          ),

          const SizedBox(height: 18),

          for (int rating = 1; rating <= 5; rating++) ...[
            Builder(
              builder: (context) {
                final count = distribution[rating] ?? 0;

                final percentage = total > 0 ? (count / total) * 100 : 0.0;

                return Padding(
                  padding: const EdgeInsets.symmetric(vertical: 8),
                  child: Row(
                    children: [
                      Icon(
                        Icons.star_rounded,
                        color: ratingColor(rating),
                        size: 18,
                      ),

                      const SizedBox(width: 8),

                      SizedBox(
                        width: 50,
                        child: Text(
                          '$rating ★',
                          style: const TextStyle(fontWeight: FontWeight.bold),
                        ),
                      ),

                      Expanded(
                        child: Text(
                          '$count ${count == 1 ? 'rating' : 'ratings'}',
                          style: const TextStyle(color: Colors.white60),
                        ),
                      ),

                      SizedBox(
                        width: 64,
                        child: Text(
                          '${percentage.toStringAsFixed(1)}%',
                          textAlign: TextAlign.right,
                          style: const TextStyle(fontWeight: FontWeight.bold),
                        ),
                      ),
                    ],
                  ),
                );
              },
            ),
          ],
        ],
      ),
    );
  }
}

