  void _selectDiscoverTab(int index) {
    if (discoverTab == index) {
      return;
    }

    setState(() {
      discoverTab = index;
    });

    // Today + For You both use
    // the existing Today data loader.
    if (index == 2 || index == 3) {
      unawaited(_loadToday());
    }
  }

