  // ====================================================
  // TODAY
  // ====================================================

  String _dayKey(DateTime date) {
    return '${date.year}-'
        '${date.month.toString().padLeft(2, '0')}-'
        '${date.day.toString().padLeft(2, '0')}';
  }

  Map<String, dynamic>? _mapFromDynamic(dynamic value) {
    if (value is Map) {
      return Map<String, dynamic>.from(value);
    }

    return null;
  }

  bool _movieIsUnwatched(Map<String, dynamic> movie) {
    final id = movie['id'];

    if (id is! num) {
      return false;
    }

    final libraryItem = library.getItem(id.toInt(), 'movie');

    return libraryItem?.status != 'completed';
  }

  bool _tvIsUnwatched(Map<String, dynamic> show) {
    final id = show['id'];

    if (id is! num) {
      return false;
    }

    final showId = id.toInt();

    if (library.watchedCountForShow(showId) > 0) {
      return false;
    }

    final libraryItem = library.getItem(showId, 'tv');

    return libraryItem?.status != 'completed';
  }

  Map<String, dynamic>? _dailyPick(List<dynamic> items, int salt) {
    if (items.isEmpty) {
      return null;
    }

    final now = DateTime.now();

    final seed = now.year * 10000 + now.month * 100 + now.day + salt;

    final index = seed.abs() % items.length;

    final item = items[index];

    if (item is! Map) {
      return null;
    }

    return Map<String, dynamic>.from(item);
  }

  Map<String, dynamic>? _popularDailyPick(
    List<dynamic> items,
    int salt, {
    int topCount = 8,
  }) {
    if (items.isEmpty) {
      return null;
    }

    final validItems = items
        .whereType<Map>()
        .map((item) => Map<String, dynamic>.from(item))
        .toList();

    if (validItems.isEmpty) {
      return null;
    }

    // Most popular first.
    validItems.sort((a, b) {
      final aPopularity = a['popularity'];

      final bPopularity = b['popularity'];

      final double aValue = aPopularity is num ? aPopularity.toDouble() : 0;

      final double bValue = bPopularity is num ? bPopularity.toDouble() : 0;

      return bValue.compareTo(aValue);
    });

    // Only pick randomly from the
    // more popular part of the list.
    final shortlist = validItems.take(topCount).toList();

    return _dailyPick(shortlist, salt);
  }

  Future<Map<String, dynamic>?> _getBirthdayActor(DateTime date) async {
    try {
      final row = await Supabase.instance.client
          .from('daily_birthday_spotlights')
          .select(
            'tmdb_id, '
            'name, '
            'birth_year, '
            'age, '
            'profile_path',
          )
          .eq('spotlight_date', _dayKey(date))
          .maybeSingle();

      if (row == null) {
        return null;
      }

      final rawTmdbId = row['tmdb_id'];

      final int? tmdbId = rawTmdbId is num
          ? rawTmdbId.toInt()
          : int.tryParse(rawTmdbId?.toString() ?? '');

      return {
        'name': row['name']?.toString() ?? 'Unknown Actor',

        'birthYear': row['birth_year'],

        'age': row['age'],

        'tmdbId': tmdbId,

        'profilePath': row['profile_path']?.toString(),
      };
    } catch (e) {
      debugPrint(
        'Could not load cached '
        'birthday actor: $e',
      );

      return null;
    }
  }

  Future<Map<String, dynamic>?> _getInMemoriamActor(
  DateTime date,
) async {
  try {
    final row =
        await Supabase
            .instance
            .client
            .from(
              'daily_in_memoriam_spotlights',
            )
            .select(
              'tmdb_id, '
              'name, '
              'birth_year, '
              'death_year, '
              'age_at_death, '
              'profile_path',
            )
            .eq(
              'spotlight_date',
              _dayKey(date),
            )
            .maybeSingle();

    if (row == null) {
      return null;
    }

    final rawTmdbId =
        row['tmdb_id'];

    final int? tmdbId =
        rawTmdbId is num
            ? rawTmdbId.toInt()
            : int.tryParse(
                rawTmdbId
                        ?.toString() ??
                    '',
              );

    return {
      'name':
          row['name']
                  ?.toString() ??
              'Unknown Actor',

      'birthYear':
          row['birth_year'],

      'deathYear':
          row['death_year'],

      'ageAtDeath':
          row['age_at_death'],

      'tmdbId':
          tmdbId,

      'profilePath':
          row['profile_path']
              ?.toString(),
    };
  } catch (e) {
    debugPrint(
      'Could not load cached '
      'In Memoriam actor: $e',
    );

    return null;
  }
}

  Future<void> _loadToday({bool forceRefresh = false}) async {
    if (todayLoading) {
      return;
    }

    final now = DateTime.now();

    final today = _dayKey(now);

    if (!forceRefresh) {
      try {
        final prefs = await SharedPreferences.getInstance();

        final raw = prefs.getString(_todayCacheKey);

        if (raw != null && raw.isNotEmpty) {
          final decoded = jsonDecode(raw);

          if (decoded is Map && decoded['day'] == today) {
            final cachedMovie = _mapFromDynamic(decoded['todayMovie']);

            final cachedTv = _mapFromDynamic(decoded['todayTv']);

            final cachedRelease = _mapFromDynamic(decoded['releasedMovie']);

            final cachedAiring = _mapFromDynamic(decoded['airingTv']);

            final cachedBirthday = _mapFromDynamic(decoded['birthdayActor']);

            final cachedMemoriam = _mapFromDynamic(decoded['inMemoriamActor']);

            final movieStillValid =
                cachedMovie == null || _movieIsUnwatched(cachedMovie);

            final tvStillValid = cachedTv == null || _tvIsUnwatched(cachedTv);

            if (movieStillValid && tvStillValid) {
              if (!mounted) {
                return;
              }

              setState(() {
                todaysMovie = cachedMovie;

                todaysTvShow = cachedTv;

                releasedTodayMovie = cachedRelease;

                airingTodayTv = cachedAiring;

                birthdayActor = cachedBirthday;

                inMemoriamActor = cachedMemoriam;

                todayLoading = false;

                todayError = null;
              });

              return;
            }
          }
        }
      } catch (e) {
        debugPrint('Could not load Today cache: $e');
      }
    }

    final birthdayFuture = _getBirthdayActor(now);

    final memoriamFuture = _getInMemoriamActor(now);

    if (mounted) {
      setState(() {
        todayLoading = true;
        todayError = null;
      });
    }

    try {
      final results = await Future.wait([
        tmdbService.getDailyMoviePool(),
        tmdbService.getDailyTvPool(),
        tmdbService.getMoviesReleasedOn(now),
        tmdbService.getTvAiringOn(now),
      ]);

      final moviePool = results[0].where((item) {
        if (item is! Map) {
          return false;
        }

        return _movieIsUnwatched(Map<String, dynamic>.from(item));
      }).toList();

      final tvPool = results[1].where((item) {
        if (item is! Map) {
          return false;
        }

        return _tvIsUnwatched(Map<String, dynamic>.from(item));
      }).toList();

      final newMovie = _dailyPick(moviePool, 17);

      final newTv = _dailyPick(tvPool, 41);

      final newRelease = _popularDailyPick(results[2], 73, topCount: 8);

      final newAiring = _popularDailyPick(results[3], 101, topCount: 8);

      final newBirthdayActor = await birthdayFuture;

      final newMemoriamActor = await memoriamFuture;

      if (!mounted) return;

      setState(() {
        todaysMovie = newMovie;

        todaysTvShow = newTv;

        releasedTodayMovie = newRelease;

        airingTodayTv = newAiring;

        birthdayActor = newBirthdayActor;

        inMemoriamActor = newMemoriamActor;

        todayLoading = false;
        todayError = null;
      });

      final prefs = await SharedPreferences.getInstance();

      await prefs.setString(
        _todayCacheKey,
        jsonEncode({
          'day': today,
          'todayMovie': newMovie,
          'todayTv': newTv,
          'releasedMovie': newRelease,
          'airingTv': newAiring,
          'birthdayActor': newBirthdayActor,
          'inMemoriamActor': newMemoriamActor,
        }),
      );
    } catch (e) {
      if (!mounted) return;

      setState(() {
        todayLoading = false;
        todayError = 'Could not load today\'s picks.';
      });
    }
  }

  Future<void> _openTodayItem(
    Map<String, dynamic> item,
    String mediaType,
  ) async {
    final id = item['id'];

    if (id is! num) {
      return;
    }

    await Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => MediaDetailsPage(id: id.toInt(), mediaType: mediaType),
      ),
    );

    if (!mounted) return;

    // If the user watched/completed
    // the recommendation, replace it.
    unawaited(_loadToday());
  }

