class DiscoverTop100Page extends StatefulWidget {
  final ChipluxListDefinition definition;

  const DiscoverTop100Page({super.key, required this.definition});

  @override
  State<DiscoverTop100Page> createState() => _DiscoverTop100PageState();
}

class _DiscoverTop100PageState extends State<DiscoverTop100Page> {
  final tmdb = TmdbService();

  static final Map<ChipluxTopListType, List<dynamic>> _memoryCache = {};

  List<dynamic> items = [];

  bool loading = true;
  String? error;

  @override
  void initState() {
    super.initState();

    _load();
  }

  Future<List<dynamic>> _fetchList() {
    switch (widget.definition.type) {
      case ChipluxTopListType.movies:
        return tmdb.getTop100Movies();

      case ChipluxTopListType.tvShows:
        return tmdb.getTop100TvShows();

      case ChipluxTopListType.shortMovies:
        return tmdb.getTop100ShortMovies();

      case ChipluxTopListType.superheroMovies:
        return tmdb.getTop100SuperheroMovies();

      case ChipluxTopListType.hiddenGems:
        return tmdb.getTop100HiddenGems();
    }
  }

  Future<void> _load({bool force = false}) async {
    if (!force) {
      final cached = _memoryCache[widget.definition.type];

      if (cached != null) {
        setState(() {
          items = List<dynamic>.from(cached);

          loading = false;
          error = null;
        });

        return;
      }
    }

    setState(() {
      loading = true;
      error = null;
    });

    try {
      final result = await _fetchList();

      if (!mounted) return;

      _memoryCache[widget.definition.type] = List<dynamic>.from(result);

      setState(() {
        items = result.take(100).toList();

        loading = false;
      });
    } catch (e) {
      if (!mounted) return;

      setState(() {
        loading = false;
        error = 'Could not load this list.';
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: chipluxBackground,
      appBar: AppBar(
        backgroundColor: chipluxBackground,
        title: Text(widget.definition.title),
      ),
      body: ChipluxBackground(
        style: ChipluxBackgroundStyle.discover,
        child: loading
            ? const Center(child: CircularProgressIndicator())
            : error != null
            ? Center(
                child: Text(
                  error!,
                  style: const TextStyle(color: Colors.redAccent),
                ),
              )
            : RefreshIndicator(
                color: chipluxCyan,
                onRefresh: () {
                  return _load(force: true);
                },
                child: ListView.separated(
                  physics: const AlwaysScrollableScrollPhysics(),
                  padding: const EdgeInsets.fromLTRB(16, 12, 16, 35),
                  itemCount: items.length,
                  separatorBuilder: (_, _) => const SizedBox(height: 8),
                  itemBuilder: (context, index) {
                    final item = items[index];

                    return _Top100Row(
                      rank: index + 1,
                      item: item,
                      mediaType: widget.definition.mediaType,
                    );
                  },
                ),
              ),
      ),
    );
  }
}

class _Top100Row extends StatelessWidget {
  final int rank;
  final dynamic item;
  final String mediaType;

  const _Top100Row({
    required this.rank,
    required this.item,
    required this.mediaType,
  });

  @override
  Widget build(BuildContext context) {
    final library = LibraryService.instance;

    final critic = CriticService.instance;

    final mediaUserDataService = MediaUserDataService.instance;

    return AnimatedBuilder(
      animation: Listenable.merge([library, critic, mediaUserDataService]),

      builder: (context, _) {
        final rawId = item['id'];

        if (rawId is! num) {
          return const SizedBox.shrink();
        }

        final int id = rawId.toInt();

        final bool isTv = mediaType == 'tv';

        final title = item['title'] ?? item['name'] ?? 'Unknown';

        final posterPath = item['poster_path'];

        final posterUrl = posterPath != null
            ? 'https://image.tmdb.org/t/p/w185$posterPath'
            : null;

        final date = item['release_date'] ?? item['first_air_date'] ?? '';

        final year = date.toString().length >= 4
            ? date.toString().substring(0, 4)
            : '';

        final rating = item['vote_average'] is num
            ? (item['vote_average'] as num).toDouble()
            : 0.0;

        // =========================
        // USER LIBRARY DATA
        // =========================

        final libraryItem = library.getItem(id, mediaType);

        final bool isCompleted = libraryItem?.status == 'completed';

        // =========================
        // FAVORITE
        // =========================

        final bool isFavorite = mediaUserDataService.isFavorite(id, mediaType);

        // =========================
        // RATING
        // Same rules as Library.
        // =========================

        final int? titleRatingStars = critic.titleRatingStars(id, mediaType);

        final int ratedEpisodes = isTv
            ? critic.ratedEpisodeCountForShow(id)
            : 0;

        final int totalEpisodes = libraryItem?.totalEpisodes ?? 0;

        final bool fullyRated;

        if (isTv) {
          fullyRated =
              titleRatingStars != null &&
              totalEpisodes > 0 &&
              ratedEpisodes >= totalEpisodes;
        } else {
          fullyRated = critic.isMovieRated(id);
        }

        const Color watchedGreen = Color(0xFF7BE8A8);

        const Color ratedGold = Color(0xFFFFC857);

        const Color favoriteRed = Color(0xFFFF5C72);

        // =========================
        // SPECIAL FRAME
        // Same idea as Library.
        // =========================

        final bool hasSpecialFrame = fullyRated || isFavorite || isCompleted;

        final Gradient frameGradient;

        if (fullyRated && isFavorite) {
          // Rated + Favorite
          frameGradient = const LinearGradient(
            begin: Alignment.centerLeft,
            end: Alignment.centerRight,
            colors: [ratedGold, favoriteRed],
          );
        } else if (isCompleted && isFavorite) {
          // Completed + Favorite
          frameGradient = const LinearGradient(
            begin: Alignment.centerLeft,
            end: Alignment.centerRight,
            colors: [watchedGreen, favoriteRed],
          );
        } else if (fullyRated) {
          // Rated
          frameGradient = const LinearGradient(colors: [ratedGold, ratedGold]);
        } else if (isFavorite) {
          // Favorite
          frameGradient = const LinearGradient(
            colors: [favoriteRed, favoriteRed],
          );
        } else if (isCompleted) {
          // Completed / Watched
          frameGradient = const LinearGradient(
            colors: [watchedGreen, watchedGreen],
          );
        } else {
          // Normal
          frameGradient = LinearGradient(
            colors: [
              Colors.white.withValues(alpha: 0.05),
              Colors.white.withValues(alpha: 0.05),
            ],
          );
        }

        return Padding(
          padding: EdgeInsets.only(top: hasSpecialFrame ? 5 : 0),

          child: Container(
            padding: EdgeInsets.all(hasSpecialFrame ? 1.4 : 0),

            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(16),

              gradient: frameGradient,

              boxShadow: [
                if (fullyRated)
                  BoxShadow(
                    color: ratedGold.withValues(alpha: 0.08),
                    blurRadius: 12,
                  ),

                if (isFavorite)
                  BoxShadow(
                    color: favoriteRed.withValues(alpha: 0.07),
                    blurRadius: 12,
