  @override
  Widget build(BuildContext context) {
    final library = LibraryService.instance;

    return SafeArea(
      child: AnimatedBuilder(
        animation: Listenable.merge([
          library,
          mediaUserDataService,
          CriticService.instance,
        ]),
        builder: (context, _) {
          List<LibraryItem> items = library.items.toList();

          final bool showMediaTypeSelector =
              filter == 'favorites' ||
              filter == 'completed' ||
              filter == 'plan' ||
              filter == 'dropped';

          if (filter == 'favorites') {
            items = items.where((item) {
              return mediaUserDataService.isFavorite(item.id, item.mediaType);
            }).toList();
          } else {
            items = items.where((item) {
              return item.status == filter;
            }).toList();
          }

          if (showMediaTypeSelector) {
            items = items.where((item) {
              return item.mediaType == selectedMediaType;
            }).toList();
          }

          _sortCurrentList(items);

          return Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(20, 20, 20, 8),
                child: Row(
                  children: [
                    const BrandedTitle(
                      whitePart: 'Wa',
                      gradientPart: 'tch',
                      fontSize: 30,
                    ),

                    const Spacer(),

                    _buildSortButton(),
                  ],
                ),
              ),

              _buildAnimatedFilterBar(),

              if (filter == 'favorites' ||
                  filter == 'completed' ||
                  filter == 'plan' ||
                  filter == 'dropped')
                _mediaTypeSelector(),

              Expanded(
                child: items.isEmpty
                    ? const Center(
                        child: Text(
                          'Nothing here yet.',
                          style: TextStyle(color: Colors.white54),
                        ),
                      )
                    : filter == 'watching'
                    ? _buildWatchingContent(items)
                    : _buildNormalLibraryGrid(items),
              ),
            ],
          );
        },
      ),
    );
  }

  Widget _buildWatchingContent(List<LibraryItem> items) {
    final tvItems = items.where((item) => item.mediaType == 'tv').toList();

    tvItems.sort((a, b) {
      final aTime = _watchingRecency[a.id] ?? a.addedAt;

      final bTime = _watchingRecency[b.id] ?? b.addedAt;

      return bTime.compareTo(aTime);
    });

    final movieItems = items
        .where((item) => item.mediaType == 'movie')
        .toList();

    return ListView(
      padding: const EdgeInsets.fromLTRB(20, 18, 20, 30),
      children: [
        ...tvItems.map(
          (item) => Padding(
            padding: const EdgeInsets.only(bottom: 12),
            child: _WatchingTvCard(
              key: ValueKey('watching-${item.id}'),
              item: item,
              onMarkedWatched: () {
                unawaited(_markWatchingShowRecent(item.id));
              },
            ),
          ),
        ),

        if (movieItems.isNotEmpty) ...[
          const SizedBox(height: 8),

          LayoutBuilder(
            builder: (context, constraints) {
              int columns = 2;

              final textScale = MediaQuery.textScalerOf(context).scale(1.0);

              final scaleExtra = (textScale - 1.0).clamp(0.0, 0.5);

              final cardAspectRatio = 0.58 - (scaleExtra * 0.08);

              if (constraints.maxWidth > 900) {
                columns = 6;
              } else if (constraints.maxWidth > 650) {
                columns = 4;
              } else if (constraints.maxWidth > 450) {
                columns = 3;
              }

              return GridView.builder(
                shrinkWrap: true,
                physics: const NeverScrollableScrollPhysics(),
                gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
                  crossAxisCount: columns,
                  crossAxisSpacing: 14,
                  mainAxisSpacing: 18,
                  childAspectRatio: cardAspectRatio,
                ),
                itemCount: movieItems.length,
                itemBuilder: (context, index) {
                  final item = movieItems[index];

                  return _LibraryPosterCard(
                    item: item,
                    onMenu: () {
                      _showItemMenu(context, item);
                    },
                  );
                },
              );
            },
          ),
        ],
      ],
    );
  }

  Widget _buildNormalLibraryGrid(List<LibraryItem> items) {
    return ListView.separated(
      padding: const EdgeInsets.fromLTRB(20, 16, 20, 30),
      itemCount: items.length,
      separatorBuilder: (_, _) => const SizedBox(height: 9),
      itemBuilder: (context, index) {
        final item = items[index];

        return _LibraryListCard(item: item, showRatingInfo: true);
      },
    );
  }

  static const double _filterTabWidth = 140;
  static const double _filterTabHeight = 46;
  static const double _filterGap = 4;

  Color _filterAccent(String value) {
    switch (value) {
      case 'watching':
        return chipluxCyan;

      case 'favorites':
        return const Color(0xFFFFB84D);

      case 'completed':
        return const Color(0xFF7BE8A8);

      case 'plan':
        return chipluxPurple;

      case 'dropped':
        return const Color(0xFFFF6B6B);

      default:
        return chipluxCyan;
    }
  }

  Color _filterBackground(String value) {
    switch (value) {
      case 'watching':
        return const Color(0xFF173A50);

      case 'favorites':
        return const Color(0xFF3A2A17);

      case 'completed':
        return const Color(0xFF173A29);

      case 'plan':
        return const Color(0xFF3A2047);

      case 'dropped':
        return const Color(0xFF3A1C22);

      default:
        return chipluxSurfaceLight;
    }
  }

  IconData _filterIcon(String value) {
    switch (value) {
      case 'watching':
        return Icons.visibility_outlined;

      case 'favorites':
        return Icons.favorite;

      case 'completed':
        return Icons.emoji_events_outlined;

      case 'plan':
        return Icons.calendar_month_outlined;

      case 'dropped':
        return Icons.delete_outline;

      default:
        return Icons.circle_outlined;
    }
  }

  String _filterLabel(String value) {
    switch (value) {
      case 'watching':
        return 'Watching';

      case 'favorites':
        return 'Favorites';

      case 'completed':
        return 'Completed';

      case 'plan':
        return 'Plan';

      case 'dropped':
        return 'Dropped';

      default:
        return value;
    }
  }

  Widget _buildAnimatedFilterBar() {
    const filters = ['watching', 'favorites', 'completed', 'plan', 'dropped'];

    final rawIndex = filters.indexOf(filter);

    final selectedIndex = rawIndex < 0 ? 0 : rawIndex;

    final selectedAccent = _filterAccent(filters[selectedIndex]);

    final selectedBackground = _filterBackground(filters[selectedIndex]);

    final totalWidth =
        (_filterTabWidth * filters.length) +
        (_filterGap * (filters.length - 1)) +
        8;

    return SizedBox(
      height: 58,
      child: SingleChildScrollView(
        controller: _filterScrollController,
        scrollDirection: Axis.horizontal,
        padding: const EdgeInsets.symmetric(horizontal: 20),
        child: Container(
          width: totalWidth,
          height: 54,
          padding: const EdgeInsets.all(4),
          decoration: BoxDecoration(
            color: chipluxSurface,
            borderRadius: BorderRadius.circular(18),
          ),
          child: Stack(
            children: [
              // MOVING HIGHLIGHT
              AnimatedPositioned(
                duration: const Duration(milliseconds: 320),
                curve: Curves.easeInOutCubic,
                left: selectedIndex * (_filterTabWidth + _filterGap),
                top: 0,
                bottom: 0,
                width: _filterTabWidth,
                child: AnimatedContainer(
                  duration: const Duration(milliseconds: 280),
                  curve: Curves.easeInOut,
                  decoration: BoxDecoration(
                    color: selectedBackground,
                    borderRadius: BorderRadius.circular(14),
                    border: Border.all(
                      color: selectedAccent.withValues(alpha: 0.65),
                      width: 1.3,
                    ),
                    boxShadow: [
                      BoxShadow(
                        color: selectedAccent.withValues(alpha: 0.12),
                        blurRadius: 12,
                      ),
                    ],
                  ),
                ),
              ),

              // BUTTONS
              Row(
                children: [
                  for (int i = 0; i < filters.length; i++) ...[
                    SizedBox(
                      width: _filterTabWidth,
                      height: _filterTabHeight,
                      child: InkWell(
                        borderRadius: BorderRadius.circular(14),
                        onTap: () {
                          setState(() {
                            filter = filters[i];
                          });

                          _scrollFilterIntoView(i);
                        },
                        child: Center(
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            mainAxisAlignment: MainAxisAlignment.center,
                            crossAxisAlignment: CrossAxisAlignment.center,
                            children: [
                              Icon(
                                _filterIcon(filters[i]),
                                size: 18,
                                color: filter == filters[i]
                                    ? _filterAccent(filters[i])
                                    : Colors.white60,
                              ),

                              const SizedBox(width: 7),

                              Text(
                                _filterLabel(filters[i]),
                                style: TextStyle(
                                  fontSize: 15,
                                  fontWeight: filter == filters[i]
                                      ? FontWeight.bold
                                      : FontWeight.w500,
                                  color: filter == filters[i]
                                      ? _filterAccent(filters[i])
                                      : Colors.white70,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ),
                    ),

                    if (i != filters.length - 1)
                      const SizedBox(width: _filterGap),
                  ],
                ],
              ),
            ],
          ),
        ),
      ),
    );
  }

  void _showItemMenu(BuildContext context, LibraryItem item) {
    final library = LibraryService.instance;

    showModalBottomSheet(
      context: context,
      backgroundColor: chipluxSurface,
      builder: (context) {
        return SafeArea(
          child: Wrap(
            children: [
              _statusMenuItem(
                context,
                item,
                'watching',
                'Watching',
                Icons.play_circle_outline,
              ),
              _statusMenuItem(
                context,
                item,
                'completed',
                'Completed',
                Icons.check_circle_outline,
              ),
              _statusMenuItem(
                context,
                item,
                'plan',
                'Plan to Watch',
                Icons.bookmark_border,
              ),
              _statusMenuItem(context, item, 'dropped', 'Dropped', Icons.close),

              const Divider(),

              ListTile(
                leading: const Icon(
                  Icons.delete_outline,
                  color: Colors.redAccent,
                ),
                title: const Text(
                  'Remove from Watch',
                  style: TextStyle(color: Colors.redAccent),
                ),
                onTap: () async {
                  Navigator.pop(context);

                  await library.remove(item.id, item.mediaType);

                  await CriticService.instance.clearAllRatingsForRemovedMedia(
                    tmdbId: item.id,
                    mediaType: item.mediaType,
                  );

                  try {
                    await CommunityService.instance.deleteActivity(
                      activityType: 'rated',
                      mediaType: item.mediaType,
                      tmdbId: item.id,
                    );
                  } catch (e) {
                    debugPrint('Could not remove rating activities: $e');
                  }
                },
              ),
            ],
          ),
        );
      },
    );
  }

  Widget _statusMenuItem(
    BuildContext context,
    LibraryItem item,
    String status,
    String label,
    IconData icon,
  ) {
    return ListTile(
      leading: Icon(icon),
      title: Text(label),
      onTap: () async {
        final library = LibraryService.instance;

        final pageContext = this.context;

        final bool wasCompleted = item.status == 'completed';

        final int previousMovieCount = library.moviesWatchedCount;

        final int previousTvCount = library.completedTvShowsCount;

        await library.updateStatus(item.id, item.mediaType, status);

        if (item.mediaType == 'movie' &&
            wasCompleted &&
            status != 'completed') {
          await CriticService.instance.clearAllRatingsForRemovedMedia(
            tmdbId: item.id,
            mediaType: 'movie',
          );

          try {
            await CommunityService.instance.deleteActivity(
              activityType: 'rated',
              mediaType: 'movie',
              tmdbId: item.id,
              titleLevelOnly: true,
            );
          } catch (e) {
            debugPrint('Could not remove movie rating activity: $e');
          }
        }

        if (context.mounted) {
          Navigator.pop(context);
        }

        if (status == 'completed' && !wasCompleted) {
          await Future<void>.delayed(const Duration(milliseconds: 200));

          if (!pageContext.mounted) {
            return;
          }

          showCompletionBurst(pageContext);

          if (item.mediaType == 'movie') {
            await _checkMovieAchievementUnlock(
              pageContext,
              previousCount: previousMovieCount,
              currentCount: library.moviesWatchedCount,
            );
          } else if (item.mediaType == 'tv') {
            await _checkTvAchievementUnlock(
              pageContext,
              previousCount: previousTvCount,
              currentCount: library.completedTvShowsCount,
            );
          }
        }
      },
    );
  }
}

class _WatchingTvCard extends StatefulWidget {
  final LibraryItem item;

  final VoidCallback? onMarkedWatched;

  const _WatchingTvCard({super.key, required this.item, this.onMarkedWatched});

  @override
  State<_WatchingTvCard> createState() => _WatchingTvCardState();
}

class _WatchingTvCardState extends State<_WatchingTvCard> {
  static const String _nextEpisodeCacheKey = 'chiplux_next_episode_cache_v1';

  static final Map<int, Map<String, dynamic>> _nextEpisodeCache = {};

  static Future<void>? _cacheLoadFuture;

  final TmdbService tmdbService = TmdbService();

  final LibraryService library = LibraryService.instance;

  bool loading = true;

  double _swipeProgress = 0.0;

  int? seasonNumber;
  int? episodeNumber;

  // Total number of episodes
  // in the current season.
  int? seasonEpisodeCount;

  String episodeName = '';

  int? runtime;

  double? episodeRating;

  Future<void> _ensureCacheLoaded() {
    _cacheLoadFuture ??= _loadCacheFromDisk();

    return _cacheLoadFuture!;
  }

  Future<void> _loadCacheFromDisk() async {
    try {
      final prefs = await SharedPreferences.getInstance();

      final raw = prefs.getString(_nextEpisodeCacheKey);

      if (raw == null || raw.isEmpty) {
        return;
      }

      final decoded = jsonDecode(raw);

      if (decoded is! Map) {
        return;
      }

      for (final entry in decoded.entries) {
        final showId = int.tryParse(entry.key.toString());

        if (showId == null || entry.value is! Map) {
          continue;
        }

        _nextEpisodeCache[showId] = Map<String, dynamic>.from(entry.value);
      }
    } catch (e) {
      debugPrint('Could not load next episode cache: $e');
    }
  }

  Future<void> _saveCacheToDisk() async {
    try {
      final prefs = await SharedPreferences.getInstance();

      final data = <String, dynamic>{};

      for (final entry in _nextEpisodeCache.entries) {
        data[entry.key.toString()] = entry.value;
      }

      await prefs.setString(_nextEpisodeCacheKey, jsonEncode(data));
    } catch (e) {
      debugPrint('Could not save next episode cache: $e');
    }
  }

  void _applyCachedEpisode(Map<String, dynamic> cached) {
    final cachedRating = cached['episodeRating'];

    final cachedSeasonEpisodeCount = cached['seasonEpisodeCount'];

    setState(() {
      seasonNumber = cached['seasonNumber'] as int?;

      episodeNumber = cached['episodeNumber'] as int?;

      seasonEpisodeCount = cachedSeasonEpisodeCount is num
          ? cachedSeasonEpisodeCount.toInt()
          : null;

      episodeName = cached['episodeName']?.toString() ?? '';

      runtime = cached['runtime'] as int?;

      episodeRating = cachedRating is num ? cachedRating.toDouble() : null;

      loading = false;
    });
  }

  @override
  void initState() {
    super.initState();

    _loadCachedThenRefresh();
  }

  Future<void> _loadCachedThenRefresh() async {
    await _ensureCacheLoaded();

    if (!mounted) return;

    final cached = _nextEpisodeCache[widget.item.id];

    final currentWatched = library.watchedCountForShow(widget.item.id);

    bool validCache = false;

    bool cacheIsOld = true;

    if (cached != null && cached['watchedCount'] == currentWatched) {
      validCache = true;

      _applyCachedEpisode(cached);

      // Older cache entries won't
      // contain seasonEpisodeCount.
      // Force a background refresh
      // so they update automatically.
      final bool missingSeasonCount =
          cached['seasonNumber'] != null &&
          cached['seasonEpisodeCount'] == null;

      final updatedAt = cached['updatedAt'];

      if (updatedAt is num) {
        final age = DateTime.now().millisecondsSinceEpoch - updatedAt.toInt();

        cacheIsOld =
            missingSeasonCount ||
            age > const Duration(minutes: 15).inMilliseconds;
      } else {
        cacheIsOld = true;
      }
    }

    // No usable cached information:
    // load normally.
    if (!validCache) {
      await _loadNextEpisode(forceRefresh: true, showLoader: true);

      return;
    }

    // We already displayed the cache.
    // Only refresh TMDB in the
    // background if needed.
    if (cacheIsOld) {
      unawaited(_loadNextEpisode(forceRefresh: true, showLoader: false));
    }
  }

  Future<void> _loadNextEpisode({
    bool forceRefresh = false,
    bool showLoader = true,
  }) async {
    final int currentWatchedCount = library.watchedCountForShow(widget.item.id);

    final cached = _nextEpisodeCache[widget.item.id];

    if (!forceRefresh &&
        cached != null &&
        cached['watchedCount'] == currentWatchedCount) {
      if (!mounted) return;

      final cachedRating = cached['episodeRating'];

      final cachedSeasonEpisodeCount = cached['seasonEpisodeCount'];

      setState(() {
        seasonNumber = cached['seasonNumber'] as int?;

        episodeNumber = cached['episodeNumber'] as int?;

        seasonEpisodeCount = cachedSeasonEpisodeCount is num
            ? cachedSeasonEpisodeCount.toInt()
            : null;

        episodeName = cached['episodeName']?.toString() ?? '';

        runtime = cached['runtime'] as int?;

        episodeRating = cachedRating is num ? cachedRating.toDouble() : null;

        loading = false;
      });

      return;
    }

    if (showLoader && mounted) {
      setState(() {
        loading = true;
      });
    }

    try {
      final details = await tmdbService.getDetails(widget.item.id, 'tv');

      final List<dynamic> seasons = details['seasons'] ?? [];

      final validSeasons = seasons.where((season) {
        final number = season['season_number'];

        return number is num && number.toInt() > 0;
      }).toList();

      validSeasons.sort((a, b) {
        final aNumber = (a['season_number'] as num).toInt();

        final bNumber = (b['season_number'] as num).toInt();

        return aNumber.compareTo(bNumber);
      });

      Map<String, dynamic>? nextEpisode;

      int? foundSeason;

      int? foundSeasonEpisodeCount;

      for (final season in validSeasons) {
        final int seasonNo = (season['season_number'] as num).toInt();

        final int episodeCount = season['episode_count'] is num
            ? (season['episode_count'] as num).toInt()
            : 0;

        final int watchedInSeason = library.watchedCountForSeason(
          widget.item.id,
          seasonNo,
        );

        // Skip fully watched seasons.
        if (episodeCount > 0 && watchedInSeason >= episodeCount) {
          continue;
        }

        // Download only the first
        // incomplete season.
        final episodes = await tmdbService.getSeasonEpisodes(
          widget.item.id,
          seasonNo,
        );

        for (final rawEpisode in episodes) {
          final episode = Map<String, dynamic>.from(rawEpisode);

          final rawEpisodeNumber = episode['episode_number'];

          if (rawEpisodeNumber is! num) {
            continue;
          }

          final int episodeNo = rawEpisodeNumber.toInt();

          final watched = library.isEpisodeWatched(
            widget.item.id,
            seasonNo,
            episodeNo,
          );

          if (!watched) {
            nextEpisode = episode;

            foundSeason = seasonNo;

            foundSeasonEpisodeCount = episodeCount > 0
                ? episodeCount
                : episodes.length;

            break;
          }
        }

        if (nextEpisode != null) {
          break;
        }
      }

      if (!mounted) return;

      if (nextEpisode == null) {
        _nextEpisodeCache[widget.item.id] = {
          'watchedCount': library.watchedCountForShow(widget.item.id),

          'seasonNumber': null,
          'episodeNumber': null,
          'seasonEpisodeCount': null,

          'episodeName': 'All episodes watched',

          'runtime': null,

          'episodeRating': null,

          'updatedAt': DateTime.now().millisecondsSinceEpoch,
        };

        unawaited(_saveCacheToDisk());

        setState(() {
          seasonNumber = null;

          episodeNumber = null;

          seasonEpisodeCount = null;

          episodeName = 'All episodes watched';

          runtime = null;

          episodeRating = null;

          loading = false;
        });

        return;
      }

      final rawRuntime = nextEpisode['runtime'];

      final rawRating = nextEpisode['vote_average'];

      final int? newRuntime = rawRuntime is num ? rawRuntime.toInt() : null;

      final double? newEpisodeRating =
          rawRating is num && rawRating.toDouble() > 0
          ? rawRating.toDouble()
          : null;

      final int newEpisodeNumber = (nextEpisode['episode_number'] as num)
          .toInt();

      _nextEpisodeCache[widget.item.id] = {
        'watchedCount': library.watchedCountForShow(widget.item.id),

        'seasonNumber': foundSeason,

        'episodeNumber': newEpisodeNumber,

        'seasonEpisodeCount': foundSeasonEpisodeCount,

        'episodeName': nextEpisode['name'] ?? 'Episode',

        'runtime': newRuntime,

        'episodeRating': newEpisodeRating,

        'updatedAt': DateTime.now().millisecondsSinceEpoch,
      };

      unawaited(_saveCacheToDisk());

      setState(() {
        seasonNumber = foundSeason;

        episodeNumber = newEpisodeNumber;

        seasonEpisodeCount = foundSeasonEpisodeCount;

        episodeName = nextEpisode!['name'] ?? 'Episode';

        runtime = newRuntime;

        episodeRating = newEpisodeRating;

        loading = false;
      });
    } catch (e) {
      if (!mounted) return;

      setState(() {
        loading = false;
      });

      debugPrint('Could not load next episode: $e');
    }
  }

  Future<bool> _markWatched() async {
    if (seasonNumber == null || episodeNumber == null) {
      return false;
    }

    final int previousEpisodeCount = library.watchedEpisodeCount;

    await library.toggleEpisode(
      widget.item.id,
      seasonNumber!,
      episodeNumber!,
      runtimeMinutes: runtime ?? 0,
    );

    if (!mounted) {
      return false;
    }

    await _checkEpisodeAchievementUnlock(
      context,
      previousCount: previousEpisodeCount,
      currentCount: library.watchedEpisodeCount,
    );

    if (!mounted) {
      return false;
    }

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          'S${seasonNumber!.toString().padLeft(2, '0')}'
          'E${episodeNumber!.toString().padLeft(2, '0')} marked watched',
        ),
      ),
    );

    await _loadNextEpisode(forceRefresh: true);

    final onMarkedWatched = widget.onMarkedWatched;

    // Let the Dismissible finish
    // returning to normal first,
    // then move show to top.
    unawaited(
      Future<void>.delayed(const Duration(milliseconds: 220), () {
        onMarkedWatched?.call();
      }),
    );

    return false;
  }

  Future<void> _openNextEpisode() async {
    final int? nextSeason = seasonNumber;

    final int? nextEpisode = episodeNumber;

    // Nothing left to watch.
    if (nextSeason == null || nextEpisode == null) {
      await Navigator.push(
        context,
        MaterialPageRoute(
          builder: (_) => MediaDetailsPage(id: widget.item.id, mediaType: 'tv'),
        ),
      );

      return;
    }

    try {
      final episodes = await tmdbService.getSeasonEpisodes(
        widget.item.id,
        nextSeason,
      );

      Map<String, dynamic>? episode;

      for (final raw in episodes) {
        if (raw is! Map) {
          continue;
        }

        final map = Map<String, dynamic>.from(raw);

        final number = map['episode_number'];

        if (number is num && number.toInt() == nextEpisode) {
          episode = map;

          break;
        }
      }

      if (!mounted) {
        return;
      }

      if (episode == null) {
        return;
      }

      final rawRuntime = episode['runtime'];

      final rawRating = episode['vote_average'];

      await Navigator.push(
        context,
        MaterialPageRoute(
          builder: (_) => SwipeableEpisodePage(
            showId: widget.item.id,

            seasonNumber: nextSeason,

            episodeNumber: nextEpisode,

            title: episode?['name']?.toString() ?? episodeName,

            stillPath: episode?['still_path']?.toString(),

            runtime: rawRuntime is num ? rawRuntime.toInt() : runtime,

            rating: rawRating is num ? rawRating.toDouble() : episodeRating,

            overview: episode?['overview']?.toString() ?? '',

            airDate: episode?['air_date']?.toString(),
          ),
        ),
      );
    } catch (e) {
      debugPrint('Could not open next episode: $e');
    }

    if (!mounted) {
      return;
    }

    await _loadNextEpisode(forceRefresh: true);
  }

  @override
  Widget build(BuildContext context) {
    final posterUrl = widget.item.posterPath != null
        ? 'https://image.tmdb.org/t/p/w342${widget.item.posterPath}'
        : null;

    final watched = library.watchedCountForShow(widget.item.id);

    final total = widget.item.totalEpisodes;

    final progress = total <= 0 ? 0.0 : (watched / total).clamp(0.0, 1.0);

    final completionPercent = total <= 0
        ? 0
        : ((watched / total) * 100).round();

    return Dismissible(
      key: ValueKey('watching-${widget.item.id}'),

      direction: DismissDirection.startToEnd,

      dismissThresholds: const {DismissDirection.startToEnd: 0.22},

      movementDuration: const Duration(milliseconds: 140),

      onUpdate: (details) {
        setState(() {
          _swipeProgress = details.progress.clamp(0.0, 1.0).toDouble();
        });
      },

      confirmDismiss: (_) => _markWatched(),

      background: Container(
        padding: const EdgeInsets.all(1.2),

        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(18),

          gradient: const LinearGradient(
            begin: Alignment.centerLeft,
            end: Alignment.centerRight,
            colors: [chipluxCyan, chipluxViolet, chipluxPurple],
          ),

          boxShadow: [
            BoxShadow(
              color: chipluxViolet.withValues(
                alpha: 0.04 + (_swipeProgress * 0.12),
              ),
              blurRadius: 8 + (_swipeProgress * 10),
            ),
          ],
        ),

        child: Container(
          alignment: Alignment.centerLeft,

          padding: const EdgeInsets.symmetric(horizontal: 22),

          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(17),

            color: Color.alphaBlend(
              chipluxViolet.withValues(alpha: 0.025 + (_swipeProgress * 0.035)),
              chipluxBackground,
            ),
          ),

          child: Transform.scale(
            alignment: Alignment.centerLeft,

            scale: 0.86 + (_swipeProgress * 0.14),

            child: Opacity(
              opacity: 0.55 + (_swipeProgress * 0.45),

              child: Row(
                mainAxisSize: MainAxisSize.min,

                children: [
                  ShaderMask(
                    shaderCallback: (bounds) {
                      return const LinearGradient(
                        begin: Alignment.topLeft,
                        end: Alignment.bottomRight,
                        colors: [chipluxCyan, chipluxViolet, chipluxPurple],
                      ).createShader(bounds);
                    },

                    child: const Icon(
                      Icons.check_circle_outline_rounded,
                      color: Colors.white,
                      size: 27,
                    ),
                  ),

                  const SizedBox(width: 11),

                  const GradientText(
                    'Mark as watched',
                    style: TextStyle(fontSize: 15, fontWeight: FontWeight.w700),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),

      child: InkWell(
        borderRadius: BorderRadius.circular(18),

        onTap: () async {
          await _openNextEpisode();
        },

        child: Container(
          constraints: const BoxConstraints(minHeight: 138),

          padding: const EdgeInsets.all(8),

          decoration: BoxDecoration(
            color: chipluxSurface,

            borderRadius: BorderRadius.circular(18),

            border: Border.all(color: Colors.white.withValues(alpha: 0.06)),
          ),

          child: Row(
  children: [
                    ClipRRect(
                      borderRadius: BorderRadius.circular(12),

                      child: posterUrl != null
                          ? Image.network(
                              posterUrl,
                              width: 82,
                              height: 118,
                              fit: BoxFit.cover,
                            )
                          : Container(
                              width: 82,
                              height: 118,
                              color: chipluxSurfaceLight,
                              child: const Icon(Icons.tv_outlined),
                            ),
                    ),

                    const SizedBox(width: 10),

                    Expanded(
                      child: Column(
                        mainAxisSize: MainAxisSize.min,

                        crossAxisAlignment: CrossAxisAlignment.start,

                        children: [
                          Row(
                            children: [
                              Expanded(
                                child: Text(
                                  widget.item.title,

                                  maxLines: 1,

                                  overflow: TextOverflow.ellipsis,

                                  style: const TextStyle(
                                    fontSize: 17,

                                    fontWeight: FontWeight.bold,
                                  ),
                                ),
                              ),

                              const Icon(
                                Icons.chevron_right,

                                color: Colors.white60,
                              ),
                            ],
                          ),

                          const SizedBox(height: 6),

                          // =========================
                          // NEXT EPISODE POSITION
                          // =========================
                          if (seasonNumber != null &&
                              episodeNumber != null) ...[
                            Row(
                              children: [
                                Text(
                                  'Season $seasonNumber',

                                  style: const TextStyle(
                                    color: chipluxCyan,

                                    fontSize: 12,

                                    fontWeight: FontWeight.w700,
                                  ),
                                ),

                                const SizedBox(width: 9),

                                Container(
                                  width: 3,
                                  height: 3,

                                  decoration: const BoxDecoration(
                                    color: Colors.white24,

                                    shape: BoxShape.circle,
                                  ),
                                ),

                                const SizedBox(width: 9),

                                Text(
                                  seasonEpisodeCount != null &&
                                          seasonEpisodeCount! > 0
                                      ? 'EP ${episodeNumber!.toString().padLeft(2, '0')}'
                                            '/${seasonEpisodeCount!.toString().padLeft(2, '0')}'
                                      : 'EP ${episodeNumber!.toString().padLeft(2, '0')}',

                                  style: const TextStyle(
                                    color: Colors.white54,

                                    fontSize: 11,

                                    fontWeight: FontWeight.w600,

                                    letterSpacing: 0.2,
                                  ),
                                ),
                              ],
                            ),

                            const SizedBox(height: 3),
                          ],

                          Text(
  loading
      ? 'Loading next episode...'
      : episodeName,

                            maxLines: 1,

                            overflow: TextOverflow.ellipsis,

                            style: const TextStyle(
                              color: Colors.white70,

                              fontSize: 12,
                            ),
                          ),

                          const SizedBox(height: 8),

                          Row(
                            children: [
                              const Icon(
                                Icons.access_time_rounded,

                                size: 17,

                                color: Colors.white54,
                              ),

                              const SizedBox(width: 5),

                              Text(
                                runtime != null ? '${runtime}m' : '--m',

                                style: const TextStyle(
                                  color: Colors.white60,

                                  fontSize: 12,
                                ),
                              ),

                              const SizedBox(width: 10),

                              const Icon(
                                Icons.star,

                                size: 18,

                                color: Colors.amber,
                              ),

                              const SizedBox(width: 5),

                              Text(
                                episodeRating != null
                                    ? '${episodeRating!.toStringAsFixed(1)}/10'
                                    : '--/10',

                                style: const TextStyle(
                                  color: Colors.white60,

                                  fontSize: 13,
                                ),
                              ),
                            ],
                          ),

                          const SizedBox(height: 8),

                          Row(
                            children: [
                              Expanded(
                                child: ClipRRect(
                                  borderRadius: BorderRadius.circular(20),

                                  child: LinearProgressIndicator(
                                    value: progress,

                                    minHeight: 6,

                                    backgroundColor: Colors.white12,

                                    valueColor:
                                        const AlwaysStoppedAnimation<Color>(
                                          chipluxPurple,
                                        ),
                                  ),
                                ),
                              ),

                              const SizedBox(width: 12),

                              SizedBox(
                                width: 46,
                                height: 22,

                                child: FittedBox(
                                  fit: BoxFit.scaleDown,

                                  alignment: Alignment.centerRight,

                                  child: Text(
                                    '$completionPercent%',

                                    maxLines: 1,

                                    style: const TextStyle(
                                      fontSize: 15,

                                      fontWeight: FontWeight.bold,

                                      color: Colors.white,
                                    ),
                                  ),
                                ),
                              ),
                            ],
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
        ),
      ),
    );
  }
}

class _LibraryListCard extends StatelessWidget {
  String _genreName(int genreId) {
    switch (genreId) {
      case 28:
        return 'Action';
      case 12:
        return 'Adventure';
      case 16:
        return 'Animation';
      case 35:
        return 'Comedy';
      case 80:
        return 'Crime';
      case 99:
        return 'Documentary';
      case 18:
        return 'Drama';
      case 10751:
        return 'Family';
      case 14:
        return 'Fantasy';
      case 36:
        return 'History';
      case 27:
        return 'Horror';
      case 10402:
        return 'Music';
      case 9648:
        return 'Mystery';
      case 10749:
        return 'Romance';
      case 878:
        return 'Science Fiction';
      case 10770:
        return 'TV Movie';
      case 53:
        return 'Thriller';
      case 10752:
        return 'War';
      case 37:
        return 'Western';

      // TV
      case 10759:
        return 'Action & Adventure';
      case 10762:
        return 'Kids';
      case 10763:
        return 'News';
      case 10764:
        return 'Reality';
      case 10765:
        return 'Sci-Fi & Fantasy';
      case 10766:
        return 'Soap';
      case 10767:
        return 'Talk';
      case 10768:
        return 'War & Politics';

      default:
        return '';
    }
  }

  final LibraryItem item;
  final bool showRatingInfo;

  const _LibraryListCard({required this.item, this.showRatingInfo = false});

  @override
  Widget build(BuildContext context) {
    final library = LibraryService.instance;

    final critic = CriticService.instance;

    final mediaUserDataService = MediaUserDataService.instance;

    final bool isTv = item.mediaType == 'tv';

    final String genre = item.genreIds.isNotEmpty
        ? _genreName(item.genreIds.first)
        : '';

    final bool isFavorite = mediaUserDataService.isFavorite(
      item.id,
      item.mediaType,
    );

    const Color ratedGold = Color(0xFFFFC857);

    const Color favoriteRed = Color(0xFFFF5C72);

    final posterUrl = item.posterPath != null
        ? 'https://image.tmdb.org/t/p/w185${item.posterPath}'
        : null;

    final int watched = isTv ? library.watchedCountForShow(item.id) : 0;

    // =====================================
    // RATING INFORMATION
    // =====================================

    final int ratedEpisodes = isTv
        ? critic.ratedEpisodeCountForShow(item.id)
        : 0;

    final int? titleRatingStars = critic.titleRatingStars(
      item.id,
      item.mediaType,
    );

    final int totalEpisodes = item.totalEpisodes;

    final bool fullyRated;

    if (isTv) {
      fullyRated =
          titleRatingStars != null &&
          totalEpisodes > 0 &&
          ratedEpisodes >= totalEpisodes;
    } else {
      fullyRated = critic.isMovieRated(item.id);
    }

    final int shownRatedEpisodes = totalEpisodes > 0
        ? ratedEpisodes.clamp(0, totalEpisodes)
        : ratedEpisodes;

    final String episodeRatingText = totalEpisodes > 0
        ? '$shownRatedEpisodes/$totalEpisodes'
        : '$ratedEpisodes/?';

    final Color ratingColor = fullyRated ? ratedGold : Colors.white38;

    // =====================================
    // STATUS
    // =====================================

    String statusText;

    switch (item.status) {
      case 'completed':
        statusText = isTv ? 'Completed' : 'Watched';
        break;

      case 'plan':
        statusText = 'Plan';
        break;

      case 'dropped':
        statusText = 'Dropped';
        break;

      case 'watching':
        statusText = 'Watching';
        break;

      default:
        statusText = item.status;
    }

    Color statusColor;

    switch (item.status) {
      case 'completed':
        statusColor = const Color(0xFF7BE8A8);
        break;

      case 'plan':
        statusColor = chipluxPurple;
        break;

      case 'dropped':
        statusColor = const Color(0xFFFF6B6B);
        break;

      default:
        statusColor = chipluxCyan;
    }

    // =====================================
    // OUTER FRAME
    // =====================================

    final bool hasSpecialFrame = fullyRated || isFavorite;

    final Gradient frameGradient;

    if (fullyRated && isFavorite) {
      // Rated + Favorite
      frameGradient = const LinearGradient(
        begin: Alignment.centerLeft,
        end: Alignment.centerRight,
        colors: [ratedGold, favoriteRed],
      );
    } else if (fullyRated) {
      // Rated
      frameGradient = const LinearGradient(colors: [ratedGold, ratedGold]);
    } else if (isFavorite) {
      // Favorite
      frameGradient = const LinearGradient(colors: [favoriteRed, favoriteRed]);
    } else {
      // Normal card
      frameGradient = LinearGradient(
        colors: [
          Colors.white.withValues(alpha: 0.05),
          Colors.white.withValues(alpha: 0.05),
        ],
      );
    }

    return Padding(
      // Room for star / heart
      // sitting on the border.
      padding: EdgeInsets.only(top: showRatingInfo || isFavorite ? 10 : 0),
      child: Stack(
        clipBehavior: Clip.none,
        children: [
          // =====================================
          // OUTER FRAME
          // =====================================

          Container(
            padding: EdgeInsets.all(hasSpecialFrame ? 1.4 : 1),
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(16),
              gradient: frameGradient,
              boxShadow: [
                if (fullyRated)
                  BoxShadow(
                    color: ratedGold.withValues(alpha: 0.08),
                    blurRadius: 12,
                  ),

                if (isFavorite)
                  BoxShadow(
                    color: favoriteRed.withValues(alpha: 0.07),
                    blurRadius: 12,
                  ),
              ],
            ),

            // =====================================
            // ACTUAL CARD
            // =====================================
            child: Material(
              color: Colors.transparent,
              borderRadius: BorderRadius.circular(15),
              clipBehavior: Clip.antiAlias,
              child: InkWell(
                borderRadius: BorderRadius.circular(15),
                onTap: () {
                  Navigator.push(
                    context,
                    MaterialPageRoute(
                      builder: (_) => MediaDetailsPage(
                        id: item.id,
                        mediaType: item.mediaType,
                      ),
                    ),
                  );
                },
                child: Container(
                  constraints: const BoxConstraints(minHeight: 96),
                  padding: const EdgeInsets.all(8),
                  decoration: BoxDecoration(
                    color: chipluxSurface,
                    borderRadius: BorderRadius.circular(15),
                  ),
                  child: Row(
                    children: [
                      // =========================
                      // POSTER
                      // =========================

                      ClipRRect(
                        borderRadius: BorderRadius.circular(10),
                        child: posterUrl != null
                            ? Image.network(
                                posterUrl,
                                width: 54,
                                height: 80,
                                fit: BoxFit.cover,

                                errorBuilder: (context, error, stackTrace) {
                                  return Container(
                                    width: 54,
                                    height: 80,
                                    color: chipluxSurfaceLight,
                                    child: const Icon(
                                      Icons.movie_outlined,
                                      size: 20,
                                      color: Colors.white38,
                                    ),
                                  );
                                },
                              )
                            : Container(
                                width: 54,
                                height: 80,
                                color: chipluxSurfaceLight,
                                child: const Icon(
                                  Icons.movie_outlined,
                                  size: 20,
                                ),
                              ),
                      ),

                      const SizedBox(width: 12),

                      // =========================
                      // TITLE + INFO
                      // =========================
                      Expanded(
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              item.title,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                fontSize: 15,
                                fontWeight: FontWeight.bold,
                              ),
                            ),

                            const SizedBox(height: 6),

                            Text(
                              isTv
                                  ? [
                                      '$watched / ${item.totalEpisodes} episodes',
                                      if (genre.isNotEmpty) genre,
                                    ].join(' • ')
                                  : [
                                      if (item.year.isNotEmpty) item.year,
                                      if (genre.isNotEmpty) genre,
                                    ].join(' • '),
