class _BannerPickerSheet extends StatelessWidget {
  const _BannerPickerSheet();

  @override
  Widget build(BuildContext context) {
    final library = LibraryService.instance;

    final profile = ProfileService.instance;

    final completed = library.items.where((item) {
      return item.status == 'completed' &&
          (item.mediaType == 'movie' || item.mediaType == 'tv');
    }).toList();

    completed.sort((a, b) => b.addedAt.compareTo(a.addedAt));

    return SafeArea(
      top: false,
      child: SizedBox(
        height: MediaQuery.sizeOf(context).height * 0.78,
        child: Column(
          children: [
            const SizedBox(height: 12),

            Container(
              width: 42,
              height: 4,
              decoration: BoxDecoration(
                color: Colors.white24,
                borderRadius: BorderRadius.circular(50),
              ),
            ),

            const SizedBox(height: 18),

            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 20),
              child: Row(
                children: [
                  const Text(
                    'Choose Banner',
                    style: TextStyle(fontSize: 22, fontWeight: FontWeight.bold),
                  ),

                  const Spacer(),

                  IconButton(
                    onPressed: () {
                      Navigator.pop(context);
                    },
                    icon: const Icon(Icons.close),
                  ),
                ],
              ),
            ),

            const Padding(
              padding: EdgeInsets.fromLTRB(20, 0, 20, 16),
              child: Align(
                alignment: Alignment.centerLeft,
                child: Text(
                  'Backdrops from movies and TV shows you completed.',
                  style: TextStyle(color: Colors.white54, fontSize: 13),
                ),
              ),
            ),

            if (profile.bannerPath != null && profile.bannerPath!.isNotEmpty)
              Padding(
                padding: const EdgeInsets.fromLTRB(20, 0, 20, 14),
                child: InkWell(
                  borderRadius: BorderRadius.circular(14),
                  onTap: () async {
                    await profile.removeBanner();

                    if (context.mounted) {
                      Navigator.pop(context);
                    }
                  },
                  child: Container(
                    width: double.infinity,
                    padding: const EdgeInsets.symmetric(
                      horizontal: 15,
                      vertical: 13,
                    ),
                    decoration: BoxDecoration(
                      color: chipluxSurfaceLight,
                      borderRadius: BorderRadius.circular(14),
                    ),
                    child: const Row(
                      children: [
                        Icon(Icons.hide_image_outlined, color: Colors.white70),
                        SizedBox(width: 10),
                        Text('Remove banner'),
                      ],
                    ),
                  ),
                ),
              ),

            Expanded(
              child: completed.isEmpty
                  ? const Center(
                      child: Padding(
                        padding: EdgeInsets.all(30),
                        child: Text(
                          'Complete a movie or TV show to unlock profile banners.',
                          textAlign: TextAlign.center,
                          style: TextStyle(color: Colors.white54),
                        ),
                      ),
                    )
                  : LayoutBuilder(
                      builder: (context, constraints) {
                        final int columns;

                        if (constraints.maxWidth < 360) {
                          columns = 1;
                        } else if (constraints.maxWidth >= 750) {
                          columns = 3;
                        } else {
                          columns = 2;
                        }

                        return GridView.builder(
                          padding: const EdgeInsets.fromLTRB(20, 0, 20, 24),

                          gridDelegate:
                              SliverGridDelegateWithFixedCrossAxisCount(
                                crossAxisCount: columns,

                                crossAxisSpacing: 12,

                                mainAxisSpacing: 12,

                                childAspectRatio: 1.65,
                              ),

                          itemCount: completed.length,

                          itemBuilder: (context, index) {
                            return _BannerOptionTile(item: completed[index]);
                          },
                        );
                      },
                    ),
            ),
          ],
        ),
      ),
    );
  }
}

class _BannerOptionTile extends StatefulWidget {
  final LibraryItem item;

  const _BannerOptionTile({required this.item});

  @override
  State<_BannerOptionTile> createState() => _BannerOptionTileState();
}

class _BannerOptionTileState extends State<_BannerOptionTile> {
  late final Future<Map<String, dynamic>> _detailsFuture;

  @override
  void initState() {
    super.initState();

    _detailsFuture = TmdbService().getDetails(
      widget.item.id,
      widget.item.mediaType,
    );
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<Map<String, dynamic>>(
      future: _detailsFuture,
      builder: (context, snapshot) {
        if (!snapshot.hasData) {
          return Container(
            decoration: BoxDecoration(
              color: chipluxSurfaceLight,
              borderRadius: BorderRadius.circular(14),
            ),
            child: const Center(
              child: SizedBox(
                width: 22,
                height: 22,
                child: CircularProgressIndicator(strokeWidth: 2),
              ),
            ),
          );
        }

        final details = snapshot.data!;

        final path = details['backdrop_path']?.toString();

        final hasBackdrop = path != null && path.isNotEmpty;

        final url = hasBackdrop ? 'https://image.tmdb.org/t/p/w780$path' : null;

        return InkWell(
          borderRadius: BorderRadius.circular(14),
          onTap: !hasBackdrop
              ? null
              : () async {
                  await ProfileService.instance.updateBanner(
                    tmdbId: widget.item.id,
                    mediaType: widget.item.mediaType,
                    bannerPath: path,
                  );

                  if (context.mounted) {
                    Navigator.pop(context);
                  }
                },
          child: ClipRRect(
            borderRadius: BorderRadius.circular(14),
            child: Stack(
              fit: StackFit.expand,
              children: [
                if (url != null)
                  Image.network(
                    url,
                    fit: BoxFit.cover,

                    errorBuilder: (context, error, stackTrace) {
                      return Container(
                        color: chipluxSurfaceLight,
                        alignment: Alignment.center,
                        child: const Icon(
                          Icons.panorama_outlined,
                          color: Colors.white38,
                        ),
                      );
                    },
                  )
                else
                  Container(
                    color: chipluxSurfaceLight,
                    alignment: Alignment.center,
                    child: const Text(
                      'No backdrop',
                      style: TextStyle(color: Colors.white38, fontSize: 12),
                    ),
                  ),

                DecoratedBox(
                  decoration: BoxDecoration(
                    gradient: LinearGradient(
                      begin: Alignment.topCenter,
                      end: Alignment.bottomCenter,
                      colors: [
                        Colors.transparent,
                        Colors.black.withValues(alpha: 0.82),
                      ],
                    ),
                  ),
                ),

                Positioned(
                  left: 9,
                  right: 9,
                  bottom: 8,
                  child: Row(
                    children: [
                      Expanded(
                        child: Text(
                          widget.item.title,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                            fontSize: 12,
                            fontWeight: FontWeight.bold,
                          ),
                        ),
                      ),

                      const SizedBox(width: 5),

                      Text(
                        widget.item.mediaType == 'tv' ? 'TV' : 'MOVIE',
                        style: const TextStyle(
                          color: chipluxCyan,
                          fontSize: 9,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }
}

