              final tvGroups = <_AchievementGroup>[
                tvGroup,
                episodeGroup,
                tvShowsRatedGroup,
                episodeRatedGroup,
              ];

              final communityGroups = <_AchievementGroup>[
                profileViewGroup,
                followerGroup,
              ];

              final followDeveloperGroup =
    _followDeveloperAchievementGroupFor(
  ProfileService
      .instance
      .followedDeveloperAchievement,
);

final chipluxGroups =
    <_AchievementGroup>[
  if (!ProfileService
      .instance
      .isDeveloper)
    followDeveloperGroup,

  dailyLoginGroup,
  runtimeLevelGroup,
  ratingsLevelGroup,
];

              // =========================
              // ALL NORMAL ACHIEVEMENTS
              // =========================

              final allGroups = <_AchievementGroup>[
                ...movieGroups,
                ...tvGroups,
                ...communityGroups,
                ...chipluxGroups,
              ];

              final allTiers = allGroups
                  .expand((group) => group.tiers)
