class ProfilePageFrameService
    extends ChangeNotifier {
  ProfilePageFrameService._();

  static final ProfilePageFrameService
      instance =
      ProfilePageFrameService._();

  String? _frameId;

  String? get frameId =>
      _frameId;

  Future<void> load() async {
    final client =
        Supabase.instance.client;

    final user =
        client.auth.currentUser;

    if (user == null) {
      _frameId = null;

      notifyListeners();

      return;
    }

    try {
      final row = await client
          .from('profiles')
          .select(
            'profile_page_frame_id',
          )
          .eq(
            'id',
            user.id,
          )
          .maybeSingle();

      final rawId =
          row?['profile_page_frame_id']
              ?.toString()
              .trim();

      _frameId =
          rawId != null &&
                  rawId.isNotEmpty
              ? rawId
              : null;

      notifyListeners();
    } catch (e) {
      debugPrint(
        'Could not load profile page frame: $e',
      );
    }
  }

  Future<void> apply(
    String? frameId,
  ) async {
    final client =
        Supabase.instance.client;

    final user =
        client.auth.currentUser;

    if (user == null) {
      throw Exception(
        'No signed in user.',
      );
    }

    final cleanId =
        frameId?.trim();

    final value =
        cleanId == null ||
                cleanId.isEmpty
            ? null
            : cleanId;

    if (value != null &&
    value !=
        developerProfilePageFrameId &&
    value !=
        followDeveloperProfilePageFrameId) {
  throw Exception(
    'Unknown profile page frame.',
  );
}

if (value ==
        developerProfilePageFrameId &&
    !ProfileService
        .instance
        .isDeveloper) {
  throw Exception(
    'Developer frame is not available.',
  );
}

if (value ==
        followDeveloperProfilePageFrameId &&
    !ProfileService
        .instance
        .isDeveloper &&
    !ProfileService
        .instance
        .followedDeveloperAchievement) {
  throw Exception(
    'Follow Developer frame is still locked.',
  );
}

    await client
        .from('profiles')
        .update({
          'profile_page_frame_id':
              value,
        })
        .eq(
          'id',
          user.id,
        );

    _frameId = value;

    notifyListeners();
  }

  void clear() {
    _frameId = null;

    notifyListeners();
  }
}

class ProfileTitleService extends ChangeNotifier {
  ProfileTitleService._();

  static final ProfileTitleService instance = ProfileTitleService._();

  String? _achievementId;

  String? get achievementId => _achievementId;

  Future<void> load() async {
    final client = Supabase.instance.client;

    final user = client.auth.currentUser;

    if (user == null) {
      _achievementId = null;

      notifyListeners();

      return;
    }

    try {
      final row = await client
          .from('profiles')
          .select('profile_title_id')
          .eq('id', user.id)
          .maybeSingle();

      final rawId = row?['profile_title_id']?.toString().trim();

      _achievementId = rawId != null && rawId.isNotEmpty ? rawId : null;

      notifyListeners();
    } catch (e) {
      debugPrint('Could not load profile title: $e');
    }
  }

  Future<void> apply(String? achievementId) async {
    final client = Supabase.instance.client;

    final user = client.auth.currentUser;

    if (user == null) {
      throw Exception('No signed in user.');
    }

    final cleanId = achievementId?.trim();

    final value = cleanId == null || cleanId.isEmpty ? null : cleanId;

    await client
        .from('profiles')
        .update({'profile_title_id': value})
        .eq('id', user.id);

    _achievementId = value;

    notifyListeners();
  }
}

