class _Tier3ProfilePageFramePainter
    extends CustomPainter {
  const _Tier3ProfilePageFramePainter();

  @override
  void paint(
    Canvas canvas,
    Size size,
  ) {
    if (size.width <= 0 ||
        size.height <= 0) {
      return;
    }

    final rect =
        Rect.fromLTWH(
      5,
      5,
      size.width - 10,
      size.height - 10,
    );

    final rrect =
        RRect.fromRectAndRadius(
      rect,
      const Radius.circular(
        24,
      ),
    );

    final shader =
        const LinearGradient(
      begin:
          Alignment.topLeft,

      end:
          Alignment.bottomRight,

      colors: [
        Color(0xFFA855F7),
        Color(0xFFD946EF),
        Color(0xFF6366F1),
        Color(0xFFA855F7),
      ],
    ).createShader(
      rect,
    );

    final glow =
        Paint()
          ..style =
              PaintingStyle.stroke
          ..strokeWidth = 5
          ..shader = shader
          ..maskFilter =
              const MaskFilter.blur(
            BlurStyle.normal,
            5,
          );

    canvas.drawRRect(
      rrect,
      glow,
    );

    final frame =
        Paint()
          ..style =
              PaintingStyle.stroke
          ..strokeWidth = 2.1
          ..shader = shader;

    canvas.drawRRect(
      rrect,
      frame,
    );

    final innerRect =
        Rect.fromLTWH(
      8,
      8,
      size.width - 16,
      size.height - 16,
    );

    canvas.drawRRect(
      RRect.fromRectAndRadius(
        innerRect,
        const Radius.circular(
          21,
        ),
      ),
      Paint()
        ..style =
            PaintingStyle.stroke
        ..strokeWidth = 0.7
        ..color =
            Colors.white
                .withValues(
          alpha: 0.12,
        ),
    );
  }

  @override
  bool shouldRepaint(
    covariant
        _Tier3ProfilePageFramePainter
        oldDelegate,
  ) {
    return false;
  }
}

