class _DeveloperProfileFramePainter
    extends CustomPainter {
  final Animation<double> animation;

  _DeveloperProfileFramePainter({
    required this.animation,
  }) : super(
          repaint: animation,
        );

  @override
  void paint(
    Canvas canvas,
    Size size,
  ) {
    if (size.width <= 0 ||
        size.height <= 0) {
      return;
    }

    final rect =
        Rect.fromLTWH(
      5,
      5,
      size.width - 10,
      size.height - 10,
    );

    final roundedRect =
        RRect.fromRectAndRadius(
      rect,
      const Radius.circular(
        24,
      ),
    );

    final rotation =
        animation.value *
            6.28318530718;

    final shader =
        SweepGradient(
      colors: const [
        Color(0xFF00E5FF),
        Color(0xFF875CFF),
        Color(0xFFFF4FD8),
        Color(0xFFFFD166),
        Color(0xFF00E5FF),
      ],
      transform:
          GradientRotation(
        rotation,
      ),
    ).createShader(
      rect,
    );

    // =========================
    // SOFT OUTER GLOW
    // =========================

    final glowPaint =
        Paint()
          ..style =
              PaintingStyle.stroke
          ..strokeWidth = 6
          ..shader = shader
          ..maskFilter =
              const MaskFilter.blur(
            BlurStyle.normal,
            6,
          );

    canvas.drawRRect(
      roundedRect,
      glowPaint,
    );

    // =========================
    // MAIN DEVELOPER FRAME
    // =========================

    final framePaint =
        Paint()
          ..style =
              PaintingStyle.stroke
          ..strokeWidth = 2.2
          ..shader = shader;

    canvas.drawRRect(
      roundedRect,
      framePaint,
    );

    // =========================
    // SUBTLE INNER LINE
    // =========================

    final innerRect =
        Rect.fromLTWH(
      8,
      8,
      size.width - 16,
      size.height - 16,
    );

    final innerRoundedRect =
        RRect.fromRectAndRadius(
      innerRect,
      const Radius.circular(
        21,
      ),
    );

    final innerPaint =
        Paint()
          ..style =
              PaintingStyle.stroke
          ..strokeWidth = 0.7
          ..color =
              Colors.white.withValues(
            alpha: 0.16,
          );

    canvas.drawRRect(
      innerRoundedRect,
      innerPaint,
    );
  }

  @override
  bool shouldRepaint(
    covariant
        _DeveloperProfileFramePainter
        oldDelegate,
  ) {
    return false;
  }
}

class _DeveloperTitleLabel
    extends StatefulWidget {
  const _DeveloperTitleLabel();

  @override
  State<_DeveloperTitleLabel>
      createState() =>
          _DeveloperTitleLabelState();
}

class _DeveloperTitleLabelState
    extends State<_DeveloperTitleLabel>
    with SingleTickerProviderStateMixin {
  late final AnimationController
      _controller;

  @override
  void initState() {
    super.initState();

    _controller =
        AnimationController(
      vsync: this,
      duration:
          const Duration(
        seconds: 4,
      ),
    )..repeat();
  }

  @override
  void dispose() {
    _controller.dispose();

    super.dispose();
  }

  @override
  Widget build(
    BuildContext context,
  ) {
    return AnimatedBuilder(
      animation: _controller,

      builder: (
        context,
        child,
      ) {
        final t =
            _controller.value;

        final pulseValue =
            t <= 0.5
                ? t * 2
                : (1 - t) * 2;

        final pulse =
            Curves.easeInOut
                .transform(
          pulseValue,
        );

        final glowColor =
            Color.lerp(
              const Color(
                0xFF00E5FF,
              ),
              const Color(
                0xFFFFD166,
              ),
              pulse,
            ) ??
            chipluxCyan;

        return Container(
          constraints:
              const BoxConstraints(
            maxWidth: 220,
          ),

          padding:
              const EdgeInsets.all(
            1.4,
          ),

          decoration:
              BoxDecoration(
            borderRadius:
                BorderRadius.circular(
              20,
            ),

            gradient:
                LinearGradient(
              colors: const [
                Color(
                  0xFF00E5FF,
                ),
                Color(
                  0xFF875CFF,
                ),
                Color(
                  0xFFFF4FD8,
                ),
                Color(
                  0xFFFFD166,
                ),
                Color(
                  0xFF00E5FF,
                ),
              ],

              transform:
                  GradientRotation(
                t * 6.28318,
              ),
            ),

            boxShadow: [
              BoxShadow(
                color:
                    glowColor
                        .withValues(
                  alpha:
                      0.18 +
                      (0.12 *
                          pulse),
                ),

                blurRadius:
                    10 +
                    (8 * pulse),

                spreadRadius:
                    0.2 +
                    (0.5 *
                        pulse),
              ),
            ],
          ),

          child: Container(
            padding:
                const EdgeInsets
                    .symmetric(
              horizontal: 14,
              vertical: 5,
            ),

            decoration:
                BoxDecoration(
              color:
                  chipluxBackground
                      .withValues(
                alpha: 0.90,
              ),

              borderRadius:
                  BorderRadius
                      .circular(
                18.5,
              ),

              border:
                  Border.all(
                color:
                    Colors.white
                        .withValues(
                  alpha: 0.06,
                ),
              ),
            ),

            child: ShaderMask(
              blendMode:
                  BlendMode.srcIn,

              shaderCallback:
                  (bounds) {
                return LinearGradient(
                  begin:
                      Alignment(
                    -1.5 +
                        (t * 2),
                    0,
                  ),

                  end:
                      Alignment(
                    0.5 +
                        (t * 2),
                    0,
                  ),

                  colors:
                      const [
                    Color(
                      0xFF00E5FF,
                    ),
                    Color(
                      0xFFB388FF,
                    ),
                    Color(
                      0xFFFFD166,
                    ),
                    Color(
                      0xFFFF4FD8,
                    ),
                    Color(
                      0xFF00E5FF,
                    ),
                  ],
                ).createShader(
                  bounds,
                );
              },

              child:
                  const Row(
                mainAxisSize:
                    MainAxisSize
                        .min,

                mainAxisAlignment:
                    MainAxisAlignment
                        .center,

                children: [
                  Icon(
                    Icons
                        .code_rounded,

                    color:
                        Colors.white,

                    size: 14,
                  ),

                  SizedBox(
                    width: 6,
                  ),

                  Text(
                    'DEVELOPER',

                    style:
                        TextStyle(
                      color:
                          Colors.white,

                      fontSize:
                          10.5,

                      fontWeight:
                          FontWeight
                              .w900,

                      letterSpacing:
                          1.4,
                    ),
                  ),

                  SizedBox(
                    width: 5,
                  ),

                  Icon(
                    Icons
                        .auto_awesome_rounded,

                    color:
                        Colors.white,

                    size: 10,
                  ),
                ],
              ),
            ),
          ),
        );
      },
    );
  }
}


