class MedalPinService extends ChangeNotifier {
  MedalPinService._();

  static final MedalPinService instance = MedalPinService._();

  String? _pinnedAchievementId;

  String? get pinnedAchievementId => _pinnedAchievementId;

  bool isPinned(String id) {
    return _pinnedAchievementId == id;
  }

  Future<void> init() async {
    final client = Supabase.instance.client;

    final user = client.auth.currentUser;

    _pinnedAchievementId = null;

    if (user == null) {
      notifyListeners();

      return;
    }

    try {
      final row = await client
          .from('profiles')
          .select('pinned_achievement_id')
          .eq('id', user.id)
          .maybeSingle();

      final raw = row?['pinned_achievement_id'];

      final value = raw?.toString().trim();

      _pinnedAchievementId = value != null && value.isNotEmpty ? value : null;
    } catch (e) {
      _pinnedAchievementId = null;

      debugPrint('Could not load pinned achievement: $e');
    }

    notifyListeners();
  }

  Future<void> pin(String id) async {
    final client = Supabase.instance.client;

    final user = client.auth.currentUser;

    if (user == null) {
      return;
    }

    try {
      await client
          .from('profiles')
          .update({'pinned_achievement_id': id})
          .eq('id', user.id);

      _pinnedAchievementId = id;

      notifyListeners();
    } catch (e) {
      debugPrint('Could not pin achievement: $e');
    }
  }

  Future<void> unpin() async {
    final client = Supabase.instance.client;

    final user = client.auth.currentUser;

    if (user == null) {
      return;
    }

    try {
      await client
          .from('profiles')
          .update({'pinned_achievement_id': null})
          .eq('id', user.id);

      _pinnedAchievementId = null;

      notifyListeners();
    } catch (e) {
      debugPrint('Could not unpin achievement: $e');
    }
  }

  void clear() {
    _pinnedAchievementId = null;

    notifyListeners();
  }
}

class ProfilePage extends StatefulWidget {
  final VoidCallback? onFollowersTap;

  final VoidCallback? onTvShowsWatchedTap;

  final VoidCallback? onEpisodesWatchedTap;

  final VoidCallback? onMoviesWatchedTap;

  final VoidCallback? onEpisodesRatedTap;

  final VoidCallback? onTvShowsRatedTap;

  final VoidCallback? onMoviesRatedTap;

  const ProfilePage({
    super.key,
    this.onTvShowsWatchedTap,
    this.onEpisodesWatchedTap,
    this.onMoviesWatchedTap,
    this.onEpisodesRatedTap,
    this.onTvShowsRatedTap,
    this.onMoviesRatedTap,
    this.onFollowersTap,
  });

  @override
  State<ProfilePage> createState() => _ProfilePageState();
}

class _ProfilePageState extends State<ProfilePage> {
  final library = LibraryService.instance;

  final profile = ProfileService.instance;

  final critic = CriticService.instance;

  int? _lastFollowerCount;

  final GlobalKey _genreRuntimeKey = GlobalKey();

  final GlobalKey _ratingDistributionKey = GlobalKey();

  bool _genreRuntimeExpanded = false;

  @override
  void initState() {
    super.initState();

    _refreshProfileInBackground();

    final followerService = FollowerCountService.instance;

    _lastFollowerCount = followerService.loaded
        ? followerService.peakFollowerCount
        : null;

    followerService.addListener(_handleFollowerCountChange);

    unawaited(followerService.load());

    unawaited(critic.refresh());
  }

  // =====================================================
  // SCROLLING
  // =====================================================

  void _handleFollowerCountChange() {
    final current = FollowerCountService.instance.peakFollowerCount;

    final previous = _lastFollowerCount;

    _lastFollowerCount = current;

    if (previous == null || current <= previous || !mounted) {
      return;
    }

    unawaited(
      _checkFollowerAchievementUnlock(
        context,
        previousCount: previous,
        currentCount: current,
      ),
    );
  }

  @override
  void dispose() {
    FollowerCountService.instance.removeListener(_handleFollowerCountChange);

    super.dispose();
  }

  void _scrollToProfileSection(GlobalKey key) {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      final targetContext = key.currentContext;

      if (targetContext == null) {
        return;
      }

      Scrollable.ensureVisible(
        targetContext,
        duration: const Duration(milliseconds: 450),
        curve: Curves.easeInOutCubic,
        alignment: 0.08,
      );
    });
  }

  // =====================================================
  // BACKGROUND REFRESH
  // =====================================================

  void _refreshProfileInBackground() {
    unawaited(profile.loadProfile());

    unawaited(DisplayNameFrameService.instance.load());

    unawaited(AvatarFrameService.instance.load());

    unawaited(_AchievementCosmeticService.instance.load());

    unawaited(_backfillStatsInBackground());

    unawaited(
  ProfilePageFrameService.instance.load(),
);
  }

  Future<void> _backfillStatsInBackground() async {
    try {
      await library.backfillMissingRuntimes();

      if (!mounted) {
        return;
      }

      setState(() {});
    } catch (e) {
      debugPrint('Could not refresh profile stats: $e');
    }
  }

  Future<void> _refreshProfile() async {
    await Future.wait([
      profile.loadProfile(),

      DisplayNameFrameService.instance.load(),

      AvatarFrameService.instance.load(),

      _AchievementCosmeticService.instance.load(),

      ProfilePageFrameService.instance.load(),

      library.backfillMissingRuntimes(),

      critic.refresh(),
    ]);

    if (!mounted) {
      return;
    }

    setState(() {});
  }

  // =====================================================
  // GENRE HELPERS
  // =====================================================

  List<int> _genresForItem(LibraryItem item) {
    return item.genreIds.toSet().toList();
  }

  String _genreName(int genreId) {
    switch (genreId) {
      case 28:
        return 'Action';

      case 12:
        return 'Adventure';

      case 16:
        return 'Animation';

      case 35:
        return 'Comedy';

      case 80:
        return 'Crime';

      case 99:
        return 'Documentary';

      case 18:
        return 'Drama';

      case 10751:
        return 'Family';

      case 14:
        return 'Fantasy';

      case 36:
        return 'History';

      case 27:
        return 'Horror';

      case 10402:
        return 'Music';

      case 9648:
        return 'Mystery';

      case 10749:
        return 'Romance';

      case 878:
        return 'Science Fiction';

      case 10770:
        return 'TV Movie';

      case 53:
        return 'Thriller';

      case 10752:
        return 'War';

      case 37:
        return 'Western';

      // TV genres
      case 10759:
        return 'Action & Adventure';

      case 10762:
        return 'Kids';

      case 10763:
        return 'News';

      case 10764:
        return 'Reality';

      case 10765:
        return 'Sci-Fi & Fantasy';

      case 10766:
        return 'Soap';

      case 10767:
        return 'Talk';

      case 10768:
        return 'War & Politics';

      default:
        return 'Other';
    }
  }

  List<_GenreRuntimeStat> _buildGenreRuntimeStats() {
    final items = library.items.toList();

    if (items.isEmpty) {
      return [];
    }

    final titleCounts = <int, int>{};

    final watchedMinutes = <int, int>{};

    for (final item in items) {
      final genres = _genresForItem(item);

      if (genres.isEmpty) {
        continue;
      }

      final itemWatchedMinutes = library.watchedMinutesForItem(item);

      for (final genreId in genres.toSet()) {
        titleCounts[genreId] = (titleCounts[genreId] ?? 0) + 1;

        watchedMinutes[genreId] =
            (watchedMinutes[genreId] ?? 0) + itemWatchedMinutes;
      }
    }

    final int totalGenreRuntime = watchedMinutes.values.fold(
      0,
      (sum, minutes) => sum + minutes,
    );

    final result = <_GenreRuntimeStat>[];

    for (final entry in titleCounts.entries) {
      final genreId = entry.key;

      final count = entry.value;

      final minutes = watchedMinutes[genreId] ?? 0;

      final percentage = totalGenreRuntime > 0
          ? (minutes / totalGenreRuntime) * 100
          : 0.0;

      result.add(
        _GenreRuntimeStat(
          genre: _genreName(genreId),
          titleCount: count,
          watchedMinutes: minutes,
          percentage: percentage,
        ),
      );
    }

    result.sort((a, b) {
      final runtimeComparison = b.watchedMinutes.compareTo(a.watchedMinutes);

      if (runtimeComparison != 0) {
        return runtimeComparison;
      }

      return b.titleCount.compareTo(a.titleCount);
    });

    return result;
  }

  // =====================================================
  // GENRE RUNTIME PANEL
  // =====================================================

  Widget _buildGenreRuntimeSection() {
    final stats = _buildGenreRuntimeStats();

    if (stats.isEmpty) {
      return const SizedBox.shrink();
    }

    final visibleStats = _genreRuntimeExpanded ? stats : stats.take(4).toList();

    final canExpand = stats.length > 4;

    const genreColors = <Color>[
      chipluxCyan,
      Color(0xFF55C7FF),
      chipluxViolet,
      chipluxPurple,
      Color(0xFF6F7CFF),
      Color(0xFF43B8FF),
      Color(0xFFB56DFF),
      Color(0xFF5363B8),
    ];

    Color genreColor(int index) {
      return genreColors[index % genreColors.length];
    }

    String formatRuntime(int totalMinutes) {
      final hours = totalMinutes ~/ 60;

      final minutes = totalMinutes % 60;

      if (hours > 0 && minutes > 0) {
        return '${hours}h ${minutes}m';
      }

      if (hours > 0) {
        return '${hours}h';
      }

      return '${minutes}m';
    }

    final totalGenreWeight = stats.fold<double>(
      0,
      (sum, stat) => sum + stat.percentage,
    );

    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        color: chipluxSurface,
        borderRadius: BorderRadius.circular(22),
        border: Border.all(color: chipluxCyan.withValues(alpha: 0.14)),
        boxShadow: [
          BoxShadow(
            color: chipluxViolet.withValues(alpha: 0.07),
            blurRadius: 18,
            spreadRadius: 1,
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Row(
            children: [
              Icon(Icons.bar_chart_rounded, color: chipluxCyan, size: 27),

              SizedBox(width: 10),

              Text(
                'Genre Runtime',
                style: TextStyle(fontSize: 24, fontWeight: FontWeight.bold),
              ),
            ],
          ),

          const SizedBox(height: 24),

          // LARGE SEGMENTED BAR
          ClipRRect(
            borderRadius: BorderRadius.circular(30),
            child: SizedBox(
              height: 22,
              child: Row(
                children: stats.asMap().entries.map((entry) {
                  final index = entry.key;

                  final stat = entry.value;

                  final normalized = totalGenreWeight > 0
                      ? stat.percentage / totalGenreWeight
                      : 0.0;

                  int flex = (normalized * 10000).round();

                  if (flex < 1) {
                    flex = 1;
                  }

                  return Expanded(
                    flex: flex,
                    child: Container(color: genreColor(index)),
                  );
                }).toList(),
              ),
            ),
          ),

          const SizedBox(height: 20),

          ...visibleStats.asMap().entries.map((entry) {
            final index = entry.key;

            final stat = entry.value;

            final color = genreColor(index);

            final isLast = index == visibleStats.length - 1;

            return Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 12),
                  child: Row(
                    children: [
                      Container(
                        width: 15,
                        height: 15,
                        decoration: BoxDecoration(
                          color: color,
                          shape: BoxShape.circle,
                          boxShadow: [
                            BoxShadow(
                              color: color.withValues(alpha: 0.30),
                              blurRadius: 8,
                            ),
                          ],
                        ),
                      ),

                      const SizedBox(width: 11),

                      Expanded(
                        child: Text(
                          stat.genre,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                            fontSize: 16,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                      ),

                      const SizedBox(width: 8),

                      SizedBox(
                        width: 72,
                        height: 22,
                        child: FittedBox(
                          fit: BoxFit.scaleDown,
                          alignment: Alignment.centerRight,
                          child: Text(
                            '${stat.percentage.toStringAsFixed(1)}%',
                            maxLines: 1,
                            style: const TextStyle(
                              fontSize: 15,
                              fontWeight: FontWeight.bold,
                              color: Colors.white,
                            ),
                          ),
                        ),
                      ),

                      const SizedBox(width: 12),

                      SizedBox(
                        width: 78,
                        child: Text(
                          formatRuntime(stat.watchedMinutes),
                          textAlign: TextAlign.right,
                          style: const TextStyle(
                            fontSize: 14,
                            fontWeight: FontWeight.w500,
                            color: Colors.white70,
                          ),
                        ),
                      ),
                    ],
                  ),
                ),

                if (!isLast)
                  Divider(
                    height: 1,
                    thickness: 1,
                    color: Colors.white.withValues(alpha: 0.08),
                  ),
              ],
            );
          }),

          if (canExpand) ...[
            const SizedBox(height: 10),

            InkWell(
              borderRadius: BorderRadius.circular(14),
              onTap: () {
                setState(() {
                  _genreRuntimeExpanded = !_genreRuntimeExpanded;
