class _FollowerCountBadge extends StatefulWidget {
  final String userId;

  final String? selectedTierId;

  final int? achievementCount;

  final ValueChanged<int>? onCountChanged;

  final VoidCallback? onTap;

  const _FollowerCountBadge({
    required this.userId,
    this.selectedTierId,
    this.achievementCount,
    this.onCountChanged,
    this.onTap,
  });

  @override
  State<_FollowerCountBadge> createState() => _FollowerCountBadgeState();
}

class _FollowerCountBadgeState extends State<_FollowerCountBadge> {
  int followerCount = 0;

  bool loading = true;

  RealtimeChannel? _channel;

  @override
  void initState() {
    super.initState();

    _loadFollowerCount();

    _startRealtime();
  }

  @override
  void didUpdateWidget(covariant _FollowerCountBadge oldWidget) {
    super.didUpdateWidget(oldWidget);

    if (oldWidget.userId != widget.userId) {
      if (_channel != null) {
        unawaited(_channel!.unsubscribe());
      }

      _channel = null;

      followerCount = 0;

      loading = true;

      _loadFollowerCount();

      _startRealtime();
    }
  }

  Future<void> _loadFollowerCount() async {
    try {
      final rows = await Supabase.instance.client
          .from('follows')
          .select('follower_id')
          .eq('following_id', widget.userId);

      if (!mounted) {
        return;
      }

      final int newCount = rows.length;

      final bool changed = newCount != followerCount;

      setState(() {
        followerCount = newCount;

        loading = false;
      });

      if (changed) {
        widget.onCountChanged?.call(newCount);
      }
    } catch (e) {
      debugPrint('Could not load follower count: $e');

      if (!mounted) {
        return;
      }

      setState(() {
        loading = false;
      });
    }
  }

  void _startRealtime() {
    final client = Supabase.instance.client;

    _channel = client.channel('followers_${widget.userId}_$hashCode');

    _channel!
        .onPostgresChanges(
          event: PostgresChangeEvent.all,

          schema: 'public',

          table: 'follows',

          callback: (payload) {
            if (!mounted) {
              return;
            }

            unawaited(_loadFollowerCount());
          },
        )
        .subscribe();
  }

  @override
  void dispose() {
    if (_channel != null) {
      unawaited(_channel!.unsubscribe());
    }

    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final group = _followersAchievementGroupFor(
      widget.achievementCount ?? followerCount,
    );

    _Achievement? styleAchievement;

    final selectedId = widget.selectedTierId;

    if (selectedId != null) {
      for (final tier in group.tiers) {
        if (tier.id == selectedId && tier.unlocked) {
          styleAchievement = tier;

          break;
        }
      }
    }

    styleAchievement ??= group.highestUnlockedTier;

    final colors = _achievementTierColors(styleAchievement);

    final Color accent =
    colors.isNotEmpty
        ? colors.first
        : Colors.white54;

    final bool hasReward = styleAchievement != null && colors.isNotEmpty;

    return GestureDetector(
      onTap: widget.onTap,

      behavior: HitTestBehavior.opaque,

      child: Container(
        height: 43,

        padding: hasReward ? const EdgeInsets.all(1.3) : EdgeInsets.zero,

        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(16),

          gradient: hasReward
              ? LinearGradient(
                  begin: Alignment.topLeft,

                  end: Alignment.bottomRight,

                  colors: colors,
                )
              : null,

          border: hasReward
    ? null
    : Border.all(
        color: Colors.white
            .withValues(
          alpha: 0.18,
        ),
        width: 1,
      ),

          boxShadow: hasReward
              ? [
                  BoxShadow(
                    color: accent.withValues(alpha: 0.09),

                    blurRadius: 10,
                  ),
                ]
              : const [],
        ),

        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 11),

          decoration: BoxDecoration(
            color: chipluxSurface.withValues(alpha: 0.92),

            borderRadius: BorderRadius.circular(hasReward ? 14.7 : 16),
          ),

          child: Row(
            mainAxisSize: MainAxisSize.min,

            children: [
              Icon(Icons.people_alt_rounded, color: accent, size: 22),

              const SizedBox(width: 6),

              if (loading)
                SizedBox(
                  width: 13,

                  height: 13,

                  child: CircularProgressIndicator(
                    strokeWidth: 1.5,

                    color: accent,
                  ),
                )
              else
                Text(
                  '$followerCount',

                  style: const TextStyle(
                    color: Colors.white,

                    fontSize: 14,

                    fontWeight: FontWeight.bold,
                  ),
                ),
            ],
          ),
        ),
      ),
    );
  }
}

