class _LevelCardState extends State<_LevelCard> with TickerProviderStateMixin {
  late final AnimationController _controller;

  late final AnimationController _flowController;

  late Animation<double> _progressAnimation;

  int level = 1;

  int minutesInLevel = 0;

  int requiredMinutes = 20;

  int minutesLeft = 20;

  double targetProgress = 0;

  @override
  void initState() {
    super.initState();

    _calculateLevel();

    _controller = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 900),
    );

    _progressAnimation = Tween<double>(
      begin: 0,
      end: targetProgress,
    ).animate(CurvedAnimation(parent: _controller, curve: Curves.easeOutCubic));

    _controller.forward();

    _flowController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 2200),
    )..repeat();
  }

  @override
  void didUpdateWidget(covariant _LevelCard oldWidget) {
    super.didUpdateWidget(oldWidget);

    if (oldWidget.totalMinutes != widget.totalMinutes) {
      final oldProgress = targetProgress;

      _calculateLevel();

      _progressAnimation =
          Tween<double>(begin: oldProgress, end: targetProgress).animate(
            CurvedAnimation(parent: _controller, curve: Curves.easeOutCubic),
          );

      _controller
        ..reset()
        ..forward();
    }
  }

  void _calculateLevel() {
    level = 1;

    minutesInLevel = widget.totalMinutes;

    while (minutesInLevel >= level * 20) {
      minutesInLevel -= level * 20;

      level++;
    }

    requiredMinutes = level * 20;

    minutesLeft = requiredMinutes - minutesInLevel;

    targetProgress = requiredMinutes == 0
        ? 0
        : minutesInLevel / requiredMinutes;
  }

  String _formatTimeLeft(int totalMinutes) {
    if (totalMinutes < 60) {
      return '$totalMinutes '
          'minute${totalMinutes == 1 ? '' : 's'}';
    }

    final totalHours = totalMinutes ~/ 60;

    final remainingMinutes = totalMinutes % 60;

    if (totalHours < 24) {
      if (remainingMinutes == 0) {
        return '${totalHours}h';
      }

      return '${totalHours}h '
          '${remainingMinutes}m';
    }

    final totalDays = totalHours ~/ 24;

    final remainingHours = totalHours % 24;

    if (totalDays < 30) {
      if (remainingHours == 0) {
        return '${totalDays}d';
      }

      return '${totalDays}d '
          '${remainingHours}h';
    }

    final totalMonths = totalDays ~/ 30;

    final remainingDays = totalDays % 30;

    if (totalMonths < 12) {
      if (remainingDays == 0) {
        return '$totalMonths '
            'month${totalMonths == 1 ? '' : 's'}';
      }

      return '$totalMonths '
          'month${totalMonths == 1 ? '' : 's'} '
          '${remainingDays}d';
    }

    final years = totalMonths ~/ 12;

    final remainingMonths = totalMonths % 12;

    if (remainingMonths == 0) {
      return '$years '
          'year${years == 1 ? '' : 's'}';
    }

    return '$years '
        'year${years == 1 ? '' : 's'} '
        '$remainingMonths '
        'month${remainingMonths == 1 ? '' : 's'}';
  }

  @override
  Widget build(BuildContext context) {
    final achievementColors = _achievementTierColors(widget.frameAchievement);

    final List<Color> activeColors = achievementColors.isNotEmpty
        ? achievementColors
        : const [Color(0xFFD7DEE7), Color(0xFF8F9BAA)];

    final Color glowColor = activeColors.first;

    final Color titleColor = widget.frameAchievement?.visualTier == 4
        ? const Color(0xFFFFC857)
        : activeColors.first;

    return GestureDetector(
      behavior: HitTestBehavior.opaque,

      onTap: widget.onTap,

      child: Container(
        padding: const EdgeInsets.all(1.2),

        decoration: BoxDecoration(
          gradient: LinearGradient(
            begin: Alignment.topLeft,

            end: Alignment.bottomRight,

            colors: activeColors,
          ),

          borderRadius: BorderRadius.circular(20),

          boxShadow: [
            BoxShadow(color: glowColor.withValues(alpha: 0.10), blurRadius: 15),
          ],
        ),

        child: Container(
          width: double.infinity,

          padding: const EdgeInsets.fromLTRB(14, 14, 14, 14),

          decoration: BoxDecoration(
            color: chipluxSurface,

            borderRadius: BorderRadius.circular(19),

            border: Border.all(
              color: Colors.white.withValues(alpha: 0.045),

              width: 0.7,
            ),
          ),

          child: Row(
            crossAxisAlignment: CrossAxisAlignment.center,

            children: [
              _LevelHexBadge(level: level, colors: activeColors),

              const SizedBox(width: 11),

              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,

                  children: [
                    const Text(
                      'RUNTIME LEVEL',

                      style: TextStyle(
                        color: Colors.white38,

                        fontSize: 9,

                        fontWeight: FontWeight.w700,

                        letterSpacing: 1.2,
                      ),
                    ),

                    const SizedBox(height: 1),

                    Text(
                      widget.title.toUpperCase(),

                      maxLines: 1,

                      overflow: TextOverflow.ellipsis,

                      style: TextStyle(
                        color: titleColor,

                        fontSize: 16,

                        fontWeight: FontWeight.w900,

                        letterSpacing: 0.6,

                        shadows: [
                          Shadow(
                            color: titleColor.withValues(alpha: 0.34),

                            blurRadius: 7,
                          ),
                        ],
                      ),
                    ),

                    const SizedBox(height: 7),

                    // =============================
                    // GLOSSY PROGRESS
                    // =============================
                    Container(
                      height: 8,

                      decoration: BoxDecoration(
                        color: Colors.black.withValues(alpha: 0.22),

                        borderRadius: BorderRadius.circular(20),

                        border: Border.all(
                          color: Colors.white.withValues(alpha: 0.055),

                          width: 0.7,
                        ),

                        boxShadow: [
                          BoxShadow(
                            color: glowColor.withValues(alpha: 0.18),

                            blurRadius: 8,
                          ),
                        ],
                      ),

                      clipBehavior: Clip.antiAlias,

                      child: AnimatedBuilder(
                        animation: Listenable.merge([
                          _progressAnimation,
                          _flowController,
                        ]),

                        builder: (context, _) {
                          final flow = _flowController.value;

                          return Align(
                            alignment: Alignment.centerLeft,

                            child: FractionallySizedBox(
                              widthFactor: _progressAnimation.value.clamp(
                                0.0,
                                1.0,
                              ),

                              heightFactor: 1,

                              child: Stack(
                                fit: StackFit.expand,

                                children: [
                                  Container(
                                    decoration: BoxDecoration(
                                      gradient: LinearGradient(
                                        begin: Alignment(-1.8 + flow * 3.6, 0),

                                        end: Alignment(-0.2 + flow * 3.6, 0),

                                        colors: activeColors,
                                      ),
                                    ),
                                  ),

                                  Align(
                                    alignment: Alignment.topCenter,

                                    child: Container(
                                      height: 2,

                                      decoration: BoxDecoration(
                                        gradient: LinearGradient(
                                          colors: [
                                            Colors.white.withValues(
                                              alpha: 0.65,
                                            ),

                                            Colors.white.withValues(
                                              alpha: 0.08,
                                            ),
                                          ],
                                        ),
                                      ),
                                    ),
                                  ),

                                  Align(
                                    alignment: Alignment.bottomCenter,

                                    child: Container(
                                      height: 1.3,

                                      color: Colors.black.withValues(
                                        alpha: 0.18,
                                      ),
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          );
                        },
                      ),
                    ),

                    const SizedBox(height: 6),

                    Row(
                      children: [
                        Text(
                          '$minutesInLevel / '
                          '$requiredMinutes min',

                          style: const TextStyle(
                            color: Colors.white54,

                            fontSize: 10,

                            fontWeight: FontWeight.w600,
                          ),
                        ),

                        const Spacer(),

                        Text(
                          _formatTimeLeft(minutesLeft),

                          style: const TextStyle(
                            color: Colors.white70,

                            fontSize: 10,

                            fontWeight: FontWeight.w600,
                          ),
                        ),
                      ],
