  int _achievementTabIndex(
  String? achievementId,
) {
  if (achievementId == null ||
      achievementId.isEmpty) {
    return 0;
  }

  // =========================
  // MOVIES
  // =========================
  if (achievementId.startsWith(
        'movies_',
      ) ||
      achievementId.startsWith(
        'movies_rated_',
      )) {
    return 0;
  }

  // =========================
  // TV SHOWS
  // =========================
  if (achievementId.startsWith(
        'tv_',
      ) ||
      achievementId.startsWith(
        'episodes_',
      ) ||
      achievementId.startsWith(
        'tv_rated_',
      ) ||
      achievementId.startsWith(
        'episodes_rated_',
      )) {
    return 1;
  }

  // =========================
  // COMMUNITY
  // =========================
  if (achievementId.startsWith(
        'followers_',
      ) ||
      achievementId.startsWith(
        'profile_views_',
      )) {
    return 2;
  }

  // =========================
  // CHIPLUX
  // =========================
  if (achievementId.startsWith(
        'login_',
      ) ||
      achievementId.startsWith(
        'runtime_level_',
      ) ||
      achievementId.startsWith(
        'ratings_level_',
      ) ||
      achievementId.startsWith(
        'medal_collection_',
      )) {
    return 3;
  }

  return 0;
}

Future<void> _openNewEpisodeNotification(
  ChipluxNotification notification,
) async {
  final showId =
      notification.tmdbId;

  final seasonNumber =
      notification.seasonNumber;

  final episodeNumber =
      notification.episodeNumber;

  if (showId == null ||
      seasonNumber == null ||
      episodeNumber == null) {
    ScaffoldMessenger.of(context)
        .showSnackBar(
      const SnackBar(
        content: Text(
          'Could not open this episode.',
        ),
      ),
    );

    return;
  }

  try {
    final episodes =
        await tmdbService.getSeasonEpisodes(
      showId,
      seasonNumber,
    );

    Map<String, dynamic>? foundEpisode;

    for (final raw in episodes) {
      if (raw is! Map) {
        continue;
      }

      final episode =
          Map<String, dynamic>.from(
        raw,
      );

      final number =
          episode['episode_number'];

      if (number is num &&
          number.toInt() ==
              episodeNumber) {
        foundEpisode = episode;
        break;
      }
    }

    if (!mounted) {
      return;
    }

    if (foundEpisode == null) {
      ScaffoldMessenger.of(context)
          .showSnackBar(
        const SnackBar(
          content: Text(
            'Could not find this episode.',
          ),
        ),
      );

      return;
    }

    final rawRuntime =
        foundEpisode['runtime'];

    final rawRating =
        foundEpisode['vote_average'];

    await Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) =>
            SwipeableEpisodePage(
          showId: showId,

          seasonNumber:
              seasonNumber,

          episodeNumber:
              episodeNumber,

          title:
              foundEpisode?['name']
                      ?.toString() ??
                  'Episode $episodeNumber',

          stillPath:
              foundEpisode?['still_path']
                  ?.toString(),

          runtime:
              rawRuntime is num
                  ? rawRuntime.toInt()
                  : null,

          rating:
              rawRating is num &&
                      rawRating.toDouble() >
                          0
                  ? rawRating.toDouble()
                  : null,

          overview:
              foundEpisode?['overview']
                      ?.toString() ??
                  '',

          airDate:
              foundEpisode?['air_date']
                  ?.toString(),
        ),
      ),
    );
  } catch (e) {
    debugPrint(
      'Could not open new episode notification: $e',
    );

    if (!mounted) {
      return;
    }

    ScaffoldMessenger.of(context)
        .showSnackBar(
      const SnackBar(
        content: Text(
          'Could not open this episode.',
        ),
      ),
    );
  }
}

Future<void> _openChipluxUpdate(
  ChipluxNotification notification,
) async {
  await _showChipluxUpdateDialog(
    context: context,
    title: notification.title,
    body: notification.body,
  );
}

  Future<void> _openNotification(
  ChipluxNotification notification,
) async {
  // Mark it read immediately.
  await service.markRead(
    notification.id,
  );

  if (!mounted) {
    return;
  }

  // ===================================================
// NEW FOLLOWER
// ===================================================
if (notification.type ==
    'new_follower') {
  final followerUserId =
      notification.actorUserId;

  if (followerUserId == null ||
      followerUserId.isEmpty) {
    ScaffoldMessenger.of(context)
        .showSnackBar(
      const SnackBar(
        content: Text(
          'Could not open this profile.',
        ),
      ),
    );

    return;
  }

  await Navigator.push(
    context,

    MaterialPageRoute(
      builder: (_) =>
          PublicProfilePage(
        userId: followerUserId,
      ),
    ),
  );

  return;
}

// ===================================================
// ACHIEVEMENT
// ===================================================
if (notification.type ==
    'achievement') {
  final tabIndex =
      _achievementTabIndex(
    notification.achievementId,
  );

  await Navigator.push(
    context,

    MaterialPageRoute(
      builder: (_) =>
          AchievementsPage(
        initialTabIndex:
            tabIndex,

        initialAchievementId:
            notification.achievementId,
      ),
    ),
  );

  return;
}

// ===================================================
// RELEASE REMINDER
// ===================================================
if (notification.type ==
    'release') {
  final tmdbId =
      notification.tmdbId;

  final mediaType =
      notification.mediaType;

  if (tmdbId == null ||
      mediaType == null ||
      (mediaType != 'movie' &&
          mediaType != 'tv')) {
    ScaffoldMessenger.of(context)
        .showSnackBar(
      const SnackBar(
        content: Text(
          'Could not open this title.',
        ),
      ),
    );

    return;
  }

  await Navigator.push(
    context,

    MaterialPageRoute(
      builder: (_) =>
          MediaDetailsPage(
        id: tmdbId,
        mediaType: mediaType,
      ),
    ),
  );

  return;
}

// ===================================================
// NEW EPISODE
// ===================================================
if (notification.type ==
    'new_episode') {
  await _openNewEpisodeNotification(
    notification,
  );

  return;
}

// ===================================================
// CHIPLUX UPDATE
// ===================================================
if (notification.type ==
    'chiplux_update') {
  await _openChipluxUpdate(
    notification,
  );

  return;
}


// ===================================================
// COMMENT NOTIFICATIONS
// ===================================================
final bool opensDiscussion =
    notification.type == 'comment_reply' ||
    notification.type ==
        'comment_like_milestone';

if (!opensDiscussion) {
  return;
}

  final mediaType =
      notification.mediaType;

  final tmdbId =
      notification.tmdbId;

  if (mediaType == null ||
      tmdbId == null) {
    ScaffoldMessenger.of(context)
        .showSnackBar(
      const SnackBar(
        content: Text(
          'Could not open this notification.',
        ),
      ),
    );

    return;
  }

  try {
    // ===================================================
    // EPISODE DISCUSSION
    // ===================================================
    if (mediaType == 'episode') {
      final seasonNumber =
          notification.seasonNumber;

      final episodeNumber =
          notification.episodeNumber;

      if (seasonNumber == null ||
          episodeNumber == null) {
        throw Exception(
          'Missing episode information.',
        );
      }

      final showDetails =
          await tmdbService.getDetails(
        tmdbId,
        'tv',
      );

      final episodes =
          await tmdbService
              .getSeasonEpisodes(
        tmdbId,
        seasonNumber,
      );

      Map<String, dynamic>?
          episodeDetails;

      for (final raw in episodes) {
        if (raw is! Map) {
          continue;
        }

        final episode =
            Map<String, dynamic>.from(
          raw,
        );

        final rawEpisodeNumber =
            episode['episode_number'];

        if (rawEpisodeNumber is num &&
            rawEpisodeNumber.toInt() ==
                episodeNumber) {
          episodeDetails = episode;

          break;
        }
      }

      final String showTitle =
          (showDetails['name'] ??
                  LibraryService.instance
                      .getItem(
                        tmdbId,
                        'tv',
                      )
                      ?.title ??
                  'TV Show')
              .toString();

      final String episodeTitle =
          (episodeDetails?['name'] ??
                  'Episode $episodeNumber')
              .toString();

      final String episodeCode =
          'S${seasonNumber.toString().padLeft(2, '0')}'
          'E${episodeNumber.toString().padLeft(2, '0')}';

      final String? stillPath =
          episodeDetails?['still_path']
              ?.toString();

      if (!mounted) {
        return;
      }

      await Navigator.push(
        context,

        MaterialPageRoute(
          builder: (_) =>
              CommentsPage(
            mediaType: 'episode',

            tmdbId: tmdbId,

            seasonNumber:
                seasonNumber,

            episodeNumber:
                episodeNumber,

            title: episodeTitle,

            subtitle:
                '$showTitle • $episodeCode',

            imagePath:
                stillPath,

                targetCommentId:
    notification.commentId,

            onProfileTap:
                (userId) async {
              await Navigator.push(
                context,

                MaterialPageRoute(
                  builder: (_) =>
                      PublicProfilePage(
                    userId: userId,
                  ),
                ),
              );
            },
          ),
        ),
      );

      return;
    }

    // ===================================================
    // MOVIE / TV DISCUSSION
    // ===================================================
    if (mediaType == 'movie' ||
        mediaType == 'tv') {
      final details =
          await tmdbService.getDetails(
        tmdbId,
        mediaType,
      );

      final libraryItem =
          LibraryService.instance
              .getItem(
        tmdbId,
        mediaType,
      );

      final String title =
          (details['title'] ??
                  details['name'] ??
                  libraryItem?.title ??
                  'Discussion')
              .toString();

      final String? backdropPath =
          details['backdrop_path']
              ?.toString();

      if (!mounted) {
        return;
      }

      await Navigator.push(
        context,

        MaterialPageRoute(
          builder: (_) =>
              CommentsPage(
            mediaType: mediaType,

            tmdbId: tmdbId,

            title: title,

            imagePath:
                backdropPath,

                targetCommentId:
    notification.commentId,

            onProfileTap:
                (userId) async {
              await Navigator.push(
                context,

                MaterialPageRoute(
                  builder: (_) =>
                      PublicProfilePage(
                    userId: userId,
                  ),
                ),
              );
            },
          ),
        ),
      );

      return;
    }
  } catch (e) {
    debugPrint(
      'Could not open notification: $e',
    );

    if (!mounted) {
      return;
    }

    ScaffoldMessenger.of(context)
        .showSnackBar(
      const SnackBar(
        content: Text(
          'Could not open this discussion.',
        ),
      ),
    );
  }
}

  String _timeAgo(DateTime date) {
    final difference =
        DateTime.now().difference(date);

    if (difference.inSeconds < 60) {
      return 'Just now';
    }

    if (difference.inMinutes < 60) {
      return '${difference.inMinutes}m ago';
    }

    if (difference.inHours < 24) {
      return '${difference.inHours}h ago';
    }

    if (difference.inDays < 7) {
      return '${difference.inDays}d ago';
    }

    return '${date.day}/${date.month}/${date.year}';
  }

  IconData _iconFor(
    ChipluxNotification notification,
  ) {
    switch (notification.type) {
      case 'comment_reply':
        return Icons.reply_rounded;

      case 'comment_like_milestone':
        return Icons.favorite_rounded;

      case 'new_follower':
        return Icons.person_add_alt_1_rounded;

      case 'achievement':
        return Icons
            .workspace_premium_rounded;

      case 'new_episode':
        return Icons.tv_rounded;

      case 'release':
  return Icons
      .calendar_month_rounded;

case 'chiplux_update':
  return Icons
      .auto_awesome_rounded;

default:
        return Icons
            .notifications_rounded;
    }
  }

  String _labelFor(
    ChipluxNotification notification,
  ) {
    switch (notification.type) {
      case 'comment_reply':
        return 'REPLY';

      case 'comment_like_milestone':
        return 'LIKE MILESTONE';

      case 'new_follower':
        return 'NEW FOLLOWER';

      case 'achievement':
        return 'ACHIEVEMENT';

      case 'new_episode':
        return 'NEW EPISODE';

      case 'release':
        return 'RELEASE';

      case 'chiplux_update':
        return 'CHIPLUX UPDATE';

      default:
        return 'ACTIVITY';
    }
  }

