                          SizedBox(
                    height:
                        index == 0
                            ? 12
                            : 9,
                  ),

                  itemBuilder:
                      (context, index) {
                    if (index == 0) {
                      return Container(
                        padding:
                            const EdgeInsets
                                .fromLTRB(
                          3,
                          2,
                          3,
                          0,
                        ),
                        child: Row(
                          children: [
                            const Text(
                              'RECENT ACTIVITY',
                              style:
                                  TextStyle(
                                color:
                                    Colors
                                        .white38,
                                fontSize: 9,
                                fontWeight:
                                    FontWeight
                                        .w900,
                                letterSpacing:
                                    1.5,
                              ),
                            ),

                            const SizedBox(
                              width: 9,
                            ),

                            Expanded(
                              child: Container(
                                height: 1,
                                decoration:
                                    BoxDecoration(
                                  gradient:
                                      LinearGradient(
                                    colors: [
                                      chipluxCyan
                                          .withValues(
                                        alpha:
                                            0.35,
                                      ),
                                      chipluxViolet
                                          .withValues(
                                        alpha:
                                            0.18,
                                      ),
                                      Colors
                                          .transparent,
                                    ],
                                  ),
                                ),
                              ),
                            ),

                            if (unreadCount >
                                0) ...[
                              const SizedBox(
                                width: 9,
                              ),
                              Container(
                                padding:
                                    const EdgeInsets
                                        .symmetric(
                                  horizontal:
                                      8,
                                  vertical:
                                      4,
                                ),
                                decoration:
                                    BoxDecoration(
                                  color:
                                      chipluxViolet
                                          .withValues(
                                    alpha:
                                        0.08,
                                  ),
                                  borderRadius:
                                      BorderRadius
                                          .circular(
                                    999,
                                  ),
                                  border:
                                      Border.all(
                                    color:
                                        chipluxViolet
                                            .withValues(
                                      alpha:
                                          0.28,
                                    ),
                                  ),
                                ),
                                child: Text(
                                  '$unreadCount UNREAD',
                                  style:
                                      const TextStyle(
                                    color:
                                        chipluxViolet,
                                    fontSize: 8,
                                    fontWeight:
                                        FontWeight
                                            .w900,
                                    letterSpacing:
                                        0.8,
                                  ),
                                ),
                              ),
                            ],
                          ],
                        ),
                      );
                    }

                    final notification =
                        notifications[
                            index - 1];

                    return Dismissible(
                      key: ValueKey(
                        notification.id,
                      ),

                      direction:
                          DismissDirection
                              .endToStart,

                      background: Container(
                        alignment:
                            Alignment
                                .centerRight,

                        padding:
                            const EdgeInsets
                                .only(
                          right: 20,
                        ),

                        decoration:
                            BoxDecoration(
                          color: Colors
                              .redAccent
                              .withValues(
                            alpha: 0.12,
                          ),
                          borderRadius:
                              BorderRadius
                                  .circular(
                            19,
                          ),
                          border:
                              Border.all(
                            color: Colors
                                .redAccent
                                .withValues(
                              alpha: 0.22,
                            ),
                          ),
                        ),

                        child: const Row(
                          mainAxisAlignment:
                              MainAxisAlignment
                                  .end,
                          mainAxisSize:
                              MainAxisSize.min,
                          children: [
                            Text(
                              'REMOVE',
                              style:
                                  TextStyle(
                                color: Colors
                                    .redAccent,
                                fontSize: 9,
                                fontWeight:
                                    FontWeight
