class NotificationSettingsPage extends StatefulWidget {
  const NotificationSettingsPage({super.key});

  @override
  State<NotificationSettingsPage> createState() =>
      _NotificationSettingsPageState();
}

class _NotificationSettingsPageState
    extends State<NotificationSettingsPage> {
  final settings =
      NotificationSettingsService.instance;

  bool loading = true;

  @override
  void initState() {
    super.initState();

    _load();
  }

  Future<void> _load() async {
    try {
      await settings.load();
    } catch (e) {
      debugPrint(
        'Could not load notification settings: $e',
      );
    }

    if (!mounted) {
      return;
    }

    setState(() {
      loading = false;
    });
  }

  Future<void> _change({
    required bool value,
    required Future<void> Function(bool value)
        save,
  }) async {
    try {
      await save(value);

      if (!mounted) {
        return;
      }

      setState(() {});
    } catch (e) {
      if (!mounted) {
        return;
      }

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Could not update notification setting.',
          ),
        ),
      );
    }
  }

  Widget _sectionLabel(String text) {
    return Padding(
      padding: const EdgeInsets.only(
        left: 4,
        bottom: 8,
      ),

      child: Text(
        text,

        style: const TextStyle(
          color: chipluxCyan,
          fontSize: 11,
          fontWeight: FontWeight.bold,
          letterSpacing: 1.2,
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: chipluxBackground,

      appBar: AppBar(
        title: const Text(
          'Notifications',
        ),
      ),

      body: ChipluxBackground(
        style: ChipluxBackgroundStyle.profile,

        child: loading
            ? const Center(
                child:
                    CircularProgressIndicator(),
              )
            : ListView(
                physics:
                    const AlwaysScrollableScrollPhysics(),

                padding:
                    const EdgeInsets.fromLTRB(
                  18,
                  22,
                  18,
                  35,
                ),

                children: [
                  const _ProfileMenuSectionTitle(
                    title: 'Notifications',
                    subtitle:
                        'Choose which Chiplux notifications you want to receive.',
                  ),

                  const SizedBox(height: 22),

                  // =========================
                  // WATCHING
                  // =========================
                  _sectionLabel('WATCHING'),

                  _ProfileMenuCard(
                    children: [
                      _NotificationSettingRow(
                        icon:
                            Icons.tv_rounded,

                        title:
                            'New Episodes',

                        subtitle:
                            'Notify me when a new episode of a show I am watching becomes available.',

                        value:
                            settings.newEpisodes,

                        onChanged: (value) {
                          _change(
                            value: value,
                            save: settings
                                .setNewEpisodes,
                          );
                        },
                      ),

                      const _ProfileMenuDivider(),

                      _NotificationSettingRow(
                        icon: Icons
                            .calendar_month_rounded,

                        title:
                            'Release Reminders',

                        subtitle:
                            'Notify me when a planned movie or TV show is released.',

                        value:
                            settings.releaseReminders,

                        onChanged: (value) {
                          _change(
                            value: value,
                            save: settings
                                .setReleaseReminders,
                          );
                        },
                      ),
                    ],
                  ),

                  const SizedBox(height: 24),

                  // =========================
                  // COMMUNITY
                  // =========================
                  _sectionLabel('COMMUNITY'),

                  _ProfileMenuCard(
                    children: [
                      _NotificationSettingRow(
                        icon:
                            Icons.reply_rounded,

                        title:
                            'Comments & Replies',

                        subtitle:
                            'Notify me when someone replies to one of my comments.',

                        value:
                            settings.commentsReplies,

                        onChanged: (value) {
                          _change(
                            value: value,
                            save: settings
