                        },
                      ),

                      const _ProfileMenuDivider(),

                      _NotificationSettingRow(
                        icon:
                            Icons.favorite_rounded,

                        title:
                            'Comment Likes',

                        subtitle:
                            'Notify me whenever one of my comments reaches another 100 likes.',

                        value: settings
