                      const _ProfileMenuDivider(),

                      _NotificationSettingRow(
                        icon: Icons
                            .auto_awesome_rounded,

                        title:
                            'Chiplux Updates',

                        subtitle:
                            'Receive important Chiplux feature and app updates.',

                        value:
                            settings.chipluxUpdates,

                        onChanged: (value) {
                          _change(
                            value: value,
                            save: settings
