class PrivacySettingsPage extends StatefulWidget {
  const PrivacySettingsPage({super.key});

  @override
  State<PrivacySettingsPage> createState() =>
      _PrivacySettingsPageState();
}

class _PrivacySettingsPageState
    extends State<PrivacySettingsPage> {
  final settings = PrivacySettingsService.instance;

  bool loading = true;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    try {
      await settings.load();
    } catch (e) {
      debugPrint('Could not load privacy settings: $e');
    }

    if (!mounted) {
      return;
    }

    setState(() {
      loading = false;
    });
  }

  Future<void> _changeBool({
    required bool value,
    required Future<void> Function(bool value) save,
  }) async {
    try {
      await save(value);

      if (!mounted) {
        return;
      }

      setState(() {});
    } catch (e) {
      if (!mounted) {
        return;
      }

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Could not update privacy setting.'),
        ),
      );
    }
  }

  Future<void> _changeString({
    required String value,
    required Future<void> Function(String value) save,
  }) async {
    try {
      await save(value);

      if (!mounted) {
        return;
      }

      setState(() {});
    } catch (e) {
      if (!mounted) {
        return;
      }

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Could not update privacy setting.'),
        ),
      );
    }
  }

  Widget _sectionLabel(String text) {
    return Padding(
      padding: const EdgeInsets.only(left: 4, bottom: 8),
      child: Text(
        text,
        style: const TextStyle(
          color: chipluxCyan,
          fontSize: 11,
          fontWeight: FontWeight.bold,
          letterSpacing: 1.2,
        ),
      ),
    );
  }

  String _profileVisibilityLabel(String value) {
    switch (value) {
      case 'followers':
        return 'Followers';
      case 'private':
        return 'Private';
      case 'everyone':
      default:
        return 'Everyone';
    }
  }

  String _followPermissionLabel(String value) {
    switch (value) {
      case 'people_i_follow':
        return 'People I Follow';
      case 'nobody':
        return 'Nobody';
      case 'everyone':
      default:
        return 'Everyone';
    }
  }

  Future<void> _chooseProfileVisibility() async {
    final value = await showModalBottomSheet<String>(
      context: context,
      backgroundColor: chipluxSurface,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(24),
        ),
      ),
      builder: (sheetContext) {
        return SafeArea(
          child: Padding(
            padding: const EdgeInsets.fromLTRB(18, 18, 18, 20),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
