class BlockedUsersPage extends StatefulWidget {
  const BlockedUsersPage({super.key});

  @override
  State<BlockedUsersPage> createState() =>
      _BlockedUsersPageState();
}

class _BlockedUsersPageState extends State<BlockedUsersPage> {
  final settings = PrivacySettingsService.instance;

  bool loading = true;
  List<Map<String, dynamic>> users = [];

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    try {
      final loaded = await settings.getBlockedUsers();

      if (!mounted) {
        return;
      }

      setState(() {
        users = loaded;
        loading = false;
      });
    } catch (e) {
      if (!mounted) {
        return;
      }

      setState(() {
        users = [];
        loading = false;
      });
    }
  }

  Future<void> _unblock(Map<String, dynamic> user) async {
    final id = user['id']?.toString();

    if (id == null || id.isEmpty) {
      return;
    }

    try {
      await settings.unblockUser(id);
      await _load();
    } catch (e) {
      if (!mounted) {
        return;
      }

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Could not unblock user.'),
        ),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: chipluxBackground,
      appBar: AppBar(
        backgroundColor: chipluxBackground,
        title: const Text('Blocked users'),
      ),
      body: ChipluxBackground(
        style: ChipluxBackgroundStyle.profile,
        child: loading
            ? const Center(
                child: CircularProgressIndicator(),
              )
            : users.isEmpty
            ? const Center(
                child: Padding(
                  padding: EdgeInsets.all(28),
                  child: Text(
                    'You have not blocked anyone.',
                    textAlign: TextAlign.center,
                    style: TextStyle(
                      color: Colors.white54,
                      fontSize: 14,
                    ),
                  ),
                ),
              )
            : ListView.separated(
                padding: const EdgeInsets.fromLTRB(18, 18, 18, 30),
                itemCount: users.length,
                separatorBuilder: (_, _) =>
                    const SizedBox(height: 9),
                itemBuilder: (context, index) {
                  final user = users[index];

                  final displayName =
                      user['display_name']?.toString().trim() ?? '';

                  final username =
                      user['username']?.toString().trim() ?? '';

                  final avatarUrl = user['avatar_url']?.toString();

                  final name = displayName.isNotEmpty
                      ? displayName
                      : username.isNotEmpty
                      ? username
                      : 'Chiplux User';

                  final initial = name.isNotEmpty
                      ? name[0].toUpperCase()
                      : 'C';

                  return Container(
                    padding: const EdgeInsets.all(13),
                    decoration: BoxDecoration(
                      color: chipluxSurface.withValues(alpha: 0.92),
                      borderRadius: BorderRadius.circular(17),
                      border: Border.all(
                        color: Colors.white.withValues(alpha: 0.06),
                      ),
                    ),
                    child: Row(
                      children: [
                        CircleAvatar(
                          radius: 22,
                          backgroundColor: chipluxSurfaceLight,
                          backgroundImage:
                              avatarUrl != null && avatarUrl.isNotEmpty
                              ? NetworkImage(avatarUrl)
                              : null,
                          child: avatarUrl == null || avatarUrl.isEmpty
                              ? Text(
                                  initial,
                                  style: const TextStyle(
                                    color: Colors.white,
                                    fontWeight: FontWeight.bold,
                                  ),
                                )
                              : null,
                        ),
                        const SizedBox(width: 12),
                        Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                name,
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(
                                  color: Colors.white,
                                  fontWeight: FontWeight.w700,
                                ),
                              ),
                              if (username.isNotEmpty) ...[
                                const SizedBox(height: 2),
                                Text(
                                  '@$username',
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  style: const TextStyle(
                                    color: Colors.white38,
                                    fontSize: 11,
                                  ),
                                ),
                              ],
                            ],
                          ),
                        ),
                        const SizedBox(width: 10),
                        OutlinedButton(
                          onPressed: () {
                            _unblock(user);
                          },
                          style: OutlinedButton.styleFrom(
                            foregroundColor: chipluxCyan,
                            side: BorderSide(
                              color: chipluxCyan.withValues(alpha: 0.42),
                            ),
                          ),
                          child: const Text('Unblock'),
                        ),
                      ],
                    ),
                  );
                },
              ),
      ),
    );
  }
}


