class EditProfilePage extends StatefulWidget {
  final bool embedded;

  const EditProfilePage({super.key, this.embedded = false});

  @override
  State<EditProfilePage> createState() => _EditProfilePageState();
}

class _EditProfilePageState extends State<EditProfilePage> {
  final profile = ProfileService.instance;

  final avatarService = AvatarService.instance;

  final library = LibraryService.instance;

  final critic = CriticService.instance;

  final frameService = DisplayNameFrameService.instance;

  final avatarFrameService = AvatarFrameService.instance;

  final achievementCosmeticService = _AchievementCosmeticService.instance;

  final titleService = ProfileTitleService.instance;

  final profilePageFrameService = ProfilePageFrameService.instance;

  late final TextEditingController displayNameController;

  bool saving = false;

  bool uploadingAvatar = false;

  bool loadingFrame = true;

  bool loadingAvatarFrame = true;

  bool loadingAchievementCosmetics = true;

  bool loadingTitle = true;

  bool loadingProfilePageFrame = true;

  String? selectedAvatarFrameId;

  String? selectedFrameId;

  String? selectedTitleId;

  String? selectedProfilePageFrameId;

  Map<String, String?> selectedAchievementCosmetics = {};

  String? errorMessage;

  Uint8List? selectedAvatarBytes;

  String? selectedAvatarExtension;

  @override
  void initState() {
    super.initState();

    displayNameController = TextEditingController(text: profile.displayName);

    selectedFrameId = frameService.frameId;

    selectedAvatarFrameId = avatarFrameService.frameId;

    selectedProfilePageFrameId = profilePageFrameService.frameId;

    unawaited(_loadFrame());

    unawaited(_loadAvatarFrame());

    unawaited(_loadAchievementCosmetics());

    unawaited(_loadProfileTitle());

    unawaited(_loadProfilePageFrame());
  }

  void _setAutoSaveError(Object error) {
    if (!mounted) return;
    setState(() {
      saving = false;
      uploadingAvatar = false;
      errorMessage = 'Could not save change: $error';
    });
  }

  Future<void> _saveDisplayName() async {
    final value = displayNameController.text.trim();
    if (value.isEmpty) {
      if (mounted) setState(() => errorMessage = 'Display name cannot be empty.');
      return;
    }
    if (value == profile.displayName.trim()) return;
    try {
      if (mounted) setState(() { saving = true; errorMessage = null; });
      await profile.updateProfile(displayName: value, username: profile.username);
      if (mounted) setState(() => saving = false);
    } catch (e) { _setAutoSaveError(e); }
  }

  Future<void> _selectDisplayNameFrame(String? id) async {
    try {
      await frameService.apply(id);
      if (mounted) setState(() { selectedFrameId = id; errorMessage = null; });
    } catch (e) { _setAutoSaveError(e); }
  }

  Future<void> _selectAvatarFrame(String? id) async {
    try {
      await avatarFrameService.apply(id);
      if (mounted) setState(() { selectedAvatarFrameId = id; errorMessage = null; });
    } catch (e) { _setAutoSaveError(e); }
  }

  Future<void> _selectProfileTitle(String? id) async {
    try {
      await titleService.apply(id);
      if (mounted) setState(() { selectedTitleId = id; errorMessage = null; });
    } catch (e) { _setAutoSaveError(e); }
  }

  Future<void> _selectProfilePageFrame(String? id) async {
    try {
      await profilePageFrameService.apply(id);
      if (mounted) setState(() { selectedProfilePageFrameId = id; errorMessage = null; });
    } catch (e) { _setAutoSaveError(e); }
  }

  Future<void> _selectAchievementCosmetic(String groupId, String? tierId) async {
    final updated = Map<String, String?>.from(selectedAchievementCosmetics);
    updated[groupId] = tierId;
    try {
      await achievementCosmeticService.applyAll(updated);
      if (mounted) setState(() { selectedAchievementCosmetics = updated; errorMessage = null; });
    } catch (e) { _setAutoSaveError(e); }
  }

  Future<void> _loadProfileTitle() async {
    await Future.wait([
      profile.loadProfile(),

      titleService.load(),

      critic.refresh(),

      DailyLoginService.instance.load(),

      PublicProfileViewService.instance.load(),

      FollowerCountService.instance.load(),
    ]);

    if (!mounted) {
      return;
    }

    String? loadedId = titleService.achievementId;

    if (loadedId != null) {
      if (loadedId == developerProfileTitleId) {
        if (!profile.isDeveloper) {
          loadedId = null;
        }
      } else {
        final achievement = _findProfileTitleAchievement(
          _currentUserProfileTitleGroups(),
          loadedId,
        );

        if (achievement == null) {
          loadedId = null;
        }
      }
    }

    setState(() {
      selectedTitleId = loadedId;

      loadingTitle = false;
    });
  }

