class _EpisodeRatingCard extends StatefulWidget {
  final int showId;
  final int seasonNumber;
  final int episodeNumber;

  const _EpisodeRatingCard({
    required this.showId,
    required this.seasonNumber,
    required this.episodeNumber,
  });

  @override
  State<_EpisodeRatingCard> createState() => _EpisodeRatingCardState();
}

class _EpisodeRatingCardState extends State<_EpisodeRatingCard> {
  final critic = CriticService.instance;

  int? rating;
  int _episodeRatingPulse = 0;
  bool loading = true;

  @override
  void initState() {
    super.initState();
    

    _load();
  }

  Future<void> _load() async {
    final cached = critic.getEpisodeRating(
      widget.showId,
      widget.seasonNumber,
      widget.episodeNumber,
    );

    if (cached != null) {
      rating = cached;
      loading = false;

      return;
    }

    try {
      final result = await critic.loadEpisodeRating(
        widget.showId,
        widget.seasonNumber,
        widget.episodeNumber,
      );

      if (!mounted) return;

      setState(() {
        rating = result;
        loading = false;
      });
    } catch (e) {
      if (!mounted) return;

      setState(() {
        loading = false;
      });
    }
  }

  void _setRating(double x, double width) {
    if (width <= 0) {
      return;
    }

    int stars = ((x / width) * 5).ceil();

    stars = stars.clamp(1, 5).toInt();

    final int oldStars = ((rating ?? 0) / 2).round();

    setState(() {
      if (stars != oldStars) {
        _episodeRatingPulse++;
      }

      rating = stars * 2;
    });
  }

  Future<void> _save() async {
    final currentRating = rating;

    if (currentRating == null) {
      return;
    }

    final int stars = ((currentRating / 2).round().clamp(1, 5)).toInt();

    final show = LibraryService.instance.getItem(widget.showId, 'tv');

    final String showTitle = show?.title ?? 'Unknown TV Show';

    try {
      final int previousEpisodeRatingCount = critic.episodeRatingCount;

      await critic.saveEpisodeRating(
        showId: widget.showId,
        seasonNumber: widget.seasonNumber,
        episodeNumber: widget.episodeNumber,
        rating: currentRating,
      );

      _refreshChipluxAverageRatings();

      final int currentEpisodeRatingCount = critic.episodeRatingCount;

      if (mounted) {
        await _checkEpisodeRatedAchievementUnlock(
          context,
          previousCount: previousEpisodeRatingCount,
          currentCount: currentEpisodeRatingCount,
        );
      }

      // Keep only the newest rating
      // activity for this episode.
      try {
        await CommunityService.instance.deleteActivity(
          activityType: 'rated',
          mediaType: 'tv',
          tmdbId: widget.showId,
          seasonNumber: widget.seasonNumber,
          episodeNumber: widget.episodeNumber,
        );

        await CommunityService.instance.tryCreateActivity(
          activityType: 'rated',
          mediaType: 'tv',
          tmdbId: widget.showId,
          mediaTitle: showTitle,
          seasonNumber: widget.seasonNumber,
          episodeNumber: widget.episodeNumber,
          ratingStars: stars,
        );
      } catch (e) {
        debugPrint('Could not update episode rating activity: $e');
      }
    } catch (e) {
      if (!mounted) {
        return;
      }

      ScaffoldMessenger.of(context)
          .showSnackBar(SnackBar(content: Text('Could not save rating: $e')));
    }
  }

  Future<void> _removeRating() async {
    final oldRating = rating;

    if (oldRating == null) {
      return;
    }

    // Empty the stars immediately.
    setState(() {
      rating = null;
    });

    try {
      await critic.removeEpisodeRating(
        showId: widget.showId,
        seasonNumber: widget.seasonNumber,
        episodeNumber: widget.episodeNumber,
      );

      _refreshChipluxAverageRatings();

      try {
        await CommunityService.instance.deleteActivity(
          activityType: 'rated',
          mediaType: 'tv',
          tmdbId: widget.showId,
          seasonNumber: widget.seasonNumber,
          episodeNumber: widget.episodeNumber,
        );
      } catch (e) {
        debugPrint('Could not remove episode rating activity: $e');
      }
    } catch (e) {
      if (!mounted) {
        return;
      }

      // Restore rating if
      // deleting failed.
      setState(() {
        rating = oldRating;
      });

      ScaffoldMessenger.of(context)
          .showSnackBar(SnackBar(content: Text('Could not remove rating: $e')));
    }
  }

  @override
  Widget build(BuildContext context) {
    if (loading) {
      return const SizedBox(
        height: 80,
        child: Center(child: CircularProgressIndicator(strokeWidth: 2)),
      );
    }

    final bool canRateEpisode = LibraryService.instance.isEpisodeWatched(
    widget.showId,
    widget.seasonNumber,
    widget.episodeNumber,
  );

    return Container(
      padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(
        color: chipluxSurface,
        borderRadius: BorderRadius.circular(18),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text(
            'Your Episode Rating',
            style: TextStyle(fontSize: 16, fontWeight: FontWeight.w600),
          ),

          if (!canRateEpisode) ...[
  const SizedBox(height: 5),

  const Text(
    'Mark this episode as Watched to rate it.',
    style: TextStyle(
      color: Colors.white38,
      fontSize: 11,
    ),
  ),
],

          const SizedBox(height: 12),

          Row(
            children: [
              Expanded(
                child: LayoutBuilder(
                  builder: (context, constraints) {
                    final current = rating ?? 0;

                    final int currentStars = (current / 2).round();

                    return GestureDetector(
                      behavior: HitTestBehavior.opaque,

                      onTapDown: canRateEpisode
    ? (details) {
        _setRating(
          details.localPosition.dx,
          constraints.maxWidth,
        );
      }
    : null,

onTapUp: canRateEpisode
    ? (_) {
        unawaited(_save());
      }
    : null,

onHorizontalDragStart: canRateEpisode
    ? (details) {
        _setRating(
          details.localPosition.dx,
          constraints.maxWidth,
        );
      }
    : null,

onHorizontalDragUpdate: canRateEpisode
    ? (details) {
        _setRating(
          details.localPosition.dx,
          constraints.maxWidth,
        );
      }
    : null,

onHorizontalDragEnd: canRateEpisode
    ? (_) {
        unawaited(_save());
      }
    : null,

                      child: SizedBox(
                        height: 48,
                        child: Row(
                          children: List.generate(5, (index) {
                            final int starNumber = index + 1;

                            return Expanded(
                              child: Center(
                                child: _RatingEffectStar(
  filled: currentStars >= starNumber,
  pulseToken: _episodeRatingPulse,
  size: 36,
  enabled: canRateEpisode,
),
                              ),
                            );
                          }),
                        ),
                      ),
                    );
                  },
                ),
              ),

              if (rating != null) ...[
                const SizedBox(width: 5),

                IconButton(
                  tooltip: 'Remove rating',
                  onPressed: () {
                    unawaited(_removeRating());
                  },
                  icon: const Icon(
                    Icons.delete_outline_rounded,
                    color: Colors.redAccent,
                    size: 23,
                  ),
                ),
              ],
            ],
          ),

          if (rating != null)
            Center(
              child: Text(
                '${(rating! / 2).round()} / 5',
                style: const TextStyle(
                  color: Color(0xFFFFC857),
                  fontWeight: FontWeight.bold,
                ),
              ),
            ),
        ],
      ),
    );
  }
}

String _flagEmojiFromCountryCode(String code) {
  final upper = code.trim().toUpperCase();

  if (upper.length != 2) {
    return '';
  }

  final int first = upper.codeUnitAt(0) - 65 + 0x1F1E6;
  final int second = upper.codeUnitAt(1) - 65 + 0x1F1E6;

  if (first < 0x1F1E6 ||
      first > 0x1F1FF ||
      second < 0x1F1E6 ||
      second > 0x1F1FF) {
    return '';
  }

  return String.fromCharCode(first) + String.fromCharCode(second);
}

class _ChipluxAverageRatingData {
  final double? average;
  final int count;

  const _ChipluxAverageRatingData({required this.average, required this.count});
}

final ValueNotifier<int> _chipluxRatingRefresh = ValueNotifier<int>(0);

void _refreshChipluxAverageRatings() {
  _chipluxRatingRefresh.value++;
}

Future<_ChipluxAverageRatingData> _loadChipluxAverageRating({
  required String mediaType,
  required int tmdbId,
  int? seasonNumber,
  int? episodeNumber,
}) async {
  final params = <String, dynamic>{
    'p_media_type': mediaType,
    'p_tmdb_id': tmdbId,
  };

  if (mediaType == 'episode') {
    params['p_season_number'] = seasonNumber;

    params['p_episode_number'] = episodeNumber;
  }

  final result = await Supabase.instance.client.rpc(
    'get_chiplux_average_rating',
    params: params,
  );

  if (result is! List || result.isEmpty) {
    return const _ChipluxAverageRatingData(average: null, count: 0);
  }

  final row = result.first;

  if (row is! Map) {
    return const _ChipluxAverageRatingData(average: null, count: 0);
  }

  final rawAverage = row['average_rating'];

  final rawCount = row['rating_count'];

  return _ChipluxAverageRatingData(
    average: rawAverage is num
        ? rawAverage.toDouble()
        : double.tryParse(rawAverage?.toString() ?? ''),
    count: rawCount is num
        ? rawCount.toInt()
        : int.tryParse(rawCount?.toString() ?? '') ?? 0,
  );
}

class _ChipluxAverageRating extends StatefulWidget {
  final String mediaType;
  final int tmdbId;
  final int? seasonNumber;
  final int? episodeNumber;

  const _ChipluxAverageRating({
    required this.mediaType,
    required this.tmdbId,
    this.seasonNumber,
    this.episodeNumber,
  });

  @override
  State<_ChipluxAverageRating> createState() => _ChipluxAverageRatingState();
}

class _ChipluxAverageRatingState extends State<_ChipluxAverageRating> {
  late Future<_ChipluxAverageRatingData> _future;

  @override
  void initState() {
    super.initState();

    _future = _load();

    _chipluxRatingRefresh.addListener(_reload);
  }

  Future<_ChipluxAverageRatingData> _load() {
    return _loadChipluxAverageRating(
      mediaType: widget.mediaType,
      tmdbId: widget.tmdbId,
      seasonNumber: widget.seasonNumber,
      episodeNumber: widget.episodeNumber,
    );
  }

  void _reload() {
    if (!mounted) {
      return;
    }

    setState(() {
      _future = _load();
    });
  }

  @override
  void didUpdateWidget(covariant _ChipluxAverageRating oldWidget) {
    super.didUpdateWidget(oldWidget);

    if (oldWidget.mediaType != widget.mediaType ||
        oldWidget.tmdbId != widget.tmdbId ||
        oldWidget.seasonNumber != widget.seasonNumber ||
        oldWidget.episodeNumber != widget.episodeNumber) {
      _reload();
    }
  }

  @override
  void dispose() {
    _chipluxRatingRefresh.removeListener(_reload);

    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<_ChipluxAverageRatingData>(
      future: _future,

      builder: (context, snapshot) {
        final data = snapshot.data;

        final average = data?.average;

        final count = data?.count ?? 0;

        final text = average != null && count > 0
            ? '${average.toStringAsFixed(1)}/5'
            : '--/5';

        return Tooltip(
          message: count == 1
              ? 'Chiplux average · 1 rating'
              : 'Chiplux average · $count ratings',

          child: Row(
            mainAxisSize: MainAxisSize.min,

            children: [
              Image.asset(
                'assets/app_icons/chiplux_rating.png',
                width: 19,
                height: 19,
                fit: BoxFit.contain,
              ),

              const SizedBox(width: 5),

              Text(
                text,

                style: const TextStyle(
                  color: Colors.white70,
                  fontSize: 13,
                  fontWeight: FontWeight.w700,
                ),
              ),
            ],
          ),
        );
      },
    );
  }
}

