String _contentRatingForTitle(Map<String, dynamic> data, String mediaType) {
  // =========================
  // MOVIE
  // =========================

  if (mediaType == 'movie') {
    final releaseDates = data['release_dates'];

    if (releaseDates is Map) {
      final results = releaseDates['results'];

      if (results is List) {
        // Prefer the US rating because
        // this gives PG, PG-13, R, etc.
        for (final item in results) {
          if (item is! Map || item['iso_3166_1']?.toString() != 'US') {
            continue;
          }

          final dates = item['release_dates'];

          if (dates is List) {
            for (final release in dates) {
              if (release is! Map) {
                continue;
              }

              final certification =
                  release['certification']?.toString().trim() ?? '';

              if (certification.isNotEmpty) {
                return certification;
              }
            }
          }
        }

        // Fallback to any country
        // with a certification.
        for (final item in results) {
          if (item is! Map) {
            continue;
          }

          final dates = item['release_dates'];

          if (dates is List) {
            for (final release in dates) {
              if (release is! Map) {
                continue;
              }

              final certification =
                  release['certification']?.toString().trim() ?? '';

              if (certification.isNotEmpty) {
                return certification;
              }
            }
          }
        }
      }
    }
  }

  // =========================
  // TV
  // =========================

  if (mediaType == 'tv') {
    final contentRatings = data['content_ratings'];

    if (contentRatings is Map) {
      final results = contentRatings['results'];

      if (results is List) {
        // Prefer US:
        // TV-PG, TV-14, TV-MA, etc.
        for (final item in results) {
          if (item is! Map || item['iso_3166_1']?.toString() != 'US') {
            continue;
          }

          final rating = item['rating']?.toString().trim() ?? '';

          if (rating.isNotEmpty) {
            return rating;
          }
        }

        // Fallback to another
        // available country rating.
        for (final item in results) {
          if (item is! Map) {
            continue;
          }

          final rating = item['rating']?.toString().trim() ?? '';

          if (rating.isNotEmpty) {
            return rating;
          }
        }
      }
    }
  }

  return '';
}

class _MediaDetailsPageState extends State<MediaDetailsPage> {
  final MediaUserDataService mediaUserDataService =
      MediaUserDataService.instance;

  MediaUserData mediaUserData = MediaUserData.empty();

  final TextEditingController reviewController = TextEditingController();

  bool mediaUserDataLoading = true;
  bool mediaUserDataSaving = false;

  final TmdbService tmdbService = TmdbService();

  final LibraryService library = LibraryService.instance;

  Map<String, dynamic>? details;

  Map<String, dynamic>? featuredPerson;

  String? featuredPersonRole;

  List<Map<String, dynamic>> cast = [];

  bool isLoading = true;
  bool _overviewExpanded = false;
  final GlobalKey _overviewEndKey = GlobalKey();
  int _mediaRatingPulse = 0;

  String? errorMessage;

  final Map<int, List<dynamic>> loadedEpisodes = {};

  final Set<int> loadingSeasons = {};
  final Set<int> expandedSeasons = {};

  @override
  void initState() {
    super.initState();

    loadDetails();
    loadMediaUserData();
  }

  Future<void> _loadFeaturedPerson(Map<String, dynamic> mediaDetails) async {
    try {
      Map<String, dynamic>? foundPerson;

      String? foundRole;

      final credits = await tmdbService.getCredits(widget.id, widget.mediaType);

      final List<dynamic> crew = credits['crew'] ?? [];

      final List<dynamic> rawCast = credits['cast'] ?? [];

      final loadedCast = <Map<String, dynamic>>[];

      for (final raw in rawCast) {
        if (raw is! Map) {
          continue;
        }

        loadedCast.add(Map<String, dynamic>.from(raw));
      }

      // TMDB billing order.
      loadedCast.sort((a, b) {
        final aOrder = a['order'] is num ? (a['order'] as num).toInt() : 9999;

        final bOrder = b['order'] is num ? (b['order'] as num).toInt() : 9999;

        return aOrder.compareTo(bOrder);
      });

      Map<String, dynamic>? findCrewMember(bool Function(String job) matches) {
        for (final raw in crew) {
          if (raw is! Map) {
            continue;
          }

          final person = Map<String, dynamic>.from(raw);

          final job = (person['job'] ?? '').toString();

          if (matches(job)) {
            return person;
          }
        }

        return null;
      }

      // =================================
      // MOVIE -> DIRECTOR
      // =================================

      if (widget.mediaType == 'movie') {
        foundPerson = findCrewMember((job) => job == 'Director');

        if (foundPerson != null) {
          foundRole = 'Director';
        }
      }

      // =================================
      // TV -> PRODUCER
      // =================================

      if (widget.mediaType == 'tv') {
        // Prefer Executive Producer.
        foundPerson = findCrewMember((job) => job == 'Executive Producer');

        if (foundPerson != null) {
          foundRole = 'Executive Producer';
        }

        // Then normal Producer.
        foundPerson ??= findCrewMember((job) => job == 'Producer');

        if (foundPerson != null && foundRole == null) {
          foundRole = 'Producer';
        }

        // If TMDB doesn't provide a
        // producer, use the show's creator.
        if (foundPerson == null) {
          final List<dynamic> creators = mediaDetails['created_by'] ?? [];

          if (creators.isNotEmpty) {
            final first = creators.first;

            if (first is Map) {
              foundPerson = Map<String, dynamic>.from(first);

              foundRole = 'Creator';
            }
          }
        }
      }

      if (!mounted) {
        return;
      }

      setState(() {
        featuredPerson = foundPerson;

        featuredPersonRole = foundRole;

        cast = loadedCast;
      });
    } catch (e) {
      debugPrint('Could not load director/producer: $e');
    }
  }

  Future<void> _scrollToOverviewEnd() async {
    // Wait for AnimatedSize
    // to finish expanding.
    await Future.delayed(const Duration(milliseconds: 300));

    if (!mounted) {
      return;
    }

    final targetContext = _overviewEndKey.currentContext;

    if (targetContext == null || !targetContext.mounted) {
      return;
    }

    await Scrollable.ensureVisible(
      targetContext,
      duration: const Duration(milliseconds: 350),
      curve: Curves.easeInOutCubic,
      alignment: 0.85,
    );
  }

  Future<void> loadMediaUserData() async {
    try {
      final result = await mediaUserDataService.load(
        widget.id,
        widget.mediaType,
      );

      if (!mounted) return;

      setState(() {
        mediaUserData = result;
        reviewController.text = result.review;

        mediaUserDataLoading = false;
      });
    } catch (e) {
      if (!mounted) return;

      setState(() {
        mediaUserDataLoading = false;
      });
    }
  }

  Future<void> toggleFavorite() async {
    final newValue = !mediaUserData.isFavorite;

    final String mediaTitle =
        (details?['title'] ??
                details?['name'] ??
                library.getItem(widget.id, widget.mediaType)?.title ??
                'Unknown')
            .toString();

    setState(() {
      mediaUserData = MediaUserData(
        isFavorite: newValue,
        rating: mediaUserData.rating,
        review: mediaUserData.review,
      );
    });

    try {
      await mediaUserDataService.save(
        tmdbId: widget.id,
        mediaType: widget.mediaType,
        isFavorite: newValue,
        rating: mediaUserData.rating,
        review: reviewController.text,
      );

      // =====================================
      // COMMUNITY FAVORITE ACTIVITY
      // =====================================

      try {
        // Remove any old favorite event
        // for this title first.
        await CommunityService.instance.deleteActivity(
          activityType: 'favorite',
          mediaType: widget.mediaType,
          tmdbId: widget.id,
          titleLevelOnly: true,
        );

        if (newValue) {
          await CommunityService.instance.tryCreateActivity(
            activityType: 'favorite',
            mediaType: widget.mediaType,
            tmdbId: widget.id,
            mediaTitle: mediaTitle,
          );
        }
      } catch (e) {
        debugPrint('Could not update favorite activity: $e');
      }

      if (newValue && mounted) {
        showFavoriteBurst(context);
      }
    } catch (e) {
      if (!mounted) {
        return;
      }

      // Restore previous state if
      // saving the favorite failed.
      setState(() {
        mediaUserData = MediaUserData(
          isFavorite: !newValue,
          rating: mediaUserData.rating,
          review: mediaUserData.review,
        );
      });

      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text('Could not update favorite: $e')));
    }
  }

  Future<void> _removeMediaRating() async {
    final oldRating = mediaUserData.rating;

    if (oldRating == null) {
      return;
    }

    // Clear it visually first.
    setState(() {
      mediaUserData = MediaUserData(
        isFavorite: mediaUserData.isFavorite,
        rating: null,
        review: mediaUserData.review,
      );
    });

    try {
      await mediaUserDataService.save(
        tmdbId: widget.id,
        mediaType: widget.mediaType,
        isFavorite: mediaUserData.isFavorite,

        // NULL = no rating.
        rating: null,

        review: reviewController.text,
      );

      _refreshChipluxAverageRatings();

      // Updates XP, rating counts,
      // Rated state, sorting, etc.
      await CriticService.instance.refresh();
      try {
        await CommunityService.instance.deleteActivity(
          activityType: 'rated',
          mediaType: widget.mediaType,
          tmdbId: widget.id,
          titleLevelOnly: true,
        );
      } catch (e) {
        debugPrint('Could not remove rating activity: $e');
      }
    } catch (e) {
      if (!mounted) {
        return;
      }

      // Restore rating if saving
      // failed.
      setState(() {
        mediaUserData = MediaUserData(
          isFavorite: mediaUserData.isFavorite,
          rating: oldRating,
          review: mediaUserData.review,
        );
      });

      ScaffoldMessenger.of(context)
          .showSnackBar(SnackBar(content: Text('Could not remove rating: $e')));
    }
  }

  Future<void> saveMediaUserData() async {
    setState(() {
      mediaUserDataSaving = true;
    });

    try {
      await mediaUserDataService.save(
        tmdbId: widget.id,
        mediaType: widget.mediaType,
        isFavorite: mediaUserData.isFavorite,
        rating: mediaUserData.rating,
        review: reviewController.text,
      );

      if (!mounted) return;

      setState(() {
        mediaUserData = MediaUserData(
          isFavorite: mediaUserData.isFavorite,
          rating: mediaUserData.rating,
          review: reviewController.text.trim(),
        );
      });

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Your rating and notes were saved.')),
      );
    } catch (e) {
      if (!mounted) return;

      ScaffoldMessenger.of(context)
          .showSnackBar(SnackBar(content: Text('Could not save: $e')));
    } finally {
      if (mounted) {
        setState(() {
          mediaUserDataSaving = false;
        });
      }
    }
  }

  Future<void> loadDetails() async {
    try {
      final result = await tmdbService.getDetails(widget.id, widget.mediaType);

      if (!mounted) return;

      setState(() {
        details = result;
        isLoading = false;
      });

      unawaited(_loadFeaturedPerson(result));
    } catch (e) {
      if (!mounted) return;

      setState(() {
        errorMessage = 'Could not load details.';
        isLoading = false;
      });
    }
  }

  Future<void> loadSeason(int seasonNumber) async {
    if (loadedEpisodes.containsKey(seasonNumber)) {
      return;
    }

    setState(() {
      loadingSeasons.add(seasonNumber);
    });

    try {
      final episodes = await tmdbService.getSeasonEpisodes(
        widget.id,
        seasonNumber,
      );

      if (!mounted) return;

      setState(() {
        loadedEpisodes[seasonNumber] = episodes;

        loadingSeasons.remove(seasonNumber);
      });
    } catch (e) {
      if (!mounted) return;

      setState(() {
        loadingSeasons.remove(seasonNumber);
      });
    }
  }

  Widget _buildPersonalMediaSection() {
    if (mediaUserDataLoading) {
      return const Center(
        child: Padding(
          padding: EdgeInsets.all(20),
          child: CircularProgressIndicator(),
        ),
      );
    }

    final libraryItem = library.getItem(widget.id, widget.mediaType);

    final bool canRateOrFavorite =
        libraryItem?.status == 'watching' || libraryItem?.status == 'completed';

    void setRatingFromPosition(double x, double width) {
      if (width <= 0) {
        return;
      }

      int stars = ((x / width) * 5).ceil();

      stars = stars.clamp(1, 5).toInt();

      final int oldStars = ((mediaUserData.rating ?? 0) / 2).round();

      final int rating = stars * 2;

      setState(() {
        // Only trigger another animation
        // when the finger crosses into
        // another star.
        if (stars != oldStars) {
          _mediaRatingPulse++;
        }

        mediaUserData = MediaUserData(
          isFavorite: mediaUserData.isFavorite,
          rating: rating,
          review: mediaUserData.review,
        );
      });
    }

    Future<void> saveRatingNow() async {
      final rating = mediaUserData.rating;

      if (rating == null) {
        return;
      }

      final int stars = (rating / 2).round().clamp(1, 5);

      final String mediaTitle =
          (details?['title'] ??
                  details?['name'] ??
                  library.getItem(widget.id, widget.mediaType)?.title ??
                  'Unknown')
              .toString();

      final critic = CriticService.instance;

      final int previousCount = widget.mediaType == 'movie'
          ? critic.movieRatingCount
          : critic.tvRatingCount;

      try {
        await mediaUserDataService.save(
          tmdbId: widget.id,
          mediaType: widget.mediaType,
          isFavorite: mediaUserData.isFavorite,
          rating: rating,
          review: mediaUserData.review,
        );

        _refreshChipluxAverageRatings();

        await critic.refresh();

        final int currentCount = widget.mediaType == 'movie'
            ? critic.movieRatingCount
            : critic.tvRatingCount;

        if (mounted) {
          await _checkTitleRatedAchievementUnlock(
            context,
            mediaType: widget.mediaType,
            previousCount: previousCount,
            currentCount: currentCount,
          );
        }

        try {
          await CommunityService.instance.deleteActivity(
            activityType: 'rated',
            mediaType: widget.mediaType,
            tmdbId: widget.id,
            titleLevelOnly: true,
          );

          await CommunityService.instance.tryCreateActivity(
            activityType: 'rated',
            mediaType: widget.mediaType,
            tmdbId: widget.id,
            mediaTitle: mediaTitle,
            ratingStars: stars,
          );
        } catch (e) {
          debugPrint('Could not update rating activity: $e');
        }
      } catch (e) {
        debugPrint('Could not save rating: $e');
      }
    }

    return Container(
      padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(
        color: chipluxSurface,
        borderRadius: BorderRadius.circular(20),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // FAVORITES
          Row(
            children: [
              const Expanded(
                child: Text(
                  'Add to Favorites',
                  style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold),
                ),
              ),

              IconButton(
                tooltip: mediaUserData.isFavorite
                    ? 'Remove from favorites'
                    : 'Add to favorites',
                onPressed: canRateOrFavorite || mediaUserData.isFavorite
                    ? toggleFavorite
                    : null,
                icon: TweenAnimationBuilder<double>(
                  key: ValueKey(mediaUserData.isFavorite),
                  tween: Tween(begin: 0.65, end: 1.0),
                  duration: const Duration(milliseconds: 350),
                  curve: Curves.elasticOut,
                  builder: (context, scale, child) {
                    return Transform.scale(scale: scale, child: child);
                  },
                  child: Icon(
                    mediaUserData.isFavorite
                        ? Icons.favorite
                        : Icons.favorite_border,
                    color: mediaUserData.isFavorite
                        ? Colors.pinkAccent
                        : canRateOrFavorite
                        ? Colors.white54
                        : Colors.white24,
                    size: 29,
                  ),
                ),
              ),
            ],
          ),

          const SizedBox(height: 18),

          const Text(
            'Your Rating',
            style: TextStyle(fontWeight: FontWeight.w600),
          ),

          if (!canRateOrFavorite) ...[
            const SizedBox(height: 5),

            Text(
              widget.mediaType == 'movie'
                  ? 'Mark this movie as Watched to rate or favorite it.'
                  : 'Start Watching or complete this show to rate or favorite it.',
              style: const TextStyle(color: Colors.white38, fontSize: 11),
            ),
          ],

          const SizedBox(height: 10),

          // 5 STAR RATING + REMOVE BUTTON
          Row(
            children: [
              Expanded(
                child: LayoutBuilder(
                  builder: (context, constraints) {
                    final currentRating = mediaUserData.rating ?? 0;

                    final int currentStars = (currentRating / 2).round();

                    return GestureDetector(
                      behavior: HitTestBehavior.opaque,

                      onTapDown: canRateOrFavorite
                          ? (details) {
                              setRatingFromPosition(
                                details.localPosition.dx,
                                constraints.maxWidth,
                              );
                            }
                          : null,

                      onTapUp: canRateOrFavorite
                          ? (_) async {
                              await saveRatingNow();
                            }
                          : null,

                      onHorizontalDragStart: canRateOrFavorite
                          ? (details) {
                              setRatingFromPosition(
                                details.localPosition.dx,
                                constraints.maxWidth,
                              );
                            }
                          : null,

                      onHorizontalDragUpdate: canRateOrFavorite
                          ? (details) {
                              setRatingFromPosition(
                                details.localPosition.dx,
                                constraints.maxWidth,
                              );
                            }
                          : null,

                      onHorizontalDragEnd: canRateOrFavorite
                          ? (_) async {
                              await saveRatingNow();
                            }
                          : null,

                      child: SizedBox(
                        height: 52,
                        child: Row(
                          children: List.generate(5, (index) {
                            final int starNumber = index + 1;

                            return Expanded(
                              child: Center(
                                child: _RatingEffectStar(
                                  filled: currentStars >= starNumber,
                                  pulseToken: _mediaRatingPulse,
                                  size: 38,
                                  enabled: canRateOrFavorite,
                                ),
                              ),
                            );
                          }),
                        ),
                      ),
                    );
                  },
                ),
              ),

              if (mediaUserData.rating != null) ...[
                const SizedBox(width: 4),

                IconButton(
                  tooltip: 'Remove rating',
                  onPressed: () {
                    unawaited(_removeMediaRating());
                  },
                  icon: const Icon(
                    Icons.delete_outline_rounded,
                    color: Colors.redAccent,
                    size: 23,
                  ),
                ),
              ],
            ],
          ),

          if (mediaUserData.rating != null) ...[
            const SizedBox(height: 4),

            Center(
              child: Text(
                '${(mediaUserData.rating! / 2).round()} / 5',
                style: const TextStyle(
                  color: chipluxCyan,
                  fontWeight: FontWeight.bold,
                ),
              ),
            ),
          ],
        ],
      ),
    );
  }

  @override
  void dispose() {
    reviewController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (isLoading) {
      return const Scaffold(body: Center(child: CircularProgressIndicator()));
    }

    if (errorMessage != null || details == null) {
      return Scaffold(
        appBar: AppBar(),
        body: Center(child: Text(errorMessage ?? 'Something went wrong')),
      );
    }

    final data = details!;

    final String contentRating = _contentRatingForTitle(data, widget.mediaType);

    final title = data['title'] ?? data['name'] ?? 'Unknown';

    final overview = data['overview'] ?? 'No description available.';

    final posterPath = data['poster_path'];

    final backdropPath = data['backdrop_path'];

    final posterUrl = posterPath != null
        ? 'https://image.tmdb.org/t/p/w500$posterPath'
        : null;

    final backdropUrl = backdropPath != null
        ? 'https://image.tmdb.org/t/p/w1280$backdropPath'
        : null;

    final double rating = (data['vote_average'] ?? 0).toDouble();

    final date = data['release_date'] ?? data['first_air_date'] ?? '';

    final year = date.toString().length >= 4
        ? date.toString().substring(0, 4)
        : '';

    // =========================
// COUNTRY FLAG
// =========================

String countryFlag = '';

final productionCountries = data['production_countries'];

if (productionCountries is List && productionCountries.isNotEmpty) {
  final firstCountry = productionCountries.first;

  if (firstCountry is Map) {
    final code = firstCountry['iso_3166_1']?.toString() ?? '';
    countryFlag = _flagEmojiFromCountryCode(code);
  }
}

// TV shows sometimes provide
// origin_country even if
// production_countries is empty.
if (countryFlag.isEmpty && widget.mediaType == 'tv') {
  final originCountries = data['origin_country'];

  if (originCountries is List && originCountries.isNotEmpty) {
    countryFlag = _flagEmojiFromCountryCode(originCountries.first.toString());
  }
}

    final String tagline = (data['tagline'] ?? '').toString().trim();

    final List<dynamic> genres = data['genres'] ?? [];

    final List<int> genreIds = genres
        .map<int?>((genre) {
          final id = genre['id'];

          return id is num ? id.toInt() : null;
        })
        .whereType<int>()
        .toList();

    final List<dynamic> seasons = List<dynamic>.from(data['seasons'] ?? []);

    seasons.sort((a, b) {
      final int aNumber = a['season_number'] is num
          ? (a['season_number'] as num).toInt()
          : 0;

      final int bNumber = b['season_number'] is num
          ? (b['season_number'] as num).toInt()
          : 0;

      // Season 0 = Specials.
      // Always place it last.
      if (aNumber == 0 && bNumber != 0) {
        return 1;
      }

      if (bNumber == 0 && aNumber != 0) {
        return -1;
      }

      return aNumber.compareTo(bNumber);
    });

    final int totalEpisodes = data['number_of_episodes'] ?? 0;

    final int runtimeMinutes =
        widget.mediaType == 'movie' && data['runtime'] is num
        ? (data['runtime'] as num).toInt()
        : 0;

    final String rawShowStatus = widget.mediaType == 'tv'
        ? (data['status'] ?? '').toString()
        : '';

    String showStatus = rawShowStatus;

    Color showStatusColor = Colors.white60;

    if (widget.mediaType == 'tv') {
      switch (rawShowStatus.toLowerCase()) {
        case 'ended':
          showStatus = 'Ended';
          showStatusColor = const Color(0xFF66E6A8);
          break;

        case 'canceled':
        case 'cancelled':
          showStatus = 'Canceled';
          showStatusColor = const Color(0xFFFF6B6B);
          break;

        case 'returning series':
        case 'in production':
        case 'planned':
          showStatus = 'Ongoing';
          showStatusColor = chipluxCyan;
          break;

        default:
          showStatus = rawShowStatus.isEmpty ? 'Unknown' : rawShowStatus;
          showStatusColor = Colors.white60;
      }
    }

    final int seasonCount =
        widget.mediaType == 'tv' && data['number_of_seasons'] is num
        ? (data['number_of_seasons'] as num).toInt()
        : 0;

    return Scaffold(
      body: CustomScrollView(
        slivers: [
          SliverAppBar(
            expandedHeight: 300,
            pinned: true,
            backgroundColor: chipluxBackground,
            flexibleSpace: FlexibleSpaceBar(
              background: backdropUrl != null
                  ? Stack(
                      fit: StackFit.expand,
                      children: [
                        Image.network(
                          backdropUrl,
                          fit: BoxFit.cover,

                          errorBuilder: (context, error, stackTrace) {
                            return Container(color: chipluxSurface);
                          },
                        ),
                        const DecoratedBox(
                          decoration: BoxDecoration(
                            gradient: LinearGradient(
                              begin: Alignment.topCenter,
                              end: Alignment.bottomCenter,
                              colors: [Colors.transparent, chipluxBackground],
                            ),
                          ),
                        ),
                      ],
                    )
                  : Container(color: chipluxSurface),
            ),
          ),

          SliverToBoxAdapter(
            child: Padding(
              padding: const EdgeInsets.all(20),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      ClipRRect(
                        borderRadius: BorderRadius.circular(15),

                        child: SizedBox(
                          width: 125,
                          height: 188,

                          child: Stack(
                            fit: StackFit.expand,

                            children: [
                              if (posterUrl != null)
                                Image.network(
                                  posterUrl,

                                  fit: BoxFit.cover,

                                  errorBuilder: (context, error, stackTrace) {
                                    return Container(
                                      color: chipluxSurface,

                                      child: const Icon(
                                        Icons.movie_outlined,

                                        color: Colors.white38,
                                      ),
                                    );
                                  },
                                )
                              else
                                Container(
                                  color: chipluxSurface,

                                  child: const Icon(
                                    Icons.movie_outlined,

                                    color: Colors.white38,
                                  ),
                                ),

                              if (contentRating.isNotEmpty)
                                Positioned(
                                  right: 8,
                                  bottom: 8,

                                  child: Container(
                                    padding: const EdgeInsets.symmetric(
                                      horizontal: 7,
                                      vertical: 4,
                                    ),

                                    decoration: BoxDecoration(
                                      color: Colors.black.withValues(
                                        alpha: 0.78,
                                      ),

                                      borderRadius: BorderRadius.circular(6),

                                      border: Border.all(
                                        color: Colors.white.withValues(
                                          alpha: 0.75,
                                        ),

                                        width: 1,
                                      ),

                                      boxShadow: [
                                        BoxShadow(
                                          color: Colors.black.withValues(
                                            alpha: 0.30,
                                          ),

                                          blurRadius: 5,
                                        ),
                                      ],
                                    ),

                                    child: Text(
                                      contentRating,

                                      style: const TextStyle(
                                        color: Colors.white,

                                        fontSize: 10,

                                        fontWeight: FontWeight.w800,

                                        letterSpacing: 0.3,
                                      ),
                                    ),
                                  ),
                                ),
                            ],
                          ),
                        ),
                      ),

                      const SizedBox(width: 18),

                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              title,
                              style: const TextStyle(
                                fontSize: 26,
                                fontWeight: FontWeight.bold,
                              ),
                            ),

                            const SizedBox(height: 8),

                            Text(
                              [
  if (year.isNotEmpty) year,

  widget.mediaType == 'tv' ? 'TV Show' : 'Movie',

  if (countryFlag.isNotEmpty) countryFlag,
].join('  •  '),

                              style: const TextStyle(color: Colors.white60),
                            ),

                            if (widget.mediaType == 'movie' &&
                                tagline.isNotEmpty) ...[
                              const SizedBox(height: 8),

                              Text(
                                '"$tagline"',
                                maxLines: 2,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(
                                  color: Colors.white70,
                                  fontSize: 13,
                                  fontStyle: FontStyle.italic,
                                  height: 1.35,
                                ),
                              ),
                            ],

                            if (widget.mediaType == 'tv') ...[
                              const SizedBox(height: 7),

                              Wrap(
                                spacing: 8,
                                runSpacing: 5,
                                crossAxisAlignment: WrapCrossAlignment.center,
                                children: [
                                  Text(
                                    showStatus,
                                    style: TextStyle(
                                      color: showStatusColor,
                                      fontSize: 14,
                                      fontWeight: FontWeight.w700,
                                    ),
                                  ),

                                  const Text(
                                    '•',
                                    style: TextStyle(
                                      color: Colors.white38,
                                      fontSize: 14,
                                    ),
                                  ),

                                  Text(
                                    '$seasonCount '
                                    '${seasonCount == 1 ? 'Season' : 'Seasons'}',
                                    style: const TextStyle(
                                      color: Colors.white60,
                                      fontSize: 14,
                                      fontWeight: FontWeight.w500,
                                    ),
                                  ),
                                ],
                              ),
                            ],

                            const SizedBox(height: 12),

                            Row(
                              children: [
                                const Icon(
                                  Icons.star,
                                  color: Colors.amber,
                                  size: 20,
                                ),

                                const SizedBox(width: 5),

                                Text('${rating.toStringAsFixed(1)} / 10'),

                                const SizedBox(width: 12),

                                const Text(
                                  '•',
                                  style: TextStyle(color: Colors.white30),
                                ),

                                const SizedBox(width: 12),

                                _ChipluxAverageRating(
                                  mediaType: widget.mediaType,
                                  tmdbId: widget.id,
                                ),
                              ],
                            ),

                            const SizedBox(height: 14),

                            Wrap(
                              spacing: 7,
                              runSpacing: 7,
                              children: genres.map((genre) {
                                return Container(
                                  padding: const EdgeInsets.symmetric(
                                    horizontal: 9,
                                    vertical: 5,
                                  ),
                                  decoration: BoxDecoration(
                                    color: chipluxSurface,
                                    borderRadius: BorderRadius.circular(20),
                                  ),
                                  child: Text(
                                    genre['name'] ?? '',
                                    style: const TextStyle(fontSize: 11),
                                  ),
                                );
                              }).toList(),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),

                  const SizedBox(height: 24),

                  AnimatedBuilder(
                    animation: library,
                    builder: (context, _) {
                      final item = library.getItem(widget.id, widget.mediaType);

                      Future<void> setStatus(String status) async {
                        // Was this title already
                        // completed/watched before
                        // this button press?
                        final bool wasAlreadyCompleted =
                            item?.status == 'completed';

                        final int previousMovieCount =
                            library.moviesWatchedCount;

                        final int previousTvCount =
                            library.completedTvShowsCount;

                        final newItem = LibraryItem(
                          id: widget.id,
                          mediaType: widget.mediaType,
                          title: title,
                          posterPath: posterPath,
                          year: year,
                          status: status,
                          totalEpisodes: totalEpisodes,
                          runtimeMinutes: runtimeMinutes,
                          genreIds: genreIds,
                          addedAt:
                              item?.addedAt ??
                              DateTime.now().millisecondsSinceEpoch,
                        );

                        // First actually save the status.
                        await library.addOrUpdate(newItem);

                        if (!context.mounted) {
                          return;
                        }

                        if (status == 'completed' && !wasAlreadyCompleted) {
                          showCompletionBurst(context);

                          if (widget.mediaType == 'movie') {
                            await _checkMovieAchievementUnlock(
                              context,
                              previousCount: previousMovieCount,
                              currentCount: library.moviesWatchedCount,
                            );
                          } else if (widget.mediaType == 'tv') {
                            await _checkTvAchievementUnlock(
                              context,
                              previousCount: previousTvCount,
                              currentCount: library.completedTvShowsCount,
                            );
                          }
                        }
                      }

                      Widget statusButton({
                        required String status,
                        required String label,
                        required IconData icon,
                        required Color color,
                      }) {
                        final selected = item?.status == status;

                        return Expanded(
                          child: InkWell(
                            borderRadius: BorderRadius.circular(14),
                            onTap: () {
                              unawaited(setStatus(status));
                            },
                            child: AnimatedContainer(
                              duration: const Duration(milliseconds: 180),
                              height: 64,
                              decoration: BoxDecoration(
                                color: selected
                                    ? color.withValues(alpha: 0.20)
                                    : chipluxSurface,
                                borderRadius: BorderRadius.circular(14),
                                border: Border.all(
                                  color: selected
                                      ? color
                                      : Colors.white.withValues(alpha: 0.08),
                                  width: selected ? 1.4 : 1,
                                ),
                              ),
                              child: Column(
                                mainAxisAlignment: MainAxisAlignment.center,
                                children: [
                                  Icon(
                                    icon,
                                    size: 20,
                                    color: selected ? color : Colors.white60,
                                  ),

                                  const SizedBox(height: 5),

                                  Text(
                                    label,
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: TextStyle(
                                      fontSize: 10,
                                      fontWeight: selected
                                          ? FontWeight.bold
                                          : FontWeight.w600,
                                      color: selected ? color : Colors.white60,
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          ),
                        );
                      }

                      Widget removeButton() {
                        return SizedBox(
                          width: 52,
                          height: 64,
                          child: InkWell(
                            borderRadius: BorderRadius.circular(14),
                            onTap: () {
                              unawaited(
                                library.remove(widget.id, widget.mediaType),
                              );
                            },
                            child: Container(
                              decoration: BoxDecoration(
                                color: chipluxSurface,
                                borderRadius: BorderRadius.circular(14),
                                border: Border.all(
                                  color: Colors.redAccent.withValues(
                                    alpha: 0.55,
                                  ),
                                ),
                              ),
                              child: const Center(
                                child: Icon(
                                  Icons.delete_outline_rounded,
                                  color: Colors.redAccent,
                                  size: 23,
                                ),
                              ),
                            ),
                          ),
                        );
                      }

                      // ==========================
                      // TV SHOW
                      // ==========================

                      if (widget.mediaType == 'tv') {
                        return Row(
                          children: [
                            statusButton(
                              status: 'watching',
                              label: 'Watching',
                              icon: Icons.play_circle_outline,
                              color: chipluxCyan,
                            ),

                            const SizedBox(width: 7),

                            statusButton(
                              status: 'completed',
                              label: 'Completed',
                              icon: Icons.check_circle_outline,
                              color: const Color(0xFF7BE8A8),
                            ),

                            const SizedBox(width: 7),

                            statusButton(
                              status: 'plan',
                              label: 'Plan',
                              icon: Icons.bookmark_border,
                              color: chipluxPurple,
                            ),

                            const SizedBox(width: 7),

                            statusButton(
                              status: 'dropped',
                              label: 'Dropped',
                              icon: Icons.close,
                              color: const Color(0xFFFF6B6B),
                            ),

                            if (item != null) ...[
                              const SizedBox(width: 7),

                              removeButton(),
                            ],
                          ],
                        );
                      }

                      // ==========================
                      // MOVIE
                      // ==========================

                      return Row(
                        children: [
                          statusButton(
                            status: 'completed',
                            label: 'Watched',
                            icon: Icons.check_circle_outline,
                            color: const Color(0xFF7BE8A8),
                          ),

                          const SizedBox(width: 8),

                          statusButton(
                            status: 'plan',
                            label: 'Plan',
                            icon: Icons.bookmark_border,
                            color: chipluxPurple,
                          ),

                          if (item != null) ...[
                            const SizedBox(width: 8),

                            removeButton(),
                          ],
                        ],
                      );
                    },
                  ),

                  AnimatedBuilder(
                    animation: library,
                    builder: (context, _) {
                      final item = library.getItem(widget.id, widget.mediaType);

                      final canComment = item?.status == 'completed';

                      if (!canComment) {
                        return const SizedBox.shrink();
                      }

                      return Column(
                        children: [
                          const SizedBox(height: 14),

                          SizedBox(
                            width: double.infinity,

                            child: OutlinedButton.icon(
                              onPressed: () {
                                Navigator.push(
                                  context,

                                  MaterialPageRoute(
                                    builder: (_) => CommentsPage(
                                      onProfileTap: (userId) async {
                                        await Navigator.push(
                                          context,
                                          MaterialPageRoute(
                                            builder: (_) => PublicProfilePage(
                                              userId: userId,
                                            ),
                                          ),
                                        );
                                      },
                                      mediaType: widget.mediaType,

                                      tmdbId: widget.id,

                                      title: title.toString(),

                                      imagePath: backdropPath?.toString(),
                                    ),
                                  ),
                                );
                              },

                              icon: const Icon(Icons.forum_rounded),

                              label: CommentCountLabel(
                                mediaType: widget.mediaType,

                                tmdbId: widget.id,
                              ),

                              style: OutlinedButton.styleFrom(
                                foregroundColor: chipluxCyan,

                                side: BorderSide(
                                  color: chipluxCyan.withValues(alpha: 0.65),
                                ),

                                backgroundColor: chipluxCyan.withValues(
                                  alpha: 0.06,
                                ),

                                padding: const EdgeInsets.symmetric(
                                  vertical: 14,
                                ),

                                shape: RoundedRectangleBorder(
                                  borderRadius: BorderRadius.circular(15),
                                ),
                              ),
                            ),
                          ),
                        ],
                      );
                    },
                  ),

                  const SizedBox(height: 22),

                  AnimatedBuilder(
                    animation: library,
                    builder: (context, _) {
                      return _buildPersonalMediaSection();
                    },
                  ),

                  const SizedBox(height: 30),

                  const Text(
                    'Overview',
                    style: TextStyle(fontSize: 21, fontWeight: FontWeight.bold),
                  ),

                  const SizedBox(height: 10),

                  LayoutBuilder(
                    builder: (context, constraints) {
                      const overviewStyle = TextStyle(
                        fontSize: 15,
                        height: 1.55,
                        color: Colors.white70,
                      );

                      final textPainter = TextPainter(
                        text: TextSpan(text: overview, style: overviewStyle),
                        maxLines: 3,
                        textDirection: TextDirection.ltr,
                      )..layout(maxWidth: constraints.maxWidth);

                      final bool needsExpansion = textPainter.didExceedMaxLines;

                      return Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          AnimatedSize(
                            duration: const Duration(milliseconds: 280),
                            curve: Curves.easeInOutCubic,
                            alignment: Alignment.topCenter,
                            child: Text(
                              overview,
                              maxLines: _overviewExpanded ? null : 3,
                              overflow: _overviewExpanded
                                  ? TextOverflow.visible
                                  : TextOverflow.ellipsis,
                              style: overviewStyle,
                            ),
                          ),

                          if (needsExpansion) ...[
                            const SizedBox(height: 4),

                            InkWell(
                              borderRadius: BorderRadius.circular(8),
                              onTap: () {
                                final bool expanding = !_overviewExpanded;

                                setState(() {
                                  _overviewExpanded = expanding;
                                });

                                if (expanding) {
                                  unawaited(_scrollToOverviewEnd());
                                }
                              },
                              child: Padding(
                                padding: const EdgeInsets.symmetric(
                                  vertical: 6,
                                  horizontal: 2,
                                ),
                                child: Row(
                                  mainAxisSize: MainAxisSize.min,
                                  children: [
                                    Text(
                                      _overviewExpanded
                                          ? 'View less'
                                          : 'View more',
                                      style: const TextStyle(
                                        color: chipluxCyan,
                                        fontSize: 13,
                                        fontWeight: FontWeight.bold,
                                      ),
                                    ),

                                    const SizedBox(width: 3),

                                    Icon(
                                      _overviewExpanded
                                          ? Icons.keyboard_arrow_up_rounded
                                          : Icons.keyboard_arrow_down_rounded,
                                      color: chipluxCyan,
                                      size: 19,
                                    ),
                                  ],
                                ),
                              ),
                            ),
                          ],

                          SizedBox(key: _overviewEndKey, height: 1),
                        ],
                      );
                    },
                  ),

                  // =====================================
                  // DIRECTOR / PRODUCER
                  // =====================================
                  if (featuredPerson != null && featuredPersonRole != null) ...[
                    const SizedBox(height: 18),

                    _CreatorChip(
                      person: featuredPerson!,
                      role: featuredPersonRole!,
                      onTap: () {
                        final rawId = featuredPerson!['id'];

                        if (rawId is! num) {
                          return;
                        }

                        Navigator.push(
                          context,
                          MaterialPageRoute(
                            builder: (_) => PersonProjectsPage(
                              personId: rawId.toInt(),
                              personName:
                                  featuredPerson!['name']?.toString() ??
                                  'Unknown',
                              role: featuredPersonRole!,
                              profilePath: featuredPerson!['profile_path']
                                  ?.toString(),
                            ),
                          ),
                        );
                      },
                    ),
                  ],

                  if (cast.isNotEmpty) ...[
                    const SizedBox(height: 28),

                    const Text(
                      'Top Billed Cast',
                      style: TextStyle(
                        fontSize: 21,
                        fontWeight: FontWeight.bold,
                      ),
                    ),

                    const SizedBox(height: 14),

                    Builder(
                      builder: (context) {
                        final textScale = MediaQuery.textScalerOf(context)
                            .scale(1.0);

                        final extraHeight =
                            ((textScale - 1.0).clamp(0.0, 0.5)) * 30;

                        return SizedBox(
                          height: 212 + extraHeight,
                          child: ListView.separated(
                            scrollDirection: Axis.horizontal,
                            physics: const BouncingScrollPhysics(),
                            itemCount:
                                math.min(cast.length, 8) +
                                (cast.length > 8 ? 1 : 0),
                            separatorBuilder: (_, _) =>
                                const SizedBox(width: 11),
                            itemBuilder: (context, index) {
                              // Last card = View more.
                              if (index == 8) {
                                return _CastViewMoreCard(
                                  remaining: cast.length - 8,
                                  onTap: () {
                                    Navigator.push(
                                      context,
                                      MaterialPageRoute(
                                        builder: (_) => FullCastPage(
                                          title: title.toString(),
                                          cast: cast,
                                        ),
                                      ),
                                    );
                                  },
                                );
                              }

                              return _TopCastCard(person: cast[index]);
                            },
                          ),
                        );
                      },
                    ),
                  ],

                  if (widget.mediaType == 'tv' && seasons.isNotEmpty) ...[
                    const SizedBox(height: 35),

                    const Text(
                      'Seasons',
                      style: TextStyle(
                        fontSize: 21,
                        fontWeight: FontWeight.bold,
                      ),
                    ),

                    const SizedBox(height: 14),

                    ...seasons.map((season) {
                      final int seasonNumber = (season['season_number'] as num)
                          .toInt();

                      final String seasonName =
                          season['name'] ?? 'Season $seasonNumber';

                      final String? seasonPosterPath = season['poster_path']
                          ?.toString();

                      final String? seasonPosterUrl =
                          seasonPosterPath != null &&
                              seasonPosterPath.isNotEmpty
                          ? 'https://image.tmdb.org/t/p/w185$seasonPosterPath'
                          : null;

                      final int episodeCount = season['episode_count'] is num
                          ? (season['episode_count'] as num).toInt()
                          : 0;

                      return AnimatedBuilder(
                        animation: library,
                        builder: (context, _) {
                          final watched = library.watchedCountForSeason(
                            widget.id,
                            seasonNumber,
                          );

                          final allWatched =
                              episodeCount > 0 && watched >= episodeCount;

                          final isExpanded = expandedSeasons.contains(
                            seasonNumber,
                          );

                          final showSeasonGreen = allWatched && !isExpanded;

                          return Container(
                            margin: const EdgeInsets.only(bottom: 12),
                            decoration: BoxDecoration(
                              color: showSeasonGreen
                                  ? const Color(0xFF173A29)
                                  : chipluxSurface,
                              borderRadius: BorderRadius.circular(18),
                              border: showSeasonGreen
                                  ? Border.all(
                                      color: const Color(0xFF7BE8A8)
                                          .withValues(alpha: 0.20),
                                    )
                                  : null,
                            ),
                            child: ExpansionTile(
                              tilePadding: const EdgeInsets.symmetric(
                                horizontal: 16,
                                vertical: 5,
                              ),
                              childrenPadding: const EdgeInsets.fromLTRB(
                                12,
                                0,
                                12,
                                12,
                              ),

                              leading: ClipRRect(
                                borderRadius: BorderRadius.circular(8),
                                child: seasonPosterUrl != null
                                    ? Image.network(
                                        seasonPosterUrl,
                                        width: 44,
                                        height: 66,
                                        fit: BoxFit.cover,
                                        errorBuilder:
                                            (context, error, stackTrace) {
                                              return Container(
                                                width: 44,
                                                height: 66,
                                                color: chipluxSurfaceLight,
                                                child: const Icon(
                                                  Icons.image_outlined,
                                                  color: Colors.white38,
                                                ),
                                              );
                                            },
                                      )
                                    : Container(
                                        width: 44,
                                        height: 66,
                                        color: chipluxSurfaceLight,
                                        child: const Icon(
                                          Icons.image_outlined,
                                          color: Colors.white38,
                                        ),
                                      ),
                              ),

                              title: Text(
                                seasonName,
                                style: TextStyle(
                                  fontWeight: FontWeight.bold,
                                  color: showSeasonGreen
                                      ? const Color(0xFF7BE8A8)
                                      : Colors.white,
                                ),
                              ),

                              subtitle: Padding(
                                padding: const EdgeInsets.only(top: 6),
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Text(
                                      '$watched / $episodeCount watched',
                                      style: TextStyle(
                                        color: showSeasonGreen
                                            ? const Color(0xFF7BE8A8)
                                            : Colors.white54,
                                        fontSize: 12,
                                        fontWeight: showSeasonGreen
                                            ? FontWeight.w600
                                            : FontWeight.normal,
                                      ),
                                    ),

                                    const SizedBox(height: 6),

                                    ClipRRect(
                                      borderRadius: BorderRadius.circular(8),
                                      child: LinearProgressIndicator(
                                        value: episodeCount == 0
                                            ? 0
                                            : (watched / episodeCount).clamp(
                                                0.0,
                                                1.0,
                                              ),
                                        minHeight: 4,
                                        backgroundColor: chipluxSurfaceLight,
                                        color: showSeasonGreen
                                            ? const Color(0xFF7BE8A8)
                                            : chipluxCyan,
                                      ),
                                    ),
                                  ],
                                ),
                              ),

                              trailing: IconButton(
                                tooltip: allWatched
                                    ? 'Clear season'
                                    : 'Mark season watched',
                                onPressed: () async {
                                  if (!loadedEpisodes.containsKey(
                                    seasonNumber,
                                  )) {
                                    await loadSeason(seasonNumber);
                                  }

                                  final episodes = loadedEpisodes[seasonNumber];

                                  if (episodes == null || episodes.isEmpty) {
                                    return;
                                  }

                                  await library.markSeason(
                                    widget.id,
                                    seasonNumber,
                                    episodes,
                                    !allWatched,
                                  );
                                  if (allWatched) {
                                    await CriticService.instance
                                        .clearSeasonAfterUnwatch(
                                          showId: widget.id,
                                          seasonNumber: seasonNumber,
                                        );

                                    try {
                                      await CommunityService.instance
                                          .deleteActivity(
                                            activityType: 'rated',
                                            mediaType: 'tv',
                                            tmdbId: widget.id,
                                            seasonNumber: seasonNumber,
                                          );

                                      if (library.watchedCountForShow(
                                            widget.id,
                                          ) ==
                                          0) {
                                        await CommunityService.instance
                                            .deleteActivity(
                                              activityType: 'rated',
                                              mediaType: 'tv',
                                              tmdbId: widget.id,
                                              titleLevelOnly: true,
                                            );
                                      }
                                    } catch (e) {
                                      debugPrint(
                                        'Could not remove season rating activities: $e',
                                      );
                                    }
                                  }
                                },
                                icon: Icon(
                                  allWatched
                                      ? Icons.check_circle
                                      : Icons.radio_button_unchecked,
                                  color: showSeasonGreen
                                      ? const Color(0xFF7BE8A8)
                                      : Colors.white54,
                                  size: 28,
                                ),
                              ),

                              onExpansionChanged: (expanded) {
                                setState(() {
                                  if (expanded) {
                                    expandedSeasons.add(seasonNumber);
                                  } else {
                                    expandedSeasons.remove(seasonNumber);
                                  }
                                });

                                if (expanded) {
                                  loadSeason(seasonNumber);
                                }
                              },

                              children: [
                                if (loadingSeasons.contains(seasonNumber))
                                  const Padding(
                                    padding: EdgeInsets.all(25),
                                    child: CircularProgressIndicator(),
                                  ),

                                if (loadedEpisodes.containsKey(
                                  seasonNumber,
                                )) ...[
                                  ...loadedEpisodes[seasonNumber]!.map((
                                    episode,
                                  ) {
                                    final int episodeNumber =
                                        (episode['episode_number'] as num)
                                            .toInt();

                                    return _EpisodeTile(
                                      showId: widget.id,
                                      seasonNumber: seasonNumber,
                                      episodeNumber: episodeNumber,
                                      title: episode['name'] ?? 'Episode',
                                      stillPath: episode['still_path'],
                                      runtime: episode['runtime'] is num
                                          ? (episode['runtime'] as num).toInt()
                                          : null,
                                      rating:
                                          episode['vote_average'] is num &&
                                              (episode['vote_average'] as num)
                                                      .toDouble() >
                                                  0
                                          ? (episode['vote_average'] as num)
                                                .toDouble()
                                          : null,
                                      overview:
                                          episode['overview']?.toString() ?? '',
                                      airDate: episode['air_date']?.toString(),
                                    );
                                  }),
                                ],
                              ],
                            ),
                          );
                        },
                      );
                    }),
                  ],
                  const SizedBox(height: 50),
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }
}

