class PersonProjectsPage extends StatefulWidget {
  final int personId;
  final String personName;
  final String role;
  final String? profilePath;

  const PersonProjectsPage({
    super.key,
    required this.personId,
    required this.personName,
    required this.role,
    this.profilePath,
  });

  @override
  State<PersonProjectsPage> createState() => _PersonProjectsPageState();
}

class _PersonProjectsPageState extends State<PersonProjectsPage> {
  final tmdb = TmdbService();

  List<Map<String, dynamic>> projects = [];

  bool loading = true;

  String? error;

  @override
  void initState() {
    super.initState();

    _load();
  }

  Future<void> _load() async {
    try {
      final result = await tmdb.getPersonCombinedCredits(widget.personId);

      final bool isActor = widget.role == 'Actor';

      final List<dynamic> rawCredits = isActor
          ? result['cast'] ?? []
          : result['crew'] ?? [];

      final allCredits = <Map<String, dynamic>>[];

      for (final raw in rawCredits) {
        if (raw is! Map) {
          continue;
        }

        final item = Map<String, dynamic>.from(raw);

        final mediaType = item['media_type'];

        if (mediaType != 'movie' && mediaType != 'tv') {
          continue;
        }

        allCredits.add(item);
      }

      List<Map<String, dynamic>> filtered;

      if (isActor) {
        // Acting credits.
        filtered = allCredits;
      } else if (widget.role == 'Director') {
        filtered = allCredits.where((item) {
          return item['job']?.toString() == 'Director';
        }).toList();
      } else if (widget.role.contains('Producer')) {
        filtered = allCredits.where((item) {
          return item['job']?.toString().contains('Producer') ?? false;
        }).toList();
      } else {
        filtered = allCredits;
      }

      if (filtered.isEmpty) {
        filtered = allCredits;
      }

      // Remove duplicate projects.
      final seen = <String>{};

      filtered = filtered.where((item) {
        final rawId = item['id'];

        final mediaType = item['media_type']?.toString();

        if (rawId is! num || mediaType == null) {
          return false;
        }

        final key = '$mediaType:${rawId.toInt()}';

        return seen.add(key);
      }).toList();

      // Newest projects first.
      filtered.sort((a, b) {
        final aDate = (a['release_date'] ?? a['first_air_date'] ?? '')
            .toString();

        final bDate = (b['release_date'] ?? b['first_air_date'] ?? '')
            .toString();

        return bDate.compareTo(aDate);
      });

      if (!mounted) {
        return;
      }

      setState(() {
        projects = filtered;

        loading = false;
      });
    } catch (e) {
      if (!mounted) {
        return;
      }

      setState(() {
        loading = false;

        error = 'Could not load projects.';
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final profileUrl =
        widget.profilePath != null && widget.profilePath!.isNotEmpty
        ? 'https://image.tmdb.org/t/p/w185${widget.profilePath}'
        : null;

    return Scaffold(
      backgroundColor: chipluxBackground,
      appBar: AppBar(
        backgroundColor: chipluxBackground,
        title: const Text('Projects'),
      ),
      body: ChipluxBackground(
        style: ChipluxBackgroundStyle.discover,
        child: Column(
          children: [
            // ========================
            // PERSON HEADER
            // ========================

            Padding(
              padding: const EdgeInsets.fromLTRB(20, 12, 20, 18),
              child: Row(
                children: [
                  ClipOval(
                    child: profileUrl != null
                        ? Image.network(
                            profileUrl,
                            width: 58,
                            height: 58,
                            fit: BoxFit.cover,

                            errorBuilder: (context, error, stackTrace) {
                              return Container(
                                width: 58,
                                height: 58,
                                color: chipluxSurfaceLight,
                                child: const Icon(
                                  Icons.person_outline,
                                  color: Colors.white38,
                                ),
                              );
                            },
                          )
                        : Container(
                            width: 58,
                            height: 58,
                            color: chipluxSurfaceLight,
                            child: const Icon(Icons.person_outline),
                          ),
                  ),

                  const SizedBox(width: 13),

                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          widget.personName,
                          style: const TextStyle(
                            fontSize: 20,
                            fontWeight: FontWeight.bold,
                          ),
                        ),

                        const SizedBox(height: 4),

                        Text(
                          widget.role,
                          style: const TextStyle(
                            color: chipluxCyan,
                            fontSize: 12,
                            fontWeight: FontWeight.w600,
                          ),
                        ),
                      ],
                    ),
                  ),

                  if (!loading)
                    Text(
                      '${projects.length}',
                      style: const TextStyle(
                        color: Colors.white54,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                ],
              ),
            ),

            Expanded(
              child: loading
                  ? const Center(child: CircularProgressIndicator())
                  : error != null
                  ? Center(
                      child: Text(
                        error!,
                        style: const TextStyle(color: Colors.redAccent),
                      ),
                    )
                  : projects.isEmpty
                  ? const Center(
                      child: Text(
                        'No projects found.',
                        style: TextStyle(color: Colors.white54),
                      ),
                    )
                  : ListView.separated(
                      padding: const EdgeInsets.fromLTRB(20, 0, 20, 30),
                      itemCount: projects.length,
                      separatorBuilder: (_, _) => const SizedBox(height: 9),
                      itemBuilder: (context, index) {
                        return _PersonProjectCard(project: projects[index]);
                      },
                    ),
            ),
          ],
        ),
      ),
    );
  }
}

class _PersonProjectCard extends StatelessWidget {
  final Map<String, dynamic> project;

  const _PersonProjectCard({required this.project});

  @override
  Widget build(BuildContext context) {
    final mediaType = project['media_type']?.toString() ?? 'movie';

    final title = project['title'] ?? project['name'] ?? 'Unknown';

    final posterPath = project['poster_path']?.toString();

    final posterUrl = posterPath != null && posterPath.isNotEmpty
        ? 'https://image.tmdb.org/t/p/w185$posterPath'
        : null;

    final date = project['release_date'] ?? project['first_air_date'] ?? '';

    final year = date.toString().length >= 4
        ? date.toString().substring(0, 4)
        : '';

    final rating = project['vote_average'] is num
        ? (project['vote_average'] as num).toDouble()
        : 0.0;

    final character = project['character']?.toString().trim() ?? '';

    return Material(
      color: Colors.transparent,
      child: InkWell(
        borderRadius: BorderRadius.circular(16),
        onTap: () {
          final rawId = project['id'];

          if (rawId is! num) {
            return;
