class _EpisodeTile extends StatelessWidget {
  final int showId;
  final int seasonNumber;
  final int episodeNumber;
  final String title;

  final String? stillPath;
  final int? runtime;
  final double? rating;

  final String overview;
  final String? airDate;

  const _EpisodeTile({
    required this.showId,
    required this.seasonNumber,
    required this.episodeNumber,
    required this.title,
    required this.stillPath,
    required this.runtime,
    required this.rating,
    required this.overview,
    required this.airDate,
  });

  @override
  Widget build(BuildContext context) {
    final library = LibraryService.instance;

    final stillUrl = stillPath != null && stillPath!.isNotEmpty
        ? 'https://image.tmdb.org/t/p/w300$stillPath'
        : null;

    return AnimatedBuilder(
      animation: library,
      builder: (context, _) {
        final watched = library.isEpisodeWatched(
          showId,
          seasonNumber,
          episodeNumber,
        );

        return Padding(
          padding: const EdgeInsets.only(bottom: 8),
          child: Material(
            color: Colors.transparent,
            child: InkWell(
              borderRadius: BorderRadius.circular(14),

              onTap: () {
                Navigator.push(
                  context,
                  MaterialPageRoute(
                    builder: (_) => SwipeableEpisodePage(
                      showId: showId,
                      seasonNumber: seasonNumber,
                      episodeNumber: episodeNumber,
                      title: title,
                      stillPath: stillPath,
                      runtime: runtime,
                      rating: rating,
                      overview: overview,
                      airDate: airDate,
                    ),
                  ),
                );
              },

              child: Container(
                padding: const EdgeInsets.all(10),
                decoration: BoxDecoration(
                  color: watched
                      ? const Color(0xFF173A29)
                      : chipluxSurfaceLight,

                  borderRadius: BorderRadius.circular(14),

                  border: watched
                      ? Border.all(
                          color: const Color(0xFF7BE8A8).withValues(alpha: .22),
                        )
                      : null,
                ),

                child: Row(
                  children: [
                    ClipRRect(
                      borderRadius: BorderRadius.circular(10),

                      child: stillUrl != null
                          ? Image.network(
                              stillUrl,
                              width: 88,
                              height: 58,
                              fit: BoxFit.cover,

                              errorBuilder: (context, error, stackTrace) {
                                return _episodeFallback();
                              },
                            )
                          : _episodeFallback(),
                    ),

                    const SizedBox(width: 8),

                    Expanded(
                      child: Column(
                        mainAxisSize: MainAxisSize.min,

                        crossAxisAlignment: CrossAxisAlignment.start,

                        children: [
                          Text(
                            title,
                            maxLines: 2,
                            overflow: TextOverflow.ellipsis,

                            style: TextStyle(
                              fontSize: 15,
                              fontWeight: FontWeight.w600,

                              color: watched
                                  ? const Color(0xFF7BE8A8)
                                  : Colors.white,
                            ),
                          ),

                          const SizedBox(height: 7),

                          FittedBox(
                            fit: BoxFit.scaleDown,

                            alignment: Alignment.centerLeft,

                            child: Row(
                              mainAxisSize: MainAxisSize.min,

                              children: [
                                if (runtime != null) ...[
                                  const Icon(
                                    Icons.access_time_rounded,
                                    size: 15,
                                    color: Colors.white54,
                                  ),

                                  const SizedBox(width: 4),

                                  Text(
                                    '${runtime}m',
                                    style: const TextStyle(
                                      fontSize: 12,
                                      color: Colors.white54,
                                    ),
                                  ),
                                ],

                                if (runtime != null && rating != null)
                                  const Padding(
                                    padding: EdgeInsets.symmetric(
                                      horizontal: 8,
                                    ),
                                    child: Text(
                                      '•',
                                      style: TextStyle(color: Colors.white38),
                                    ),
                                  ),

                                if (rating != null) ...[
                                  const Icon(
                                    Icons.star,
                                    size: 16,
                                    color: Colors.amber,
                                  ),

                                  const SizedBox(width: 4),

                                  Text(
                                    '${rating!.toStringAsFixed(1)}/10',
                                    style: const TextStyle(
                                      fontSize: 12,
                                      color: Colors.white60,
                                    ),
                                  ),
                                ],
                              ],
                            ),
                          ),
                        ],
                      ),
                    ),

                    const SizedBox(width: 4),

                    IconButton(
                      constraints: const BoxConstraints(
                        minWidth: 34,
                        minHeight: 38,
                      ),

                      padding: EdgeInsets.zero,

                      onPressed: () async {
                        final bool wasWatched = watched;

                        final int previousEpisodeCount =
                            library.watchedEpisodeCount;

                        await library.toggleEpisode(
                          showId,
                          seasonNumber,
                          episodeNumber,
                          runtimeMinutes: runtime ?? 0,
                        );

                        if (!wasWatched && context.mounted) {
                          await _checkEpisodeAchievementUnlock(
                            context,
                            previousCount: previousEpisodeCount,
                            currentCount: library.watchedEpisodeCount,
                          );
                        }

                        if (wasWatched) {
                          await CriticService.instance.clearEpisodeAfterUnwatch(
                            showId: showId,
                            seasonNumber: seasonNumber,
                            episodeNumber: episodeNumber,
                          );

                          try {
                            await CommunityService.instance.deleteActivity(
                              activityType: 'rated',
                              mediaType: 'tv',
                              tmdbId: showId,
                              seasonNumber: seasonNumber,
                              episodeNumber: episodeNumber,
                            );

                            if (library.watchedCountForShow(showId) == 0) {
                              await CommunityService.instance.deleteActivity(
                                activityType: 'rated',
                                mediaType: 'tv',
                                tmdbId: showId,
                                titleLevelOnly: true,
                              );
                            }
                          } catch (e) {
                            debugPrint('Could not remove rating activity: $e');
                          }
                        }
                      },

                      icon: Icon(
                        watched
                            ? Icons.check_circle
                            : Icons.radio_button_unchecked,

                        color: watched
                            ? const Color(0xFF7BE8A8)
                            : Colors.white38,
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        );
      },
    );
  }

  Widget _episodeFallback() {
    return Container(
      width: 88,
      height: 58,

      alignment: Alignment.center,

      color: chipluxBackground,

      child: Text(
        'S${seasonNumber.toString().padLeft(2, '0')}\n'
        'E${episodeNumber.toString().padLeft(2, '0')}',

        textAlign: TextAlign.center,

        style: const TextStyle(
          fontSize: 10,
          color: chipluxCyan,
          fontWeight: FontWeight.bold,
        ),
      ),
    );
  }
}

class SwipeableEpisodePage extends StatefulWidget {
  final int showId;
  final int seasonNumber;
  final int episodeNumber;

  final String title;
  final String? stillPath;
  final int? runtime;
  final double? rating;
  final String overview;
  final String? airDate;

  const SwipeableEpisodePage({
    super.key,
    required this.showId,
    required this.seasonNumber,
    required this.episodeNumber,
    required this.title,
    required this.stillPath,
    required this.runtime,
    required this.rating,
    required this.overview,
    required this.airDate,
  });

  @override
  State<SwipeableEpisodePage> createState() => _SwipeableEpisodePageState();
}

class _SwipeableEpisodePageState extends State<SwipeableEpisodePage> {
  final TmdbService tmdb = TmdbService();

  final Map<int, List<Map<String, dynamic>>> _seasonEpisodeCache = {};

  late int _seasonNumber;
  late int _episodeNumber;

  late String _title;
  late String _showTitle;

  String? _stillPath;
  int? _runtime;
  double? _rating;
  late String _overview;
  String? _airDate;

  List<int> _seasonNumbers = [];

  bool _hasPrevious = false;
  bool _hasNext = false;

  bool _movingEpisode = false;

  int _transitionDirection = 1;

  @override
  void initState() {
    super.initState();

    _seasonNumber = widget.seasonNumber;

    _episodeNumber = widget.episodeNumber;

    _title = widget.title;

    _showTitle =
        LibraryService.instance.getItem(widget.showId, 'tv')?.title ?? '';

    _stillPath = widget.stillPath;

    _runtime = widget.runtime;

    _rating = widget.rating;

    _overview = widget.overview;

    _airDate = widget.airDate;

    unawaited(_prepareNavigation());
  }

  Future<void> _prepareNavigation() async {
    try {
      final details = await tmdb.getDetails(widget.showId, 'tv');

      final loadedShowTitle = details['name']?.toString().trim() ?? '';

      if (loadedShowTitle.isNotEmpty && mounted) {
        setState(() {
          _showTitle = loadedShowTitle;
        });
      }

      final rawSeasons = details['seasons'];

      final seasonNumbers = <int>[];

      if (rawSeasons is List) {
        for (final raw in rawSeasons) {
          if (raw is! Map) {
            continue;
          }

          final number = raw['season_number'];

          final count = raw['episode_count'];

          // Ignore Specials.
          if (number is num &&
              number.toInt() > 0 &&
              count is num &&
              count.toInt() > 0) {
            seasonNumbers.add(number.toInt());
          }
        }
      }

      seasonNumbers.sort();

      _seasonNumbers = seasonNumbers;

      await _refreshNavigation();
    } catch (e) {
      debugPrint('Could not prepare episode navigation: $e');
    }
  }

  Future<List<Map<String, dynamic>>> _episodesForSeason(
    int seasonNumber,
  ) async {
    final cached = _seasonEpisodeCache[seasonNumber];

    if (cached != null) {
      return cached;
    }

    final rawEpisodes = await tmdb.getSeasonEpisodes(
      widget.showId,
      seasonNumber,
    );

    final episodes = <Map<String, dynamic>>[];

    for (final raw in rawEpisodes) {
      if (raw is! Map) {
        continue;
      }

      final episode = Map<String, dynamic>.from(raw);

      if (episode['episode_number'] is! num) {
        continue;
      }

      episodes.add(episode);
    }

    episodes.sort((a, b) {
      final aNumber = (a['episode_number'] as num).toInt();

      final bNumber = (b['episode_number'] as num).toInt();

      return aNumber.compareTo(bNumber);
    });

    _seasonEpisodeCache[seasonNumber] = episodes;

    return episodes;
  }

  Future<void> _refreshNavigation() async {
    if (_seasonNumbers.isEmpty) {
      return;
    }

    final seasonIndex = _seasonNumbers.indexOf(_seasonNumber);

    if (seasonIndex < 0) {
      return;
    }

    final episodes = await _episodesForSeason(_seasonNumber);

    final episodeIndex = episodes.indexWhere((episode) {
      final number = episode['episode_number'];

      return number is num && number.toInt() == _episodeNumber;
    });

    final hasPrevious = episodeIndex > 0 || seasonIndex > 0;

    final hasNext =
        (episodeIndex >= 0 && episodeIndex < episodes.length - 1) ||
        seasonIndex < _seasonNumbers.length - 1;

    if (!mounted) {
      return;
    }

    setState(() {
      _hasPrevious = hasPrevious;

      _hasNext = hasNext;
    });
  }

  Future<void> _moveEpisode(int direction) async {
    if (_movingEpisode || _seasonNumbers.isEmpty) {
      return;
    }

    if (direction < 0 && !_hasPrevious) {
      return;
    }

    if (direction > 0 && !_hasNext) {
      return;
    }

    setState(() {
      _movingEpisode = true;
    });

    try {
      int targetSeason = _seasonNumber;

      Map<String, dynamic>? targetEpisode;

      final currentSeasonIndex = _seasonNumbers.indexOf(_seasonNumber);

      final currentEpisodes = await _episodesForSeason(_seasonNumber);

      final currentEpisodeIndex = currentEpisodes.indexWhere((episode) {
        final number = episode['episode_number'];

        return number is num && number.toInt() == _episodeNumber;
      });

      // ==========================
      // NEXT EPISODE
      // ==========================

      if (direction > 0) {
        if (currentEpisodeIndex >= 0 &&
            currentEpisodeIndex < currentEpisodes.length - 1) {
          targetEpisode = currentEpisodes[currentEpisodeIndex + 1];
        } else {
          int seasonIndex = currentSeasonIndex + 1;

          while (seasonIndex < _seasonNumbers.length) {
            final season = _seasonNumbers[seasonIndex];

            final episodes = await _episodesForSeason(season);

            if (episodes.isNotEmpty) {
              targetSeason = season;

              targetEpisode = episodes.first;

              break;
            }

            seasonIndex++;
          }
        }
      }

      // ==========================
      // PREVIOUS EPISODE
      // ==========================

      if (direction < 0) {
        if (currentEpisodeIndex > 0) {
          targetEpisode = currentEpisodes[currentEpisodeIndex - 1];
        } else {
          int seasonIndex = currentSeasonIndex - 1;

          while (seasonIndex >= 0) {
            final season = _seasonNumbers[seasonIndex];

            final episodes = await _episodesForSeason(season);

            if (episodes.isNotEmpty) {
              targetSeason = season;

              targetEpisode = episodes.last;

              break;
            }

            seasonIndex--;
          }
        }
      }

      if (targetEpisode == null) {
        if (mounted) {
          setState(() {
            _movingEpisode = false;
          });
        }

        return;
      }

      // From this point on,
      // the episode is guaranteed
      // to exist.
      final Map<String, dynamic> episode = targetEpisode;

      final rawEpisodeNumber = episode['episode_number'];

      if (rawEpisodeNumber is! num) {
        if (mounted) {
          setState(() {
            _movingEpisode = false;
          });
        }

        return;
      }

      final rawRuntime = episode['runtime'];

      final rawRating = episode['vote_average'];

      final double? newRating = rawRating is num && rawRating.toDouble() > 0
          ? rawRating.toDouble()
          : null;

      if (!mounted) {
        return;
      }

      setState(() {
        _transitionDirection = direction;

        _seasonNumber = targetSeason;

        _episodeNumber = rawEpisodeNumber.toInt();

        _title = episode['name']?.toString() ?? 'Episode';

        _stillPath = episode['still_path']?.toString();

        _runtime = rawRuntime is num ? rawRuntime.toInt() : null;

        _rating = newRating;

        _overview = episode['overview']?.toString() ?? '';

        _airDate = episode['air_date']?.toString();

        _movingEpisode = false;

        // Temporarily reset while
        // availability recalculates.
        _hasPrevious = false;

        _hasNext = false;
      });

      await _refreshNavigation();
    } catch (e) {
      if (!mounted) {
        return;
      }

      setState(() {
        _movingEpisode = false;
      });

      debugPrint('Could not change episode: $e');
    }
  }

  void _handleSwipe(DragEndDetails details) {
    final velocity = details.primaryVelocity ?? 0;

    // Ignore tiny accidental
    // horizontal movements.
    if (velocity.abs() < 250) {
      return;
    }

    // Finger moved LEFT.
    if (velocity < 0) {
      unawaited(_moveEpisode(1));

      return;
    }

    // Finger moved RIGHT.
    unawaited(_moveEpisode(-1));
  }

  @override
  Widget build(BuildContext context) {
    final episodeKey = '$_seasonNumber-$_episodeNumber';

    return GestureDetector(
      behavior: HitTestBehavior.translucent,
      onHorizontalDragEnd: _handleSwipe,
      child: Stack(
        children: [
          AnimatedSwitcher(
            duration: const Duration(milliseconds: 250),
            switchInCurve: Curves.easeOutCubic,
            switchOutCurve: Curves.easeInCubic,
            transitionBuilder: (child, animation) {
              final begin = Offset(_transitionDirection > 0 ? 0.08 : -0.08, 0);

              final position = Tween<Offset>(
                begin: begin,
                end: Offset.zero,
              ).animate(animation);

              return FadeTransition(
                opacity: animation,
                child: SlideTransition(position: position, child: child),
              );
            },
            child: EpisodeInfoPage(
              key: ValueKey(episodeKey),

              showId: widget.showId,

              showTitle: _showTitle,
              seasonNumber: _seasonNumber,
              episodeNumber: _episodeNumber,
              title: _title,
              stillPath: _stillPath,
              runtime: _runtime,
              rating: _rating,
              overview: _overview,
              airDate: _airDate,

              hasPreviousEpisode: _hasPrevious,

              hasNextEpisode: _hasNext,

              onPreviousEpisode: () {
                unawaited(_moveEpisode(-1));
              },

              onNextEpisode: () {
                unawaited(_moveEpisode(1));
              },
            ),
          ),

          if (_movingEpisode)
            Positioned(
              top: MediaQuery.paddingOf(context).top + 12,
              right: 18,
              child: const SizedBox(
                width: 18,
                height: 18,
                child: CircularProgressIndicator(strokeWidth: 2),
              ),
            ),
        ],
      ),
    );
  }
}

class EpisodeInfoPage extends StatelessWidget {
  final int showId;
  final String showTitle;

  final int seasonNumber;
  final int episodeNumber;

  final bool hasPreviousEpisode;
  final bool hasNextEpisode;

  final VoidCallback? onPreviousEpisode;

  final VoidCallback? onNextEpisode;

  final String title;
  final String? stillPath;
  final int? runtime;
  final double? rating;
  final String overview;
  final String? airDate;

  const EpisodeInfoPage({
    super.key,
    required this.showId,
    required this.showTitle,
    required this.seasonNumber,
    required this.episodeNumber,
    this.hasPreviousEpisode = false,
    this.hasNextEpisode = false,
    this.onPreviousEpisode,
    this.onNextEpisode,
    required this.title,
    required this.stillPath,
    required this.runtime,
    required this.rating,
    required this.overview,
    required this.airDate,
  });

  @override
