                    child: Align(
                      alignment: Alignment.centerLeft,
                      child: InkWell(
                        borderRadius: BorderRadius.circular(10),
                        onTap: hasPreviousEpisode ? onPreviousEpisode : null,
                        child: Padding(
                          padding: const EdgeInsets.symmetric(
                            vertical: 8,
                            horizontal: 4,
                          ),
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Icon(
                                Icons.chevron_left_rounded,
                                size: 20,
                                color: hasPreviousEpisode
                                    ? chipluxCyan
                                    : Colors.white24,
                              ),

                              const SizedBox(width: 2),

                              Text(
                                'Previous episode',
                                style: TextStyle(
                                  color: hasPreviousEpisode
                                      ? Colors.white60
                                      : Colors.white24,
                                  fontSize: 11,
                                  fontWeight: FontWeight.w600,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ),
                    ),
                  ),

                  Expanded(
                    child: Align(
                      alignment: Alignment.centerRight,
                      child: InkWell(
                        borderRadius: BorderRadius.circular(10),
                        onTap: hasNextEpisode ? onNextEpisode : null,
                        child: Padding(
                          padding: const EdgeInsets.symmetric(
                            vertical: 8,
                            horizontal: 4,
                          ),
                          child: Row(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              Text(
                                'Next episode',
                                style: TextStyle(
                                  color: hasNextEpisode
                                      ? Colors.white60
                                      : Colors.white24,
                                  fontSize: 11,
                                  fontWeight: FontWeight.w600,
                                ),
                              ),

                              const SizedBox(width: 2),

                              Icon(
                                Icons.chevron_right_rounded,
                                size: 20,
                                color: hasNextEpisode
                                    ? chipluxCyan
                                    : Colors.white24,
                              ),
                            ],
                          ),
                        ),
                      ),
                    ),
                  ),
                ],
              ),

              const SizedBox(height: 10),

              // =============================
              // TV SHOW LINK
              // =============================
              if (showTitle.trim().isNotEmpty) ...[
                Align(
                  alignment: Alignment.centerLeft,

                  child: Material(
                    color: Colors.transparent,

                    child: InkWell(
                      borderRadius: BorderRadius.circular(10),

                      onTap: () {
                        Navigator.push(
                          context,

                          MaterialPageRoute(
                            builder: (_) =>
                                MediaDetailsPage(id: showId, mediaType: 'tv'),
                          ),
                        );
                      },

                      child: Padding(
                        padding: const EdgeInsets.symmetric(
                          vertical: 5,
                          horizontal: 2,
                        ),

                        child: Row(
                          mainAxisSize: MainAxisSize.min,

                          children: [
                            Flexible(
                              child: Text(
                                showTitle,

                                maxLines: 1,

                                overflow: TextOverflow.ellipsis,

                                style: const TextStyle(
                                  color: chipluxCyan,

                                  fontSize: 14,

                                  fontWeight: FontWeight.w700,
                                ),
                              ),
                            ),

                            const SizedBox(width: 4),

                            const Icon(
