              SizedBox(
                width: double.infinity,
                child: ElevatedButton.icon(
                  onPressed: () async {
                    final bool wasWatched = watched;
                    final int previousEpisodeCount =
                        library.watchedEpisodeCount;

                    await library.toggleEpisode(
                      showId,
                      seasonNumber,
                      episodeNumber,
                      runtimeMinutes: runtime ?? 0,
                    );

                    if (!wasWatched && context.mounted) {
                      await _checkEpisodeAchievementUnlock(
                        context,
                        previousCount: previousEpisodeCount,
                        currentCount: library.watchedEpisodeCount,
                      );
                    }

                    if (wasWatched) {
                      await CriticService.instance.clearEpisodeAfterUnwatch(
                        showId: showId,
                        seasonNumber: seasonNumber,
                        episodeNumber: episodeNumber,
                      );

                      try {
                        await CommunityService.instance.deleteActivity(
                          activityType: 'rated',
                          mediaType: 'tv',
                          tmdbId: showId,
                          seasonNumber: seasonNumber,
                          episodeNumber: episodeNumber,
                        );

                        if (library.watchedCountForShow(showId) == 0) {
                          await CommunityService.instance.deleteActivity(
                            activityType: 'rated',
                            mediaType: 'tv',
                            tmdbId: showId,
                            titleLevelOnly: true,
                          );
                        }
                      } catch (e) {
                        debugPrint('Could not remove rating activity: $e');
                      }
                    }
                  },
                  icon: Icon(
                    watched ? Icons.check_circle : Icons.radio_button_unchecked,
                  ),
                  label: Text(watched ? 'Watched' : 'Mark as Watched'),
                  style: ElevatedButton.styleFrom(
                    padding: const EdgeInsets.symmetric(vertical: 14),
                    backgroundColor: watched
                        ? const Color(0xFF173A29)
                        : chipluxSurface,

                    foregroundColor: watched
                        ? const Color(0xFF7BE8A8)
                        : chipluxCyan,
                  ),
                ),
              ),

              if (watched) ...[
                const SizedBox(height: 14),

                SizedBox(
                  width: double.infinity,

                  child: OutlinedButton.icon(
                    onPressed: () {
                      final showTitle =
                          library.getItem(showId, 'tv')?.title ?? 'TV Show';

                      Navigator.push(
                        context,

                        MaterialPageRoute(
                          builder: (_) => CommentsPage(
                            onProfileTap: (userId) async {
                              await Navigator.push(
                                context,
