void showFavoriteBurst(BuildContext context) {
  final overlay = Overlay.maybeOf(context, rootOverlay: true);

  if (overlay == null) {
    return;
  }

  late OverlayEntry entry;

  entry = OverlayEntry(
    builder: (_) {
      return IgnorePointer(
        child: Material(
          color: Colors.transparent,
          child: TweenAnimationBuilder<double>(
            tween: Tween(begin: 0, end: 1),
            duration: const Duration(milliseconds: 850),
            curve: Curves.easeOutCubic,
            builder: (context, progress, child) {
              final double pop = math.sin(progress * math.pi);

              final double fade =
                  (1.0 - ((progress - 0.55) / 0.45).clamp(0.0, 1.0)).clamp(
                    0.0,
                    1.0,
                  );

              return Stack(
                fit: StackFit.expand,
                children: [
                  CustomPaint(
                    painter: _FavoriteBurstPainter(progress: progress),
                  ),

                  Align(
                    alignment: const Alignment(0, -0.05),
                    child: Opacity(
                      opacity: fade,
                      child: Transform.scale(
                        scale: 0.45 + pop * 0.85,
                        child: Container(
                          width: 110,
                          height: 110,
                          decoration: BoxDecoration(
                            shape: BoxShape.circle,
                            color: chipluxSurface.withValues(alpha: 0.92),
                            boxShadow: [
                              BoxShadow(
                                color: Colors.pinkAccent.withValues(
                                  alpha: 0.35,
                                ),
                                blurRadius: 40,
                                spreadRadius: 5,
                              ),
                            ],
                          ),
                          child: const Icon(
                            Icons.favorite_rounded,
                            size: 70,
                            color: Colors.pinkAccent,
                          ),
                        ),
                      ),
                    ),
                  ),
                ],
              );
            },
          ),
        ),
      );
    },
  );

  overlay.insert(entry);

  Future.delayed(const Duration(milliseconds: 950), () {
    if (entry.mounted) {
      entry.remove();
    }
  });
}

class _FavoriteBurstPainter extends CustomPainter {
  final double progress;

  const _FavoriteBurstPainter({required this.progress});

  @override
  void paint(Canvas canvas, Size size) {
    final center = Offset(size.width / 2, size.height * 0.47);

    final travel = Curves.easeOutCubic.transform(progress);

    final fade = (1.0 - ((progress - 0.55) / 0.45).clamp(0.0, 1.0)).clamp(
      0.0,
      1.0,
    );

    const colors = [
      Colors.pinkAccent,
      Color(0xFFFF5C72),
      Color(0xFFFF8A9A),
      chipluxPurple,
    ];

    const int count = 14;

    for (int i = 0; i < count; i++) {
      final angle = (math.pi * 2 / count) * i;

      final distance = 35 + travel * (90 + (i % 3) * 18);

      final position =
          center +
          Offset(math.cos(angle) * distance, math.sin(angle) * distance);

      final paint = Paint()
        ..color = colors[i % colors.length].withValues(alpha: fade);

      _drawHeart(canvas, position, 5.0 + (i % 3), paint);
    }
  }

  void _drawHeart(Canvas canvas, Offset center, double size, Paint paint) {
    final path = Path();

    path.moveTo(center.dx, center.dy + size);

    path.cubicTo(
      center.dx - size * 1.5,
      center.dy,
      center.dx - size,
      center.dy - size,
      center.dx,
      center.dy - size * 0.2,
    );

    path.cubicTo(
      center.dx + size,
      center.dy - size,
      center.dx + size * 1.5,
      center.dy,
      center.dx,
      center.dy + size,
    );

    canvas.drawPath(path, paint);
  }

  @override
  bool shouldRepaint(covariant _FavoriteBurstPainter oldDelegate) {
    return oldDelegate.progress != progress;
  }
}

void showCompletionBurst(BuildContext context) {
  final overlay = Overlay.maybeOf(context, rootOverlay: true);

  if (overlay == null) {
    return;
  }

  late OverlayEntry entry;

  entry = OverlayEntry(
    builder: (_) {
      return IgnorePointer(
        child: Material(
          color: Colors.transparent,
          child: TweenAnimationBuilder<double>(
            tween: Tween(begin: 0, end: 1),
            duration: const Duration(milliseconds: 950),
            curve: Curves.easeOutCubic,
            builder: (context, progress, child) {
              final fade = (1.0 - ((progress - 0.60) / 0.40).clamp(0.0, 1.0))
                  .clamp(0.0, 1.0);

              return Stack(
                fit: StackFit.expand,
                children: [
                  CustomPaint(
                    painter: _CompletionBurstPainter(progress: progress),
                  ),

                  Align(
                    alignment: const Alignment(0, -0.08),
                    child: Opacity(
                      opacity: fade,
                      child: Transform.scale(
                        scale: 0.65 + math.sin(progress * math.pi) * 0.35,
                        child: Container(
                          width: 64,
                          height: 64,
                          decoration: BoxDecoration(
                            shape: BoxShape.circle,
                            color: chipluxSurface,
                            border: Border.all(
                              color: const Color(0xFF7BE8A8),
                              width: 2,
                            ),
                            boxShadow: [
                              BoxShadow(
                                color: const Color(0xFF7BE8A8)
                                    .withValues(alpha: 0.30),
                                blurRadius: 25,
                                spreadRadius: 2,
                              ),
                            ],
                          ),
                          child: const Icon(
                            Icons.check_rounded,
                            color: Color(0xFF7BE8A8),
                            size: 38,
                          ),
                        ),
                      ),
                    ),
                  ),
                ],
              );
            },
          ),
        ),
      );
    },
  );

  overlay.insert(entry);

  Future.delayed(const Duration(milliseconds: 1050), () {
    if (entry.mounted) {
      entry.remove();
    }
  });
}

class _CompletionBurstPainter extends CustomPainter {
  final double progress;

  const _CompletionBurstPainter({required this.progress});

  @override
  void paint(Canvas canvas, Size size) {
    final center = Offset(size.width / 2, size.height * 0.46);

    const colors = [
      Color(0xFFFFC857),
      chipluxCyan,
      chipluxViolet,
      chipluxPurple,
      Color(0xFF7BE8A8),
    ];

    final travel = Curves.easeOutCubic.transform(progress);

    final fade = (1.0 - ((progress - 0.55) / 0.45).clamp(0.0, 1.0)).clamp(
      0.0,
      1.0,
    );

    // Expanding ring.
    final ringPaint = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 2
      ..color = const Color(0xFFFFC857).withValues(alpha: 0.45 * fade);

    canvas.drawCircle(center, 25 + 95 * travel, ringPaint);

    // Main particles.
    const particleCount = 28;

    for (int i = 0; i < particleCount; i++) {
      final angle = (math.pi * 2 / particleCount) * i;

      final variation = i.isEven ? 1.0 : 0.72;

      final distance = (45 + 130 * travel) * variation;

      final position =
          center +
          Offset(math.cos(angle) * distance, math.sin(angle) * distance);

      final color = colors[i % colors.length];

      final particlePaint = Paint()..color = color.withValues(alpha: fade);

      final radius = i % 3 == 0 ? 4.0 : 2.7;

      canvas.drawCircle(
        position,
        radius * (1 - progress * 0.25),
        particlePaint,
      );
    }

    // Shorter inner spark layer.
    const sparkCount = 14;

    for (int i = 0; i < sparkCount; i++) {
      final angle = (math.pi * 2 / sparkCount) * i + 0.20;

      final distance = 30 + 75 * travel;

      final start =
          center +
          Offset(math.cos(angle) * distance, math.sin(angle) * distance);

      final end =
          center +
          Offset(
            math.cos(angle) * (distance + 12),
            math.sin(angle) * (distance + 12),
          );

      final paint = Paint()
        ..strokeWidth = 2.2
        ..strokeCap = StrokeCap.round
        ..color = colors[(i + 1) % colors.length].withValues(
          alpha: 0.75 * fade,
        );

      canvas.drawLine(start, end, paint);
    }
  }

  @override
  bool shouldRepaint(covariant _CompletionBurstPainter oldDelegate) {
    return oldDelegate.progress != progress;
  }
}

class _RatingEffectStar extends StatefulWidget {
  final bool filled;
  final int pulseToken;
  final double size;
  final bool enabled;

  const _RatingEffectStar({
    required this.filled,
    required this.pulseToken,
    required this.size,
    this.enabled = true,
  });

  @override
  State<_RatingEffectStar> createState() => _RatingEffectStarState();
}

class _RatingEffectStarState extends State<_RatingEffectStar>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller;

  @override
  void initState() {
    super.initState();

    _controller = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 260),
    );
  }

  @override
  void didUpdateWidget(covariant _RatingEffectStar oldWidget) {
    super.didUpdateWidget(oldWidget);

    // Whenever the rating changes,
    // animate every currently
    // filled star.
    if (widget.pulseToken != oldWidget.pulseToken && widget.filled) {
      _controller.forward(from: 0);
    }
  }

  @override
  void dispose() {
    _controller.dispose();

    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _controller,
      builder: (context, child) {
        final double t = _controller.value;

        final double pulse = math.sin(t * math.pi);

        final double shake = math.sin(t * math.pi * 5) * (1 - t) * 2.3;

        final double scale = 1 + pulse * 0.18;

        return Transform.translate(
          offset: Offset(shake, 0),
          child: Transform.scale(
            scale: scale,
            child: SizedBox(
              width: widget.size + 16,
              height: widget.size + 16,
              child: Stack(
                alignment: Alignment.center,
                children: [
                  // Tiny sparkle burst.
                  if (_controller.isAnimating)
                    CustomPaint(
                      size: Size.square(widget.size + 16),
                      painter: _RatingStarSparkPainter(progress: t),
                    ),

                  // Soft glow.
                  if (widget.filled)
                    Container(
                      width: widget.size * 0.62,
                      height: widget.size * 0.62,
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        boxShadow: [
                          BoxShadow(
                            color: Colors.amber.withValues(
                              alpha: 0.10 + pulse * 0.28,
                            ),
                            blurRadius: 13 + pulse * 7,
                            spreadRadius: pulse * 2,
                          ),
                        ],
                      ),
                    ),

                  Icon(
                    widget.filled
                        ? Icons.star_rounded
                        : Icons.star_border_rounded,
                    size: widget.size,
                    color: widget.filled
                        ? Colors.amber
                        : widget.enabled
                        ? Colors.amber
                        : Colors.white24,
                  ),
                ],
              ),
            ),
          ),
        );
      },
    );
  }
}

class _RatingStarSparkPainter extends CustomPainter {
  final double progress;

  const _RatingStarSparkPainter({required this.progress});

  @override
  void paint(Canvas canvas, Size size) {
    final center = Offset(size.width / 2, size.height / 2);

    final double opacity = math.sin(progress * math.pi) * 0.85;

    final double distance = 17 + progress * 9;

    const colors = [Color(0xFFFFC857), Colors.amber, Colors.white];

    for (int i = 0; i < 6; i++) {
      final angle = (math.pi * 2 / 6) * i;

      final point =
          center +
          Offset(math.cos(angle) * distance, math.sin(angle) * distance);

      final paint = Paint()
        ..color = colors[i % colors.length].withValues(alpha: opacity);

      canvas.drawCircle(point, 1.8 * (1 - progress * 0.35), paint);
    }
  }

  @override
  bool shouldRepaint(covariant _RatingStarSparkPainter oldDelegate) {
    return oldDelegate.progress != progress;
  }
}
